-- GENERATED by `wfj generate` from data/quest/quest-0003.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [3000] = { "Tome of Divinity", "IronforgeのTiza Battleforgeに話しかけて下さい。", "こんにちは、{name}。Azerothの人々を助けるのに忙しいのは分かっていますが、時間ができたらIronforgeへ戻り、あなたの故郷で最も尊敬されているパラディンの一人、Tiza Battleforgeと話すといいでしょう。若いドワーフのパラディンたちが、光について、そして私たち皆に求められていることについてさらに学ぶ時が来たときに訪ねるのが彼女なのです。\n\n彼女はMystic WardにあるHall of Mysteriesの上の階にいます。", nil, "{name}よ、そなたに挨拶し、歓迎しよう。", 0x85861feb, 0x04be03fc, 0x3dc4f4ac, nil, 0x35f6641b, "...m." },
  [3001] = { "Strahadを捜して", "RatchetのStrahad Farsanを見つけて下さい。", "私はこれまでお前に技を教えてきたが、別の者が教える時が来た。その者はRatchetにいて、名をStrahadという。人間だが、それで弱いと思い込むな。お前の敵でもない……少なくとも今のところはな。彼は強大な力を持ち、敬意を払うべき相手だ。より上位の召喚術について教えてくれるだろう。お前にはもうその準備ができていると私は感じている。今すぐ彼のもとへ行け。\n\n彼はRatchetにいる……そこの港町の上、塔の隣だ。", nil, "Ratchetは今日も賑わっているな。港町の営みを眺めるのは実に楽しい。謎に満ち、冒険に満ち……そして無知に満ちている。\n\nその目に見えるのは憎しみか、{name}？よろしい、それは有効に使わせてもらおう。", 0x884bfbbe, 0x8ee66c11, 0xb6f535c4, nil, 0x44d961f5, "...m." },
  [3002] = { "Gordunni Orb", "OrgrimmarのDarkbriar LodgeにいるUthel'nayに、Gordunni Orbを渡して下さい。", "敵のことはよく知っているが、私はウォリアーだ、{name}。このオーブに何ができるのか、見当もつかん。\n\nOrgrimmarに、このオーブについてもっと詳しく教えてくれるメイジがいる。それを彼のところへ持って行ってくれ。", "何を持ってきた、{race}?", "実に興味深い、{name}……\n\nこのオーブは非常に強力だが、同時に非常に危険でもある。", 0xe3823ff5, 0xeb70cf0b, 0x72c4d28d, 0xfb96e30e, 0xd7de6a56, "....." },
  [3022] = { "取り扱い注意", "Carefully-packed CrateをRut'theran VillageのErelas Amberskyのところへ持って行って下さい。", "{name}、君が私の価値ある大義に身を捧げたいと願っているのが分かる。ああ、もちろん、君に頼めることがあるよ！\n\nこの卵の箱をErelas Amberskyのところへ届けてくれ。彼はこの卵の世話をしているドルイドで、卵がかえるのを手伝い、若いhippogryphsを育てているんだ。Teldrassilの、南にあるRut'theranという小さな村にいるよ。", "またCurgleからの荷物だろう?", "手伝ってくれてありがとう、{name}。私たちがいなければ、hippogryphの数が増えることはまずないだろう。ああ、だが君もFeralasへ行って、Gordunniによる荒廃を目にしたのだから、よく分かっているだろうね。\n\nさて、見てのとおり私はここで仕事に追われているから、君はそろそろ行ったほうがいい。\n\nもう一度ありがとう、{name}。", 0x69b638db, 0x3764b408, 0xe03666ec, 0x5b1259d0, 0x7896e98a, "....." },
  [3042] = { "Troll Temper", "Vial of Troll Temper 20本をGadgetzanのTrenton Lighthammerに渡して下さい。", "Zul'FarrakのSandfuryのトロールたちは砂岩から焼き入れ剤を作っていてな、そいつを使えば俺の作る品に焼き入れができるんだ、ああ、できるとも! 目利きの連中にはたいそう重宝されてるから、その焼き入れ剤をたっぷり持ってきてくれたら、たんまり礼をするよ。\n\nZul'FarrakはGadgetzanの北西だ。幸運を。", "temperは持ってきてくれたか、{name}?", "ああ、これは実に良いtemperだ！しかもこんなにたくさん！使い切るまで何日も仕事ができるぞ！\n\nありがとう、{name}。これを支払いとして受け取ってくれ。", 0xc905c5a9, 0xa028d7d0, 0x8e83f55c, 0x0bfb6765, 0x63047f86, "....." },
  [3062] = { "暗黒の心臓", "Camp MojacheのTalo Thornhoofは、Edana Hatetalon's Dark Heartを求めています。", "Edana Hatetalonは、西の廃墟に棲むNorthspringのharpiesの女王だ。あれは純然たる悪だ。その心臓は水晶でできていると聞く。他のすべての者に向ける憎しみ以外、あらゆる感情を持たない。Edanaと対決し、その黒い心臓を持ち帰ってくれ。\n\nharpiesが持ち歩いている角笛のことを聞いたことがある――廃墟の北側にあるHatetalonの石のそばでそれを吹けば、女王を呼び出せるそうだ。\n\n自分を呼んでいるのが同族ではなく、自らの死だと知ったとき、奴はどれほど驚くことだろうな。", "Edanaが大地に撒き散らす憎しみを止めねばならない。", "Edanaが本当に死んだと今分かったよ。この心臓……君が私のためにここでやってくれたことの記念として、とっておくつもりだ、{name}。どうもありがとう。", 0x9af68453, 0x1b081601, 0xab66d8bb, 0x57530bb3, 0xf3df6cce, "....." },
  [3063] = { "Northspring族への復讐", "Talo Thornhoofは、Northspring Harpies・Northspring Roguefeather・Northspring Windcaller・Northspring Slayerをそれぞれ4匹ずつ殺すよう求めています。", "若い頃、俺は熟練のハンターだった。恐れる生き物などいなかった。あの時までは……\n\n厳しい戦いの後、森で刃を研いでいたところを待ち伏せされたんだ。harpiesに囲まれて、なんとか安全な所まで這って逃げるのがやっとだった。\n\n今でも、奴らの叫び声がこだまするのが聞こえる……\n\nそれ以来、俺は変わってしまった。だが憎しみが腹の中で煮えたぎっている――何年経とうと、借りは返さねばならん。\n\nNorthspringのharpiesは、ここから西にいる。{name}、俺の仇を討ってくれ。", "Northspring harpiesの翼は夜のように黒い。目を離すな、さもなくば闇に消えてしまうぞ。", "ありがとう、{name}。君は老いたトーレンの心を安らかにしてくれたよ。", 0x38e02ae5, 0x31867a8e, 0xf1f40184, 0xc2525972, 0x64f65ca4, "....." },
  [3065] = { "Simple Tablet", "Simple Tabletを読み、Valley of TrialsのFrangに話しかけて下さい。", "ああ、君が留守の間に、君宛ての羊皮紙が届いたよ、{name}。\n\n時間のあるときに読んでくれ。私の思い違いでなければ、ウォリアーのトレーナー、Frangからのものだ。準備ができたら、君に話があるそうだ。Denの外で、日陰に隠れているはずだよ。", "隊列を固める{race}がまた一人か。俺にはそれで十分だ。\n\n斧のような良い武器を振るうのは骨が折れるだろうが、槍だってほかの何にも劣らんぞ。\n\nValley of Trialsへようこそ。", "{class}の道において訓練を続けるにつれ、ここはぴったりだと分かるだろう。疑問があるなら、気軽に周りの誰かに聞くといい。準備がととのったと思ったら、訓練に戻ってくるのだぞ。俺はこの谷にいる他の{class}と同じくらい、技を習得してきた。だからその知識をお前にも渡してやれるんだ……有料でな。", 0x1de75c3d, 0x70d6f7de, 0xb9d4e50a, 0x3a60c097, 0x79d5a027, "....." },
  [3082] = { "Etched Tablet", "Valley of TrialsのJen'shanに話しかけて下さい。", "ああ、君が留守の間に、君宛ての石板が届いたよ、{name}。\n\n時間のあるときに読んでくれ。私の思い違いでなければ、ハンターのトレーナー、Jen'shanからのものだ。準備ができたら、君に話があるそうだ。", "Jen'shanの前には強きハンターがいて、精霊たちもそれを認めてる。\n\nハンターの道は、あたしらの一番古い生き方の1つさ。HordeがAzerothで生き延びるのに必死だったころ、奴らはあたしらを頼って、教えてくれ、いろんなことの秘密を見せてくれと頼んだ。奴らはもう強かった。シャーマンの道でも強く、ウォリアーの道でも強かった。けど、ハンターの道は奴らの道じゃなかった……そのころはね。", "今、あたしらはあいつらにそういうことを教え、あいつらはあたしらに別のことを教える。あたしら、ひとつの種族になる……ほとんどな。あたしら、もう長いこと同盟者だ。だから、あいつらを助けること忘れるな。そうすりゃ、Jen'shanもお前を助けること忘れない。\n\nJen'shanがお前にハンターの道を教える。しっかり教える。忘れるな、ハンターは部族にとても尊敬されてる。お前、この先大きな役目を担うことになる……それ忘れるな。\n\n必要を感じたら、Jen'shanのところへ来い。お前の準備ができたと感じたら、Jen'shanができるだけのこと教える。", 0x5f30637e, 0xd78d7114, 0x1cb5c31f, 0xd3da7216, 0xbd0588a5, "....." },
  [3083] = { "Encrypted Tablet", "Encrypted Tabletを読み、Valley of TrialsのRwagに話しかけて下さい。", "ああ、君が留守の間に、君宛ての石板が届いたよ、{name}。\n\n時間のあるときに読んでくれ。私の思い違いでなければ、ローグのトレーナー、Rwagからのものだ。準備ができたら、君に話があるそうだ。", "Valley of Trialsへようこそ、{name}。俺のtabletを手に入れていなければ、お前はここにいないはずだ。だから単刀直入に言おう。\n\n俺はRwag、このValleyでローグ、盗賊、スリどもを鍛える役目を負っている。お前にこれから起こることへの備えができていなければ、Handが頼るのは俺だ。だが心配するな、Handがお前のやることを全部支配するわけじゃない。とはいえ、奴らがお前の才能を必要とするなら、手を組むのが賢明だろうな。", "然るべき時が来るまで、お前さんは俺の監督下にある。みんなが言うような「コツ」を教えてやろう。用意ができたと感じたらいつでも、俺のところへ戻ってくるんだ。もっと訓練できるか調べてやろう。それまでは、技を磨き、技の切れ味を研ぎ澄ますよう研ぎ続けておくことだ。最も些細な能力でさえ、いつ必要になるか分からんからな。", 0xf26f0369, 0x4028c542, 0x4649a294, 0x63ebe82c, 0x41da7694, "....." },
  [3084] = { "Rune-Inscribed Tablet", "Valley of TrialsのShikrikに話しかけて下さい。", "あぁ、君がいない間に石板が届いたよ、{name}。\n\n時間があったら、それを読んでみてくれたまえ。たしか、シャーマントレーナーのShikrikから受け取ったものだ。彼女は君が来るのを待っている。", "おお、よく来た、{name}。着いてくれて嬉しいぞ。教える生徒が大勢いて、わしの毎日は長く、忙しくさえなった。だが、お前のような者が1人来てくれると、大きな達成感を覚える……わしも昔、お前たちのシャーマンの1人に教わった日々を覚えているからな。", "おそらく知っているだろうが、エレメントが我らに力を与えてくれる。火、大地、水、そして風――これらが我らの道具だ。\n\n我らの強さは祖先の霊から来る。我らは民を導く者だ。ThrallがHordeにとってそうであるように、我らも訪れる村や町にとってそうあらねばならぬ。人々は知恵と守りを我らに求めるだろう。より備えるためには、たびたび修練を積まねばならぬ。さらなる力を得たと感じたら、我のもとへ来るがよい。教えられることを教えよう。", 0x57135a67, 0xaa674223, 0x7a1980af, 0xc763b8e8, 0x0bb859af, "....." },
  [3085] = { "Hallowed Tablet", "Hallowed Tabletを読み、Valley of TrialsのDenの外にいるKen'jaiに話しかけて下さい。", "ああ、君が留守の間に、君宛ての石板が届いたよ、{name}。\n\n時間のあるときに読んでくれ。私の思い違いでなければ、プリーストのトレーナー、Ken'jaiからのものだ。準備ができたら、君に話があるそうだ。", "よう、来たな……いいぞいいぞ! 精霊たちが、お前がそのうちKen'jaiに会いに来るって教えてくれたんだ。Valley of Trialsへお前を最初に迎える者の1人にならせてくれよ。ここがお前の家なのも長くはないが、そのあいだは精一杯楽しむといい。", "己を試していけば、霊たちをますますうまく操れるようになると分かるだろう――もっともっと大きなことを霊に求めるようになる……そこでこのKen'jaiの出番だ。用意ができたと感じたら、このKen'jaiのところへ話しに来い。霊たちが認めれば、もっと強い力を教えてやることも考えよう……だが、霊たちが認めたときだけだ。\n\nさあ行け、Valleyの他の者たちと話してこい。また後で私に話しかけるがいい。", 0xcbf1c524, 0xc36df6ef, 0x3e34c39a, 0x2b9a89b9, 0x5fe35355, "....." },
  [3086] = { "Glyphic Tablet", "Glyphic Tabletを読み、Valley of TrialsのDen入口付近にいるMai'ahに話しかけて下さい。", "ああ、君が留守の間に、君宛ての石板が届いたよ、{name}。\n\n時間のあるときに読んでくれ。私の思い違いでなければ、メイジのトレーナー、Mai'ahからのものだ。準備ができたら、君に話があるそうだ。", "もうMai'ahを喜ばせようとしてるね、{name}。そいつはいい。Mai'ahに敬意を払えば、Mai'ahもお前に敬意を返すかもしれない。けど、その話はもういい。お前は魔法を学びに来たんで、Mai'ahのおしゃべりを聞きに来たんじゃない。\n\nMai'ahがお前に魔法について教えられないことは、たった1つしかないよ、{name}。それは堕落を止める方法さ。", "お前はこの世界で最も強い者たちの一人だ、{name}……それは間違いない。誰もがそれを知っている……よく知っているとも！\n\nだが用心せねばならん！恐れるべきはオークでもエルフでもドワーフでもない……目に見えぬものたちだ。魔法は強い。望まぬことをさせる。実際より強くなったと思わせる。焦るな。賢くあれ。\n\n修行の用意ができたと思ったら、Mai'ahのところへ戻ってこい。お前が学べることを教えてくれるはずだ、何の問題もない。", 0x2f8b4832, 0xdeaadea8, 0x57f2c952, 0x3b28c8b6, 0xc911bdb3, "....." },
  [3087] = { "Etched Parchment", "Etched Parchmentを読み、Valley of TrialsのJen'shanに話しかけて下さい。", "ああ、お前さんはいなかったが文書が届いたんだよ、{name}。\n\n時間のある時に読んでくれ。俺の勘違いでなければ、その文書はハンタートレイナーのJen'shanからのだ。お前さんの都合がつく時にでも、話があるのだろう。", "ああ、やっと来たね。いいよ。Jen'shanはお前を待ってた。\n\n多くの者は楽な道だと思ってるが、Jen'shanはそうじゃないって言うよ。Durotarやその先の獣たちを使いこなすには、秘術を極めたり祖先と話したりするのと同じだけの腕がいるんだ。\n\n弓や銃を撃つのは、呪文を唱えるほどお前にとって危なくはないかもしれない。けど、敵にとっては確かに同じくらい危ないのさ。", "話し終わったら、この谷のもんと話したほうがいい。皆あんたにやってもらうことがある……やってもらうことってのは、あんたの腕を試し、この土地の危険を教えることだろうね。\n\n経験や知識で成長するに従って、より良いテクニックやスキルを見せてあげなきゃな。ちょくちょくあたしのとこへ戻っておいで。教えられることを教えてあげよう。", 0x923579a2, 0x48d60d22, 0xfba32734, 0x0569874c, 0x7c765b06, "....." },
  [3088] = { "Encrypted Parchment", "Encrypted Parchmentを読み、Valley of TrialsにいるRwagに話しかけて下さい。", "ああ、君のいない間に羊皮紙がやって来たよ、{name}。\n\n時間のある時に読みな。俺の勘違いでなければ、それはローグトレーナーRwagからのだ。君の準備が整ったら、話がしたいのだろうよ。", "しーっ、声が大きい。あそこにいるNartokは信用できん。俺よりも洞窟の奥に隠れなきゃならん奴は、甘く見ちゃいけない。\n\n道に迷うことはなかったろうな?", "俺のいる場所を知ったからには、教えなきゃならんな。Shattered Handがお前を探すよう依頼してきたのだ。お前を訓練し、必要な情報をすべて与え続けるようにと彼らは望んでいる。彼らを手助けすることにまだ興味がなくても……興味を持たないなんて馬鹿のすることだがな……俺は教えられることを教えよう……ほんのわずかな料金でな。準備ができたと思ったらいつでも俺のところへ戻ってこい。身につけられるようになった技を調べてやろう。", 0xccd2a2af, 0x62ff2435, 0xf5942fa0, 0x2656277a, 0xdb3c2ab9, "....." },
  [3089] = { "Rune-Inscribed Parchment", "Rune-Inscribed Parchmentを読み、Valley of TrialsにいるShikrikに話しかけて下さい。", "ああ、君のいない間に羊皮紙がやって来たよ、{name}。\n\n時間のある時に読みな。俺の勘違いでなければ、それはシャーマントレーナーShikrikからのだ。君の準備が整ったのなら、話がしたいのだろうよ。", "来たか。いつ姿を見せるのかと思い始めていたところだ。parchmentを送ったのはだいぶ前で、届いたかどうか分からなかった。\n\nだがおしゃべりはここまでだ……お前がここにいるのは選ばれたからだ。我らが民の魂の営みを導く者として選ばれたのだ。", "祖霊と交信する時にはパイプとなるのです。あなたは意のままに精霊の力を手にできましょう。敵を切り裂くのも児戯に等しく、仲間を治癒するのも呼吸と同じくらい容易くなるでしょう。新たな困難に直面した時には、このことを気にとめておくのです。そして、好きな時に私のところへ戻ってくるのですよ。新しい呪文を教え、準備が整ったならば正しき道へと導くべく、私はずっとここにいますよ。", 0xb7d19e20, 0x38687a84, 0x4edad387, 0xa3f65b21, 0xb34f759d, "....." },
  [3090] = { "Tainted Parchment", "Tainted Parchmentを読み、Valley of TrialsのDenにいるNartokに話しかけて下さい。", "ああ、君が留守の間に羊皮紙が届いていたよ、{name}。\n\nできればウォーロックとは関わらないようにしているんだが、時間のあるときに読んでおくといい。私の思い違いでなければ、君の新しく決まったトレーナー、Nartokからのものだ。準備ができたら話があるそうだ。", "ようやく来たか……しかも人目につかずにな。いいぞ。\n\nこの世界は愚か者だらけだ、{name}。偉大なるThrallでさえ、たいていの者が見抜けないほど大きな欠点を抱えている。奴はこの地を完全に我らのものにするのに必要な力に背を向けているのだ! 我々はもう、Netherの生き物どもに操られ利用されていた頃の民ではない。我々は我々自身の民だ。誇り高く……そして強い。", "これでお前も仲間入りだ。誤解するなよ、{name}。皆が羨むような力に触れられるからといって、容易に受け入れられたわけじゃない。ThrallがOrgrimmarに入ることを我らに許したのは、仲間の血縁だからだ……Thrallは我らを見捨てることはできぬ。でなければ、Thrallを奴隷にした人間どもと同じくらい情けないことになるだろうよ。要するにだ、気をつけろ。お前は強くなれる、しかし愚かならば、死んだも同然だ。魔法の訓練が必要なら俺のところへ戻ってこい。", 0xaf2d0c7f, 0x3d7f7224, 0x01fe275d, 0xcc951811, 0x2b34a4b3, "....." },
  [3091] = { "Simple Note", "Simple Noteを読み、Camp NaracheのHarutt Thunderhornに話しかけて下さい。", "ついさっき、メッセンジャーがお前を捜していたぞ、{name}。ウォーリアトレーナーのHaruttに寄越されたんだと思う。この手紙がHaruttからのものなら、俺だったら読むのに時間をかけないね。", "ああ、ようやく来たな、{class}。noteに書いたことに嘘はないぞ、{name}。我々もまた、部族のドルイドやシャーマンに劣らぬ特別な者たちなのだ。お前も彼らと同じく大切な存在だ。境界を守り、centaurを狩り、戦に赴くよう求められるのは我々なのだ。", "我々ひとりひとりが部族での役割を果たしているんだ。皆、同じ儀式も経験しなければならない。君のプライドに、そうではないなどと決して言わせるな。\n\n俺はここで新たな戦士に、戦いの栄光を求め古き祖先の歩んだ道に続くよう訓練している。準備ができたと思ったら、戻ってくるんだぞ。もっと稽古をつけてあげよう。部族の祝福とともに進め、{name}。", 0x14ead102, 0x3a12e673, 0xe0460976, 0xa6b0edf0, 0xb1121bc2, "....." },
  [3092] = { "Etched Note", "Etched Noteを読んで、Red Cloud MesaのLanka Farshotに話しかけて下さい。", "ついさっき、メッセンジャーがお前を捜していたぞ、{name}。彼女は確か、ハンタートレイナーのLankaに寄越されたんだと思う。この手紙がLankaからのものなら、俺だったら読むのに時間をかけないね。", "Camp Naracheへようこそ、{name}。お前の良い評判は聞いている。お前の血筋は強く、長老たちの多くはお前がすでに腕が立つと見ている。だが、それは我々が試すことだ。\n\nMulgoreの平原はしばらくお前の家となる。できる限りよく知っておくがいい。いつの日か、お前はより大きな技を極めるために見知らぬ地へ旅立つだろう。その備えをしておかねばならぬ。", "ペットの飼い慣らし方、ライフル銃の撃ち方、必要となるであろう数多くの技……そういった狩人としての基礎を君に教え、確実に鍛えあげることが私の使命なのだよ。\n\n狩人は我々の伝統と歴史において強い役割を担ってきたのだ、{name}。君が部族にとってどれだけ重要かを覚えておくといいだろう。皆のために役立てば、君は尊敬され、称賛されるだろう。", 0x9c2dae5c, 0xed672d15, 0x78d5882a, 0x6c84c2d0, 0xbd639c75, "....." },
  [3093] = { "Rune-Inscribed Note", "Rune-Inscribed Noteを読み、Camp NaracheのMeela Dawnstriderに話しかけて下さい。", "ついさっき、メッセンジャーがお前を捜していたぞ、{name}。シャーマントレーナーのMeelaに寄越されたんだと思う。この手紙がMeelaからのものなら、俺だったら読むのに時間をかけないね。", "空から雨が落ちるほどの速さで、お前は私の前に現れた。その素早さを嬉しく思う。それは、我々が会うことの大切さと、お前がここにいることの大切さを、どちらも分かっているということだ。私は指導者ではないが、精霊の力を理解し、我らが民の霊と話すことができる。お前にも同じことができるよう教えよう。", "これから私たちは何度もお会いすることになりましょう。会うたびに、あなたが少しずつ力をつけ……少しずつ備えを整えて私のもとを去っていくことを願っています。Eternal Flameのように、あなたの魂は眩しく輝き熱く燃えていますから。\n\n今すぐ行くのです、{name}。行って己自身を試すのです。必要な時には、私はここにいますよ。", 0x3d99c971, 0x05a28553, 0xa97f9159, 0x8b98605c, 0xb586e860, "....." },
  [3094] = { "Verdant Note", "Verdant Noteを読み、Camp NaracheのGart Mistrunnerと話して下さい。", "ちょうどついさっき、使者が君を捜してたぞ、{name}。ドルイドトレーナーのGartから使わされたに違いない。この手紙がGartからのものなら、俺だったら読むのに時間をかけないね。", "来ましたね。それは良いことです。Mulgoreとその先のいたるところで、私たちの祖先の霊が落ち着かなくなっていますが、その理由が私には分かりません。自然の霊に耳を傾けることを学び、その化身として行動することが、これからずっとあなたの務めとなります。そのことを心に留めておきなさい。", "我々とナイトエルフとは共通の絆を持っているけれど、ナイトエルフたちから歓迎されることは期待してはいけない。彼らの誇りが今も彼らの視野を狭めている。しかし、それは私たちに関係のないことだ。Earthmotherの教えすべてに関心を持たねばならない。智恵を伸ばしたいのならば伸ばしたいだけ、知っていることを何でも教えよう。\n\nちょくちょく私のところへ来なさい、{name}。Earthmotherは最も熱心な者に奇跡の力を与えて下さるのだと分かるはずだ。", 0x183c3d84, 0x92cc1324, 0x227a33b2, 0xe544de60, 0xae67cb54, "....." },
  [3095] = { "Simple Scroll", "Simple Scrollを読み、DeathknellのDannal Sternに話しかけて下さい。", "ああ、お前が愚かなScourgeに対処している間に、この巻物が届いたぞ。ウォーリアトレーナーDannalの印があるところを見ると、何か大事なことなんだろう。俺だったら、出発前にもう一度読む時間をとる。", "ああ、来たか。いいだろう。ほかにも何人かが「死」から逃れて町へ向かっていると耳にした。その粘り強さも、いずれ役に立つかもしれんな。\n\n自由を得られたことはSylvanasに感謝するがいい……心と体の自由をな。お前はまだ疫病とその影響に苦しめられているが、今は好きなように行き来できる身だ。", "経験を積んで成長していく間、俺はここで稽古をつけてやる……好きな時にいつでも来い。ちょっとばかし料金はもらうが、俺の教えることすべて値打ちがあると分かるはずだ。\n\n出ていって腕試しをしてこい。経験を積むにつれてもっと多くのことを学べるようになる。そのうちのいくつかは、ここで教えてやることはできないがね。将来、お前のような強さを持つ戦士をSylvanas様が必要となさるということだけは知っておけ。我らの救済の後ろ盾となるのだ。それを忘れるなよ。", 0x47a42397, 0xab7828aa, 0xac9ea6e5, 0x3d4cd994, 0x26098b59, "....." },
  [3096] = { "Encrypted Scroll", "Encrypted Scrollを読み、DeathknellのDavid Triasに話しかけて下さい。", "ああ、君が知性のないScourgeに対処している間に、この巻物が届いたよ。ローグトレーナーDavid Triasの印があるところを見ると、何か大事なことなんだろう。俺だったら、出発前にもう一度読む時間をとるよ。", "たどり着いたか? いいだろう、この先ますますローグが必要になる。時が来たと判断すれば、Shadowstalkersのほうからお前を見つけ出すだろう。だからしくじったり、後悔するようなことはするなよ。奴らが必要としているのは腕の立つ工作員だ……スリや愚か者じゃない。", "俺はこの宿で新顔を探し、有望な者を記録し続けることだけに時間のほとんどを費やしている。面倒は起こすなよ。教えられることはわずかだが、教えてやる。いつでも好きな時に戻ってくればいい。新しい技か何かを身につけられるかどうか、調べてやろう。", 0x1c2bcac8, 0xcefbc41c, 0x080b8339, 0x390c2af2, 0xe51c548c, "....." },
  [3097] = { "Hallowed Scroll", "Hallowed Scrollを読み、Deathknellの教会にいるDark Cleric Duestenに話しかけて下さい。", "ああ、君が知性のないScourgeに対処している間に、この巻物が届いたよ。プリーストトレーナーDuestenの印があるところを見ると、何か大事なことなんだろう。俺だったら、出発前にもう一度読む時間をとるよ。", "ああ、炎に疫病、暴動、そしてもっとひどいものの合間を縫って、また一人「信心深い者」が私の戸口にやってきたか。では、歓迎しよう、{class}。そして、何がお前を突き動かしているにせよ、それを探しに行く時だと決める前に、一つ二つ説明させてもらおう。聖なる光はもはやお前とは関わりがない。祖先の霊などおとぎ話にすぎない。そしてNetherから来る者どもはお前を求めてはいない。\n\nここまでは分かったか？", "お前が知っておくべきことはただ一つだ。我々は意志の力だけで生き延びてきた。我々を他の者から隔てているのは、自らへの信念だ。そしてその力で、我々はAzeroth全土に大きな変化をもたらすだろう。弱き者はお前に頼るようになる。病に冒された者たちはお前を主と呼ぶ。そして無知な者はお前に導きを求めるだろう。その時が来たら備えができているよう、お前に必要な道具を与えるのが私の務めだ。経験を積んだら、私を訪ねてこい。準備ができていれば、より大きな力を教えよう。", 0xf5ae8c7e, 0x1fc11880, 0xd59f8872, 0xe3387ae8, 0x8c4ad707, "....." },
  [3098] = { "Glyphic Scroll", "Glyphic Scrollを読み、Deathknellの教会にいるIsabellaに話しかけて下さい。", "ああ、君が知性のないScourgeに対処している間に、この巻物が届いたよ。メイジトレーナーIsabellaの印があるところを見ると、何か大事なことなんだろう。俺だったら、出発前にもう一度読む時間をとるよ。", "お前が私のもとへ来ることは分かっていた、{name}。お前に自分の道を進む意志がないからではない。我々が同じ魂を持つ者だからだ。我々はどちらも痛みを感じてきた。どちらも苦しんできた。そして今、我々のものだと分かっているものを取り戻す力を求めている。この土地、我々の命、我々の運命をな。だが、お前にはまだ学ぶべきことが多い。", "敵対する者たちを殺せるくらい強くなりたいのなら、何度もいらっしゃい。魔法の支配はまだあなたに及んでいるのよ、{name}。餓えた夜の狼のように、まだ汚染がつきまとっているのが分かるはずよ。汚染の抱擁が、かつての恋人がまだ傍にいたいと望むような依存症と似ていることに気が付くはずよ。でもそれも払いのけられるわ。すべて、あなたがそれを許している時にしかあなたを支配できないのだから。\n\nさあ行くのです、もっと強くなったら戻ってくるのですよ。", 0x59480f8c, 0xe2240a4b, 0x538de0b1, 0x33c31b73, 0x7b8e5ffc, "....." },
  [3099] = { "Tainted Scroll", "Tainted Scrollを読み、DeathknellのMaximillionに話しかけて下さい。", "ああ、お前が愚かなScourgeに対処している間に、この巻物が届いたぞ。ワーロックトレーナーMaximillionの印があるところを見ると、何か大事なことなんだろう。俺だったら、出発前にもう一度読む時間をとる。", "ようこそ、同胞よ。お前が来ることは分かっていた。時間の問題にすぎなかった。\n\n私の言ったことに興味を惹かれたのだろう? 心の琴線に触れた……お前の中の何かが、私の主張が真実だと分かっていたのだ。いいだろう。\n\nだがこれだけは知っておけ。私はSylvanasへの裏切り者ではない。むしろ、Forsakenを今の立場に置いたのは彼女自身の信念なのだから、彼女は私の主張を評価するはずだ。", "奴隷は奴隷のままであって、主人は関係ないと話した。覚えているか? それがある種の支配、力のひとつであり、自分たちを駆り立てるものだと知っている。俺たちは、生物を従えさせることを追求しているのだ。俺たちはもっと強く、他の奴らからもっと尊敬を受けて然るべき……だから今、それを奪い取ろうとしているのだ。\n\nこの戦い……自由を求める戦いにおいて、お前の協力者になってやろう。自分たち自身の忠誠を追求する自由だ。覚悟ができたと思ったなら、俺のところへ戻ってこい。俺の知るすべてを教えてやろう。", 0xbb45df2a, 0x6c0ba64b, 0x7834b1d3, 0xe41ae79b, 0xde5f138f, ".....", nil, nil, nil, 0x447c5d0b, nil },
  [3100] = { "Simple Letter", "Simple Letterを読み、Northshire AbbeyのLlane Beshereに話しかけて下さい。", "{name}、君がkoboldのキャンプから戻ったらすぐこれを渡すように頼まれたのだ。ウォーリアトレイナーLlaneの印章で封がされているようだな。私なら、この僧院の別の仕事に取り組む前にぐずぐずせず読むよ。", "ああ、letterを受け取ったんだな、{name}……よし。\n\n最近Elwynnにウォリアーが大勢押し寄せていてな。Stormwindにとってはいいことだが、この辺りのkoboldsやDefiasにとっては災難だ。", "準備を万全に整えておけ。土地の位置を覚え、訓練が必要な時はいつでも戻ってくるのだぞ。私は昼も夜もここにいる。\n\nKnights of the Silver Handはこの場所をかなり安全にするためによくやっているけれども、他の住民に会えば、{class}の助けを必要としている問題を皆が抱えているのが分かるはずだ。頑張れよ。", 0x8a6765ad, 0xcd1a2f24, 0xfe579234, 0x14347375, 0xa4d4bb5c, "....." },
  [3101] = { "Consecrated Letter", "Consecrated Letterを読み、Northshire AbbeyのBrother Sammuelに話しかけて下さい。", "{name}、君がkoboldのキャンプから戻ったらすぐこれを渡すように頼まれたのだ。パラディントレイナーBrother Sammuelの印章で封がされているようだな。私なら、この僧院の別の仕事に取り組む前にぐずぐずせず読むよ。", "ついに! こうして顔を合わせることができたな、同胞よ。Northshireへようこそ。物事のやり方を一から学ぶあいだ、ここがしばらくお前の家となる。だがStormwindは遠くないことを忘れるな。遅かれ早かれ、お前の道はそこへ通じるだろう。それまでは忍耐強くあれ……Knight of the Silver Handよ。", "ところで、新しいことをひとつふたつ知らねばなりませんよ。あなたはこの地の人々に対する象徴なのです……相応に行動するのですよ。「聖なる光」が内に輝いていますから、あなたの仲間にも敵にもすぐ分かります。\n\nまた、叡智と力を手に入れるにつれて、新たな技を身につける修行が必要となります。そこで私の出番です。Northshireで経験を積んだと感じたら来て下さい。そうしたら、あなたが身に着けられるだろうと思われる技をお教えしましょう。頑張って下さい……{class}!", 0x339c82f5, 0x6d6ee593, 0x26cd99ad, 0xeb1b3e11, 0x8b941ae4, ".....", nil, nil, nil, 0x808f8fbe, nil },
  [3102] = { "Encrypted Letter", "Encrypted Letterを読み、Northshire Abbey裏の厩舎にいるJorik Kerridanに話をする。", "私は、koboldキャンプ地からお前が戻ったらすぐにこの封書を届けるよう、頼まれていたのだ。この封書は、教官であるJorikの徽章で封をされている。お前がこの僧院で他の任務に取りかかる前に、これを読んでほしかったのだ。", "無事にここまで来たうえに、あまり人に見られてもいないようだな。それで十分だ。ここで人目を引くのは好きじゃない……静かでいいところだからな。分かるだろう。\n\nもう何か面倒はあったか? ないなら何よりだ。じきにそうもいかなくなるがな。", "俺たちの技を欲しがる連中はいろいろ出てくるぞ、{name}。冒険者、SI:7……ちくしょう、Defias BrotherhoodだってStormwindの中にスパイの2人くらいは欲しいだろうさ。だが覚えときな、お前はお前自身のものだ。やりたくもないことを誰かに無理強いされるんじゃないぞ！それに、切り札は全部こっちが握ってる……少なくとも、勝負がつくまではな。わかるだろ？\n\nとにかく、ちょっと自己紹介して、訓練が必要ならいつでもここにいるって伝えたかっただけだ。いつでも寄ってくれ。", 0x5eef0cde, 0x3d129a05, 0xb39f75e7, 0x6b9b0e24, 0xd57ec303, ".....", nil, nil, nil, nil, 0x46913652 },
  [3103] = { "Hallowed Letter", "Hallowed Letterを読んで、Northshire AbbeyでPriestess Anettaと話してください。", "あなたがkoboldキャンプから戻り次第これを渡すように言われていてね、{name}。たぶんこの地のプリーストトレーナー、Priestess Anettaが封じた手紙だと思うけど。ここAbbeyで何をするにしても私ならその手紙の封を切るね。", "ああ、ついにいらしたのですね。あなたが私のもとへたどり着くと分かっていました。聖なる光があなたと、あなたの選んだ道を照らしています。今は厳しい時代です。Burning LegionはいまだAzerothにその影を落とし、Kalimdorのすべてが自らの苦難から身を守る新たな方法を求めています。そして、できる限り多くの者を助けるのは、あなたの務めなのです。", "経験を積んだら、私のもとへ戻ってきてください。私の知識をできる限りお伝えしましょう。それまでは、心に慈悲を抱いて進み、知恵を導き手としてください。忘れないでください、世界はあなたがより良い場所にしてこそ、より良い場所になるのです。", 0x3871ce99, 0x3719f745, 0x63ba8573, 0x3c6b09ac, 0x69805596, "....." },
  [3104] = { "Glyphic Letter", "Glyphic Letter を読み、Northshire Abbey 内の Khelden Bremen に話しかけて下さい。", "koboldの野営地から戻ったらすぐに、これを見せるよう頼まれていたんだ、{name}。どうやら、この地のメイジのトレーナーであるKheldenの紋章で封をされた手紙のようだ。私なら、ここAbbeyで他の用事に取りかかる前に、ためらわずに読むね。", "こんにちは、{name}。私はKheldenだ。何か用かな?", "ハハハ、私の手紙が君の邪魔をすることはないのは分かってたよ。で、準備はできてるね? 運命を受け入れる覚悟はいいか? 知識と力を求める己の前に立ち塞がる敵や神々に挑む覚悟はいいか?\n\n嘘は言わんぞ、{name}。君は尊敬されるのと同じだけ恐れられることになる。だがこのことも知っておいてくれ。君が訓練を必要とする時、私はここにいる。もっと強くなったら、ただ私を訪ねればよいのだ。", 0x9c0b51a2, 0xb2702f67, 0xde444377, 0x1257130c, 0xea282e3b, "....." },
  [3105] = { "Tainted Letter", "Tainted Letterを読み、Northshire Abbeyの隣にいるDrusilla La Salleに話しかけて下さい。", "{name}、君がkoboldのキャンプから戻ったらすぐこれを渡すように頼まれたのだ。トレイナーDrusillaの印章で封がされているようだな。私なら、この僧院の別の仕事に取り組む前にぐずぐずせず読むよ。", "ああ、来たか。しかもちょうどいいところにな、{name}。少し前に衛兵どもがこっちに来て、妙な目で私を見ていたのだ……哀れな凡人どもめ。", "力をつけるに従って、誘惑に駆られるはずよ……己を律することをいつも覚えておきなさい。嘘は言わないわ……arcaneの練習生なら誰にでも堕落はやってくるもの。特に、Twisting Netherの生物を扱う者はね。忍耐強くなりなさい。そして、慎むこと……でも、熱意を抑えては駄目よ。\n\nもっと強くなったら戻っていらっしゃい。私たちの術をもっと教えてあげる。", 0xfe092140, 0xa2b9450e, 0xc0471a03, 0x04538110, 0x1fcadfe2, "....." },
  [3106] = { "Simple Rune", "Simple Runeを読んで、Coldridge ValleyでThran Khormanと話してください。", "わしを手伝ってくれとる間に、お前さんに渡してくれとこのルーンを預かったんじゃ。暇なときに読んでみるといい。どうやらウォリアーのトレーナー、Thranからのものらしい。目を通したら、Anvilmarの中にいるあやつを訪ねてみるといい。", "くそっ、今日は寒いな? 雪がまるで消えやしないみたいだ、{name}。\n\nもう気づいてるだろうが、今この街にはノームが住んでる。自分たちの故郷から吹っ飛ばされちまったからさ。言いふらすんじゃないぞ、だが奴らを責める気にはなれん……IronforgeがDark Ironsなんかに荒らされたら、俺だって爆薬に頼っただろうからな。", "他にもたぶん目にするものがあるから、知っておくといい。戦いでライフルの代わりに魔法を使うドワーフ。人間の一部みたいに聖なる光を崇めるようになった仲間もいる。それから最後に大事なのが、troggだ。troggについては後でもっと知ることになるが、今知っておくべきなのは、わしがお前さんを助けるためにここにいるってことだ。\n\nわしはお前さんに、本物の{class}になる方法を教えるためにここにいる。もっと訓練が必要だと思ったら、いつでもわしのところへ戻ってこい。何ができるか考えてやろう。", 0x15759692, 0xa8e2a12b, 0x0b2a8f18, 0x45cd211f, 0xc0004879, "....." },
  [3107] = { "Consecrated Rune", "Consecrated Runeを読み、Coldridge ValleyのBromos Grummnerに話しかけて下さい。", "お前さんが私を手伝ってくれてる間に、お前さん宛のルーンを渡されたぞ。機会があるなら、読む時間をとりなよ。このルーンはパラディントレイナーのBromosが出したものだと思う。サッと読んで、Anvilmarにいる彼を探しに行け。", "よう、来たな! しかもちょうどいい時にな。Coldridge Valleyとその先には、やることが山ほどある。お前が俺の助けを必要とするのと同じくらい、俺もお前の助けが必要になるぞ!\n\nお前はもうKnight of the Silver Handだ。それらしく振る舞う覚悟をしておけ。", "人間は「聖なる光」や秩序が彼らにとって……Azerothを守ることにとってどれほど大切か、たくさん教えてくれた。そういう風に伝統に浸透し、たったひとつの象徴や犠牲が、苦悩と救済の間にどれほどの差を生み出すことができるか、我々は大いに敬意を抱いているのだよ。\n\n我々ふたりはしばらく一緒に行動することになる。準備が整ったと思ったらいつでも来てくれ。そうしたらお前さんが修行に入れるか見てあげよう。今、準備もできていないのに世間へ送り出すわけにいかんだろう?", 0x605af2d1, 0x95f50fa0, 0x01726882, 0x5259d37c, 0x8df035d1, "....." },
  [3108] = { "Etched Rune", "Etched Rune を読み、Coldridge Valley の Thorgas Grimson に話しかけて下さい。", "お前さんが手伝ってくれてる間に、お前さん宛のルーンを渡されたよ。機会があるなら、読む時間をとりなよ。ハンタートレイナーの Thorgas が出したんだと思う。サッと読んで、Anvilmarにいる彼を探しに行っとくれ。", "来たか! そりゃよかった! どうせ俺を追跡しなくてもここは見つけられただろ。はっはっ!\n\n俺たちの職業は伝統にどっぷり浸かってるんだ、{name}。土地のしきたりを学ぶ。山の中で熊を追跡することを学ぶ。知恵だけで生き延びるのだって、相当な勇気と狡猾さがいるんだ。お前にできると思うか?", "いつも覚えておかなきゃならないのは、自分が生きている世界に敬意を払えってことだ。お前と共に戦うことを選んだ獣たち、武器の輝き、弾薬の重さ、身を切る風の冷たさ。そういうもの全部を、身に染みて知っておく必要がある。\n\n俺もできる限り手を貸すが、仕事のほとんどはお前次第だ。準備ができたと思ったら、いつでも戻ってきて話しかけてくれ。できる時に訓練してやる。", 0x9cb873ec, 0xaa004bc7, 0x3f424343, 0x919eafc7, 0x04729792, "....." },
  [3109] = { "Encrypted Rune", "Encrypted Runeを読み、Coldridge ValleyのSolm Hargrinに話しかけて下さい。", "君が私の手助けをしている間に、君宛のルーンを渡されたんだ。機会があったら、読む時間をとれよ。ローグトレイナーのSolmが出したものだと思う。それをちょっと読んで、Anvilmarにいる彼を探してみるんだな。", "来たか! いいぞ!\n\n最近は人の出入りが多くてな、Ironforge氏族の仲間がまた一人加わってくれて嬉しいよ。俺の好みからすると、秘術や神の力に目を向ける奴が多すぎる。そいつらやその信仰に文句はないが、手に冷たい刃を握って、影に身を隠して光から逃れるのに勝るものはない。分かるだろ?", "とにかく、Coldridgeのあたりを覗き回り始めたなら、いつか訓練が必要になるだろう。必要だと思ったらいつでもここへ来てくれ。そうしたら技でも戦略でも、知っていることは教えよう。そうそう、命を繋ぎ、ちょっとした小遣い稼ぎにもなる類のことさ。\n\n我らが隣人ノームにも気をつかってやれよ……あいつら、故郷のGnomereganが滅んで貧乏くじを引いたんだ。温かく迎え入れられてると感じてもらうには、俺たちが手助けしてやらなきゃならん。", 0xde5dc5cf, 0x5ff77ee1, 0xfc6f1297, 0xdfb79b4e, 0x81c5d183, "....." },
  [3110] = { "Hallowed Rune", "Hallowed Runeを読んで、AnvilmarでBranstock Khalderと話してください。", "わしを手伝ってくれとる間に、お前さんに渡してくれとこのルーンを預かったんじゃ。暇なときに読んでみるといい。どうやらプリーストのトレーナー、Branstockからのものらしい。目を通したら、Anvilmarの中にいるあやつを訪ねてみるといい。", "おお! 来たか、{name}! すばらしい!\n\n実はな、お前さんが来ないんじゃないかと、信仰を失いかけてたところだったんだ……分かるか、信仰を失う? 冗談だよ、嬢ちゃん……ああ、もういい。どのみち、わしのつまらん冗談を聞きに来たわけじゃないしな。", "Coldridge Valleyで右も左も分からんうちは、わしがお前さんを鍛えてやる。準備ができたと思ったら戻ってきな。いまいましいtroggsどもから谷を守れるよう、新しい呪文を2つほど教えてやれるかもしれん。\n\nお前さんには光がついとる。Ironforge全体もな、{name}……だからって、特別な者になれと重荷を背負わせるつもりはないぞ。", 0x87b91362, 0x2feef57d, 0xa512f166, 0x7e1213ed, 0x2b1b31d2, "....." },
  [3111] = { "象形文字のルーン", "Anvilmarの中にいるMarryk Nurribitと話して下さい。", "ずっと昔、ハイエルフが、同盟者の人間と一緒に、俺たちに魔法の秘密を教えてくれた。奴らは規則のことや、魔法でどうやって正気を失っちまうかを説いて聞かせたもんさ！ だが、そんなこと信じるな。俺たちはエルフとは違う。奴らと同じ弱さは持っちゃいない。正しい道からそれないようにしてりゃ、魔法は武器であると同時に、強力な道具でもあると分かるはずだ。\n\n準備ができたら、Anvilmarの中にいる俺のところへ来い。待ってるぜ！", nil, nil, 0x82fc2769, 0xab749d05, 0x46703590, nil, nil, "...mm" },
  [3112] = { "Simple Memorandum", "Simple Memorandumを読み、Coldridge ValleyのThran Khormanに話しかけて下さい。", "お前さんが私を手伝ってくれてる間に、お前さん宛のメモを渡されたぞ。機会があるなら、読む時間をとりなよ。このメモはウォーリアトレイナーのThranが出したものだと思う。サッと読んで、Anvilmarにいる彼を探しに行け。", "ほう、使命を帯びた{race}からまたmemorandumか……風変わりなこった。\n\nいやいや、からかってるんじゃないぞ、ちびすけ。お前さんの粘り強さには敬意を払わにゃならん、それだけは確かだ。IronforgeがDark Ironのドワーフどもに奪われたら、わしだって同じくらい腹を立てるだろう。だから、お前さんの苦境をわしが気の毒に思ってないなんて考えるなよ……", "まあ、これがお前の最優先の使命、最近はどう呼んでいるか知らんが、そういうものだというのなら、俺はお前と仲間たちが故郷を取り戻す用意を整えられるよう、できる限りのことをすると約束した……だからその通りにするまでだ。\n\n用意ができたと思ったらいつでも、この気のいい老いぼれThranのところへ戻ってこい。喜んで知識を分けてやる。修行には多少の費用がかかるが、そう高くはならんよ。幸運を祈る。", 0xc08132de, 0xfd32d41c, 0xc7252d3e, 0x2813cf41, 0x954e3497, "....." },
  [3113] = { "Encrypted Memorandum", "Encrypted Memorandumを読み、Coldridge ValleyにいるSolm Hargrinに話しかけて下さい。", "君が私の手伝いをしている間に、君宛のメモを渡されたんだ。機会があったら、読む時間をとれよ。ローグトレイナーのSolmが出したものだと思う。それをちょっと読んで、Anvilmarにいる彼を探してみるんだな。", "俺の書き付けを受け取って来てくれてよかった。お前さんの上役からのmemorandumだってふりをして悪かったな……悪気はなかったんだ。ただ、俺たち2人は、同類の連中と一緒に、団結しなきゃならんと分かってたんでな。\n\nお前さんたちと俺たちが同じ街に閉じこもってるのが一番いいことだなんて思う奴は多くないが、俺たちならうまくやっていけると思うんだ。どう思う?", "物がなくなったときに悪い評判が立たんように、俺はこの辺りではだいたい一人でやっている。だが何か入り用なら、修行でも何でも、いつでも戻ってこい。\n\nお前と俺は分かり合っている。いざとなったら信じられるのは身内だけだ……そして、ここにあるのはまさにそれだろう？Gnomereganが……占領されていようと、他に何が降りかかろうと、俺たちには互いを支え合う相手がいる。そうだろう？", 0xb85fa8ab, 0xadca2176, 0xddd66e3c, 0x6c381354, 0x094ba3b2, "....." },
  [3114] = { "Glyphic Memorandum", "Glyphic Memorandumを読み、Coldridge Valleyの上にあるAnvilmarの中にいるMarryk Nurribitと話す。", "お前さんが手伝ってくれている間に、このメモを預かったんだ。お前さんに渡してくれってな。時間がある時に読んでおくといい。たぶんメイジのトレーナーのMarrykからだと思うぞ。目を通したら、時間のある時にAnvilmarの中にいる彼を訪ねてみな。", "ああ、何だって、{race}? 悪いが、もっと大きな声で頼むよ。エールを何杯かやった後は、耳がよく聞こえなくてな。", "ああ、そうだ! Arcane Artsだな……もちろんだとも。\n\n知っとくべきことはこうだ、{name}。面倒ごとに首を突っ込みすぎるな。俺にエールをおごる金は取っとけ……欲しい呪文の分もな。それとGnomereganには絶対に近づくな。それ以外は、良い一日を! 用があるときや訓練したいとき……まあ何でもいいが、俺はここにいるからな。", 0x201c49fc, 0x442b0781, 0x8ec02c25, 0x2a6a6bb4, 0xf605ca24, "....." },
  [3115] = { "Tainted Memorandum", "Tainted Memorandumを読み、Coldridge Valleyの上にあるAnvilmar内のAlamar Grimmに話しかけて下さい。", "君が私の手助けをしている間に、君宛のメモを渡されたんだ。機会があったら、読む時間をとれよ。ウォーロックトレイナーのAlamarが出したものだと思う。機会があれば、それをちょっと読んで、Anvilmarにいる彼を探してみるんだな。\n\nそれから気をつけとけよ{name}。君らウォーロックはここいらじゃほとんど信頼されてないからな。", "素晴らしい! どうやら私のmemorandumを受け取ったようだな。\n\n周りの愚か者どもは無視しろ、{name}。聖なる光だと?! 剣と盾だと?! そんなものは我々のように柔軟な心を持つ者の道ではない。「普通の」魔法が我々の故郷に何をもたらしたか見てみろ。あの忌々しい機械いじりどもと相まって、我々の種族は危うく絶滅するところだった。そして今ではドワーフに頼るしかない――奴らは我々の故郷の再建を手伝うより、人間と手を組むことに時間を費やしたがる。我々はまるで二流市民だ。奴らが我々を見る目つきを見たことがあるか?", "だがそんなことはどうでもよい。問題なのは、己の「聖なる光」を見出すことなのだ! 力がやって来る本当の場所をお前は知っている。己の仲間を持つことこそ……はるかに賢明だと気付いている。特別な仲間をな。その仲間は目的を問わず、死の瞬間までお前の命に従う。\n\n{name}、そこで私の出番というわけだ。特別な力の始まりをお前に施すことができる。いつでも私の元を訪れるのだぞ。教えられる魔法はすべて教えてやろう。", 0x8ca3cdd0, 0xc0e37525, 0x9cf6a18f, 0xefc765ed, 0x0c6a5847, "....." },
  [3116] = { "Simple Sigil", "Simple Sigilを読み、ShadowglenのAlyissiaに話しかけて下さい。", "この印はウォーリアトレイナーAlyissiaの使者に渡されたものだ。時間がある時に君と話がしたいようだな。これを読んだら後で彼女のところへ持って行くのだぞ。", "来てくれたのですね。本当に嬉しいです。\n\nここ数年で多くのことが起こりました、{name}。Teldrassilの誕生、この地や他の地に住む多くの森の生き物たちの堕落、Feralasのように失われたと思っていた土地の発見……わずかな間に、あまりにも多くのことが。けれど、それらは私たちがここにいる理由の一部にすぎません。最も重要なのは、同胞をさらなる邪悪から守ることなのです。", "もうすぐ、我々の故郷の大きな枝の中で、別の種族の者たちを目にすることでしょうが……先入観を持ってはいけませんよ。彼らは歓迎される者なのです。可能な時には我々を助けてくれるでしょう。彼ら全員が他者のために手を貸してくれるわけではありませんが、いくらかは信用がおけるはずです。\n\nしかし今はどうでもよいことです。今は己自身に向き合い、いかに我々ナイトエルフを支えるかに集中せねばなりません。私はまさしくそのためにここにいるのです。あなたがもっと強くなれるよう、{class}の技を訓練してあげましょう。いつでも好きな時に戻ってくるのですよ。手助けできることならばやりますよ。", 0x0b1c4d33, 0xd0e81f4b, 0xba14907e, 0x57568a0d, 0x95b00c23, "....." },
  [3117] = { "Etched Sigil", "Etched Sigil を読み、Shadowglen の Aldrassil の頂上にいる Ayanna Everstride に話しかけて下さい。", "この印は、ハンタートレイナー Ayanna の使者が届けてくれたものだ。時間がある時にでも、君と語り合いたいようだな。それを読んだら、彼女に渡してくれ。", "よく来た。ちょうどよい頃合いだ、{name}。Shadowglenへようこそ。\n\n私のsigilが届いたとき、君は元気で健やかだったかな?\n\n前にも言ったとおり、私はハンターとして君を鍛えるためにここにいる。戦いで君を助ける獣を手なずけること、狂いのない正確さで弓を扱うこと、我々が故郷と呼ぶ土地とその先の土地を敬うことをな。", "Shadowglen の教えを経験したら、私のところへ来るのですよ……ハンターとしての役割や持てる才能の理解を手伝ってあげられます。\n\n{name}、今は恐ろしい時代なのです。ペットの技を当たり前のことと勘違いしてはなりません……この世界にはあなたの想像よりもっと危険なことがあるのです。女神 Elune と共に歩みなさい。そしてまた私のところへ戻ってくるのですよ。", 0x4253939a, 0xd81ae928, 0xec30768a, 0x5c32ead3, 0x1a49e722, "....." },
  [3118] = { "Encrypted Sigil", "Encrypted Sigilを読み、ShadowglenのFrahun Shadewhisperと話してください。", "このsigilは、私たちのローグのトレーナー、Frahunの使いの者から預かったものだ。手が空いたときに、Frahunが君と話をしたいそうだ。これを読んで、そのあと彼のところへ持って行ってくれ。", "やあ、{name}。私を見つけてくれてよかった。ここへ来る途中で道に迷ったのかと思っていたところだよ。\n\n君にsigilを送ってから、Shadowglenでは特に新しいことは起きていないが、情報集めは君に任せよう。よければAldrassilの周りにいる他の者たちにも話を聞いてみるといい。", "それまでは、この不安定な時代だからこそ、我々のような者がかつてないほど必要とされていると知っておいてくれ。他の種族との和平はいつ崩れてもおかしくないし、Hordeの連中がさらに大きな不信の種をまこうとしているという噂も多い。そのことを覚えておけ。\n\n力をつけて、もっと備えができたと感じたら、またここへ戻ってきてくれ。訓練をつけてやれるか考えてみよう。ほかにもいろいろあるが、自分の選んだ武器の扱い方を知っておくことが特に大切だ。", 0xd9ec7b68, 0x0f31aa64, 0x6d5e7cd1, 0x042e42d6, 0x1de17785, "....." },
  [3119] = { "Hallowed Sigil", "Hallowed Sigilを読み、AldrassilのShandaに話しかけて下さい。", "この印はプリーストトレイナーShandaの使者から預かったものだ。時間がある時にでも、君と語り合いたいようだな。それを読んだら、彼女に渡してくれ。", "こんなに早く来てくれて嬉しく思います、{name}。ようこそ。\n\nおそらく聞いているでしょうが、Teldrassil全体が旅人の往来でざわめいています。これから待つ冒険に備える他のKaldoreiと会うために、Allianceの者たちでさえTeldrassilの枝へ立ち入ることが許されているのです。", "当分、Teldrassilの下の世界とは関わらないようにするのですよ。後になればその時間はありますから。外へ出て、Shadowglenの他の者たちに話しかけて下さい。……今起きている出来事についてもっと詳しく教えてくれるでしょう。手を尽くして彼らを助けるのですよ。そして、もっと訓練が必要だと感じたならここへ来るのです。できる限り教えてさしあげましょう。", 0x83a52cc5, 0xf53c2a50, 0xca5600b8, 0x1f4e46af, 0x1e10f375, "....." },
  [3120] = { "Verdant Sigil", "Verdant Sigilを読み、ShadowglenのAldrassilの木にいるMardant Strongoakと話して下さい。", "この印はドルイドトレイナーMardantの使者から預かったものだ。時間がある時にでも、君と語り合いたいようだな。それを読んだら、彼に渡してくれ。", "ああ、若き{class}よ。学びを続けたくてたまらないようだな。よいことだ。\n\nところで、もうEmerald Dreamで多くの時を過ごしたかね? まだその準備はできていないのかもしれんな……いずれはできよう、きっと。\n\nだがそれまでは、他のことについて話すとしよう。", "今から私が君の師匠となって指導しよう。精霊が我々に伝えてきたことだけでなく、Emerald Dreamの秘密と複雑さの解釈法をも教えるのが私の責務だ。\n\n力を増し、学んでいけば、君はさらに我々の「眠り」について知ることとなるだろう。だがそれまでは、私のところへ好きなだけ頻繁に来るように。そうすれば、ドルイドの術で教えられるものは教えよう。", 0xbdc6d3be, 0x67426736, 0xaf299504, 0x240343bf, 0x0f1fd4af, "....." },
  [3121] = { "奇妙な依頼", "OrgrimmarにいるNeeru FirebladeにShrunken Headを渡して下さい。", "OrgrimmarのNeeru Firebladeが、ここで始めるのに必要な物を持ってるんだ! 俺の……まあ、見れば分かるさ、そのために要る調合薬を混ぜてくれたのさ。\n\nさあ行け――Orgrimmarへ。ほら、これを持っていけ。薬草と交換するとNeeruに約束していたshrunken headだ。森で出くわした哀れなドワーフの首さ。Neeruもきっと喜ぶだろう。\n\nNeeruはCleft of Shadowにいる。", "何か？", "Uzer'iがこれを届けてくれるのを待っていた……\n\n彼の……まあ、実験のために用意した薬草の調合を渡そう……", 0x88b8407c, 0xaadb8829, 0x55fb2183, 0x0c07a888, 0x87bbbd29, "....." },
  [3122] = { "Witch Doctor Uzer'iのもとへ", "Neeru's Herb PouchをFeralasのWitch Doctor Uzer'iに届けて下さい。", "これが薬草だ、{name}。Witch Doctor Uzer'iのところへ持って行け。\n\nshrunken headには満足していると伝えてくれ。", "Neeruとはもう話したか?", "これこそmuisekの器を用意するのに必要なものだ、{name}。私の最新の呪文が望んだ通りの力を持つかどうか、間もなく分かるだろう。\n\n少し待ってくれ。儀式を行い、薬草を施さねばならん。", 0x8de30558, 0x030a5f43, 0x21a6e903, 0xc26e6919, 0xb1bd0568, "....." },
  [3123] = { "器の検証", "Hinterlandsへ行き、Wildkinを見つける。$N1体倒し、Muisek Vesselを使って倒したWildkinを縮めて捕らえる。\n\nWildkin Muiseksを$N2個とMuisek VesselをFeralasのWitch Doctor Uzer'iのところへ持って行って下さい。", "これは試練となる。俺が行った儀式の、そしてお前の力のな。この器を持っていけ、{name}。これがあれば、生き物を縮めて中に捕らえる力が得られる。\n\nHinterlandsへ行き、かつてナイトエルフの女神Eluneのペットだった、Wildkinと呼ばれる生き物を探せ。狙うのはvicious、primitive、あるいはsavage owlbeastsだ、{name}。$N1体倒し、奴らの魂が逃げ出す前にmuisekの器を使って縮めて捕らえろ。", "wildkinは捕まえられたか?\n\nうまくいけば、Feralasの生き物たちのmuisekを縮めて捕らえる準備が整う。", "激しい死に触れて、生き物である魂は逃げ出して復讐を求めるかもしれない。お前がやったような生き物の圧縮はな、{name}、魂が逃げ出すのを防ぐのだ。これから好き勝手にこの器を使えるかもしれんな!", 0xf5e2ea5b, 0xf8f9b1b4, 0xa7c67336, 0xc42ca850, 0xcd9b46cd, "....." },
  [3124] = { "Hippogryph Muisek", "いずれかの種類のFrayfeather Hippogryphを10頭殺し、縮めて捕らえるためにMuisek Vesselを使って下さい。", "お前が信頼に足り、しかもmuisekの器を扱う才があることは証明された。次は別の生き物を捕らえてもらいたい。\n\nhippogryphsは長年ナイトエルフの忠実な仲間だった。その魂は忠実で揺るぎない。\n\nお前の務めは、frayfeather hippogryphsを$N1体倒し、すばやく器で縮めて捕らえ、そのmuisekを保存することだ。hippogryphsはここから南のHigh Wildernessにいる。", "hippogryphsは捕まえられたか?", "獣を殺した後、muisekを逃がしてしまえば、それはさらに大きな生き物の姿を取るかもしれん。その復讐から逃れて安全でいられる日は二度と来ないだろう。\n\n私がお前に与えたのは危険な仕事だ、{name}。今回もよくやり遂げてくれた。", 0xcb542dcf, 0xc078abbc, 0x58d1d91b, 0x0741c451, 0xe04d853a, "....." },
  [3125] = { "Faerie Dragon Muisek", "Sprite DarterかSprite Dragonを8頭殺して下さい。死んだFaerie Dragonを縮めて捕らえるためにMuisek Vesselを使って下さい。", "{name}、次に捕らえてほしい生き物は、見た目はとてもか弱く見えるかもしれんが、我々が本当に求めているのはその強い魂だ。俺の言うfaerie dragonsは、ナイトエルフの味方として仕えてきた。hordeもその魂の強さの恩恵を受けられるよう、一匹捕らえねばならん。\n\nこれがmuisekだ、{name}。sprite dartersかsprite dragonsを$N1体倒し、そのmuisekを捕らえろ。奴らはここから西にいる。", "faerie dragonsのmuisekは捕まえられたか?", "礼を言う、{name}。これでfaerie dragonの霊的な力が我々のものとなる。\n\nもう一つ、私のために務めを引き受けてくれることを願っている。", 0x58acbb3c, 0xea4fd892, 0xbcfa10ea, 0xf13dd93d, 0x98072748, "....." },
  [3126] = { "Treant Muisek", "Wandering Forest Walkerを3体殺して下さい。死んだTreantを縮めて捕らえるためにMuisek Vesselを使って下さい。", "森の中をさまよい歩くwandering forest walkersが、我々の次の標的だ、{name}。ナイトエルフはtreantsをhordeと戦う味方に引き入れている。動きは遅いかもしれんが、守護者としての役割は否定できん。\n\nじきに、この力を我々のために使えるようになる。\n\nwandering forest walkersを$N1体見つけて倒し、muisekの器を使って縮めて捕らえろ。", "wandering forest walkersは捕まえられたか?", "ありがとう、{name}。魂の収集はほぼ完璧だ。", 0x5084286b, 0xbd74e013, 0x8b52f0dc, 0xdb5de487, 0x65bce135, "....." },
  [3127] = { "Mountain Giant Muisek", "Land WalkerかCliff Giantを7体殺して下さい。死んだMountain Giantを縮めて捕らえるため、Muisek Vesselを使って下さい。", "お前に頼む最後の務めは、北西へ向かい、最後の敵を見つけることだ。\n\nburning legionがこの世界に現れたとき、mountain giantsは山を離れ、ナイトエルフに力を貸した。その巨大な体と、奴らの岩だらけの地を進むにつれて地面が揺れ始めることで、それと分かるだろう。\n\nあれほどの大きさの力を手に入れたくてたまらん。mountain giantsを$N1体倒し、muisekの器を使って、その強大なmuisekを捕らえろ。", "mountain giantsは捕まえられたか?", "{name}、我々が今手にしているものの可能性を考えてみろ。お前が集めてきたこの素材の他にも、生き物の魂を何でも望み通りに際限なく罠にかけることができるはずだ。", 0xa0493aa5, 0x716fafad, 0xa2bb182e, 0x0f0962f1, 0x14052580, "....." },
  [3128] = { "自然素材", "Splintered Log 2本・Encrusted Mineral 6個・Resilient Sinew 20個・Metallic Fragment 40個を、Camp MojacheのWitch Doctor Uzer'iに渡して下さい。", "俺の企てを成し遂げるには、いくつかの材料が要る……これは、俺が与える他の務めと並行して進めて構わん。\n\nFeralasのtreantから取ったsplintered logが要る。encrusted mineralsは、西にいるmountain giantsとfaerie dragonsから手に入る。それから、Hinterlandsのowlbeastsか、Feralasのhippogryphsからresilient sinewを見つけてこい。最後に、今挙げたどの生き物からでもいいから、metallic fragmentsを大量に頼む。", "私に必要な素材は集められたか?", "素晴らしい! この素材を魂と結合させれば、我々がまさに望んでいる結果を生み出すに違いない。", 0xca658549, 0x59ecd377, 0x753f2fae, 0xd18efce3, 0xf2fd7adb, "....." },
  [3129] = { "魂の武器", "Witch Doctor Uzer'iは武器を用意するまでしばらく待つよう求めています。", "武器に魂を吹き込むのは難しい工程だ。必要な素材とお前が捕らえてきた生き物の魂はすべて揃っているから、始めよう。待ってろ。すぐお前に渡してやる。", nil, "約束通り、お前には選ぶ権利がある、{name}。獣たちのmuisekは、この武器の力の中に永遠に封じられた。\n\n今やお前はその力を自分のものとして振るえる。よく使え。", 0xd12a1fcd, 0xb07b6bf4, 0x08cd8251, nil, 0x3a33ace4, "...m." },
  [3130] = { "Hatecrestとの戦い", "Feathermoon StrongholdのLatronicus Moonspearに報告して下さい。", "ここからは、私の副官のLatronicusのもとへ行ってもらう。彼はこれまでnagaの軍勢をずっと注意深く見張ってきた。私はここで、nagaに関する全般的な状況を見極める。奴らに全軍をぶつけたいのはやまやまだが、この砦をHordeの――あるいはもっと悪いものの――直接攻撃にさらすのは、最善とは言えんだろう。\n\nとにかく、Latronicusが待っている。ここまでよくやってくれた、{name}。この調子で頼む。\n\n下がってよし。", nil, "素晴らしい、{name}。共に働く者には「やればできる」という姿勢を重んじている。\n\nGeneral Feathermoonから、nagaに直接対処するよう任されている。私の計画は2つある。1つ目は、nagaの戦力を数でも指揮系統でも弱体化させること。2つ目は、奴らが遺跡で何をたくらんでいるのかを突き止めることだ。君の助けがあれば、要塞全体の守りを犠牲にすることなく、nagaの存在に対抗できるだろう。", 0xbaae3916, 0x9a6ce96c, 0xfc773ddd, nil, 0x746a107e, "...m." },
  [3141] = { "Loramus", "Loramus Thalipedesが語る話を聞いて下さい。", "悪魔と戦いたいというのか？ ならば、私の話を聞いておくがよい。", "邪魔をするな、{race}。", "ならば、そうしよう……", 0x91a14087, 0xc42c437e, 0xc10e0092, 0x3220e0c2, 0xef47da38, "....." },
  [3161] = { "Gahz'ridian", "TanarisのMarvon Rivetseekerは、Gahz'ridian Ornament 30個を集めるよう求めています。", "{name}、俺は科学者だけど、心はトレジャーハンターなんだ!\n\n大昔、トロールがこの地に住んでいた頃、奴らは神として崇めていたヒドラ、Gahz'rillaを模した装飾品を大量に作ったんだ。その装飾品は、ヒドラの神にちなんで俺が「Gahz'ridian」と呼んでる元素から彫り出されてる。\n\n自分でもいくつか見つけたけど、研究用にもっと欲しいんだ――君なら見つけられるかな?\n\nGahz'ridianを楽々見つけられる探知機まで発明したんだぜ! 着けるだけで、探索開始さ!", "何か困っているのか?\n\nGahz'ridianはTanarisならほぼどこでも見つかる、{name}。探し続けるんだ!", "完璧だ。このornamentは私の研究にうってつけだ。手伝ってくれて本当にありがとう、{name}。\n\nああ、それと兜を返してもらえるかな？", 0x0b56dac1, 0x4998da48, 0x0dde7e0d, 0xdaa6c3da, 0x30577316, "....." },
  [3181] = { "獣の角", "Margol's Gigantic HornをMountaineer Pebblebittyのところへ持って行って下さい。", "その巨大なhornには無数の傷やひびがある。その粗い表面に、見慣れない金属の物体が食い込んでいる。\n\nよく調べてみると、その金属は実は折れた斧の刃だと気づく。金属には次の言葉が刻まれている。\n\nMountaineer Pebblebittyの所有物。\n\n折れた斧の刃を外そうとすると、粉々に砕け散ってしまう。\n\nおっと！", "いや、門は開けない。", "それは何だい? どう見たって偽物だ!\n\n私はMargolと面と向かったことがあるから、はっきり分かってる。あいつの角は、君が手に持ってるそれの少なくとも8倍は大きいんだ、{name}。どうせBarrensでstormsnoutからでも取ってきたんだろう。だめだめ、あんた、このPebblebittyはごまかせないよ!", 0x2e5f0c0b, 0xb93db2d2, 0x3392c641, 0x2dfa9f43, 0xe1a41449, ".....", nil, nil, nil, nil, 0x7710ebcd },
  [3182] = { "Proof of Deed", "Margol's Gigantic HornをIronforgeのCurator Thoriusのところへ持って行って下さい。", "そんな話を信じろって言うのかい？ 本物のhornなら、あたしの折れた斧の刃がまだ表面に食い込んでいたはずだよ。\n\nいいかい、その見え透いた偽物をIronforgeのCurator Thoriusのところへ持っていきな。あの人があんたの言い分を認めたら、proof of deedがもらえる。その証書をあたしのところへ持ってきたら、Searing Gorgeの鍵をやるよ。\n\nさあ、行った行った！", "おや、こんにちは、お若い方。博物館を見学していきませんか?", "これは何だい?\n\nなんと、信じられない! 自分が何を手にしているか分かっているのかい、{race}? これはMargol the Ragerの角だ! Searing Gorgeに足を踏み入れたあらゆる考古学者の悩みの種だった、あのMargolだよ!\n\n私がもらってもいいかな?", 0x63d25e29, 0x5939f719, 0xb834107c, 0x8e279b3a, 0xe346b32f, ".....", nil, nil, nil, 0xf600fc7f, nil },
  [3201] = { "ついに！", "Proof of DeedをMountaineer Pebblebittyのところへ持ち帰って下さい。", "Pebblebittyが角の本物らしさを疑ったなんて信じられんな。ここだけの話、あれはただのやきもちだと思うよ。あの獣を自分の手で仕留めたくてたまらなかったんだ。例の「一件」もあったことだしな。\n\nそれで、proof of deedが要るのかね？ 君が今しがた博物館にしてくれた貢献を考えれば、何の問題もないよ。\n\n<Curator Thoriusは大きな書類に記入し始めた。>\n\nさあ、できた！ これをPebblebittyのところへ持っていくといい。", "信じられん。", "お前のような弱い奴がどうやってMargolを倒したのか知らんが、約束は約束だ。これが鍵だ。\n\nこの後お前の身に何が起ころうと、お前自身の責任だぞ。", 0xe8848fc6, 0xf8522386, 0x06cca93a, 0x422d6af8, 0x9cad295e, "....." },
  [3221] = { "Renferrelをたずねよ", "SepulcherのApothecary Renferrelと話をしてください。", "君が我らDeathstalkerの手助けに行っている間に、Apothecary Renferrelから呼び出しがかかっていたぞ。詳しいことは言わなかったが、君が渡した狼の心臓のことを聞きたがっていたようだ。", nil, "ああ、来たかい。君がこの前持ってきてくれた狼の心臓のことでちょっと聞きたいことがあってね。", 0x043c659a, 0x3eb5474e, 0x5ca32cb6, nil, 0x95d52ec0, "...m." },
  [3261] = { "Jorn Skyseer", "Camp TaurajoにいるJorn Skyseerと話してください。", "私のもとでの修行は終わりだ、{name}。さらに学ぶには、南のCamp Taurajoへ行き、Jorn Skyseerと話すがよい。彼がお前の導きを引き継いでくれるだろう。", nil, "やあ、若いの。\n\nハンターへの道を歩むのか?\n\nいいだろう。じゃあ始めようか。", 0x4d1b9bdc, 0x038243ce, 0x2e23d78b, nil, 0x88022d9d, "...m." },
  [3281] = { "Stolen Silver", "Stolen SilverをCrossroadsのGazrogに渡してください。", "君はraptorを殺したかもしれない。だが、やつらの盗んだ銀貨を取り戻さなくてはならない！\n\n我々はRaptor Groundsとして知られているRatchetの南側にやつらの巣があるとの情報を得た。やつらはそこに我々の銀貨を運び込んだ可能性が高いだろう。\n\nやつらの巣に向かい、盗まれた銀貨を探してくれ。もし見つけることができたら私のところへ持ってきてくれ。", "silverは持ってきたか?", "なるほど・・やつらは銀貨を巣に隠してたわけだ。\n\n動物が銀貨を欲しがるとはとうてい信じがたいが・・・  もしかすると私が思っているほどやつらと我々の知性はそれほど離れていないのかもしれんな。\n\nありがとう、{name}。　これを今回の件の報酬としてもらってくれ。crossroadsの警備隊は来月の給料について君に借りができたようだな。", 0xe35e0500, 0x12efa283, 0x2983e37d, 0xf2e4b6ca, 0x1f48ebc1, "....." },
  [3301] = { "Mura Runetotem", "SepulcherにいるMura Runetotemと話して下さい。", "我が一族の仲間、Mura Runetotemはアンデッドの同盟を手助けするために、Silverpineへ旅立った。Silverpineは病み、死んだ森だ。その森に新しい命をもたらすことがMuraの望みだ。多分、Barrensで見つかったこの奇妙な命は、Silverpineでの仕事の助けになる。\n\n君が集めてくれたこの甲羅を、SilverpineのMuraに持って行ってくれ。彼女はSepulcherに滞在している。運がよければ、あの死んだ場所を癒すのに必要な洞察をこの甲羅の研究がもたらすだろう。", "お前からBarrensの砂埃の匂いがするぞ、{class}。遠くから旅してきたのだな。", "あら、これは何かしら? この甲羅はまるで生命が脈打っているみたいに、内側から輝いているわね。なんて素晴らしいの! もっとこれを研究しなきゃいけないわ。\n\nありがとう、{name}。運がよければ、Silverpineの痩せた土地を救うのに使える秘密が、この甲羅にあるかもしれない。", 0x6ec1c3d1, 0x36a63bfc, 0xc0bed28e, 0xf5936a1e, 0x520dd133, "....." },
  [3321] = { "これを失くしたの?", "Trentonが作業を終えるまで待って下さい。", "あなたはOrderのために多くを成し遂げてくれました、{name}。ここまで来るのに要した献身ぶりには、普通の者なら尻込みしていたでしょう。あなたが私たちの一員であることに、私の中にも、Galvanの中にも、何の疑いもありません。\n\nだからこそ、あなたはささやかな報酬に値すると思うのです。大したものではありません、ただの小物です。その性質はご存じかもしれませんね。そもそもあなたを私たちのもとへ導いたのが、それだと思いますから。", "今日、我々は君のOrderへの献身を祝う儀式を締めくくる。", "名を上げ、評価されるんだ。Mithril Orderの鍛冶師、{name}。", 0x6c8c8581, 0xc8d14884, 0x3d6a7db3, 0x38770b41, 0x65d75799, "....." },
  [3341] = { "終焉をもたらす", "Andrew Brownellは、Amnennar the Coldbringerを倒し、その頭蓋骨を持ち帰ってほしいと言っています。", "Barrensには、もつれた蔓のおぞましい塊があり、Razorfen Downsと呼ばれている。最初の観察ではこの場所にほとんど脅威は見当たらなかったが、最近の発見ははるかに深刻だ……\n\nRazorfen Downsのquilboarは、Scourgeと手を組んだ。今はAmnennar the ColdbringerというLichが彼らを支配しており、その強大な意識の力で彼らの一挙一動を操っている。\n\nAmnennarはNer'zhulと直接のテレパシーでつながっている。我々はこの絆を断ち切らねばならん、{name}。Coldbringerに終わりをもたらさねばならんのだ。", "これは極めて重要な問題だ、{name}。Scourgeが戦力を増強しようとする企みは、すべて阻止しなければならん。", "Lichの忠誠は揺るがぬものだ、{name}。そのような忠誠が奴らにもたらすのは破滅だけだと、思い知らせてやれ。", 0x1f522a28, 0xa3eec115, 0xdcaf73d5, 0xb3d2ae26, 0xeda91eee, "....." },
  [3361] = { "避難民の苦境", "Felix's Box・Felix's Chest・Felix's Bucket of BoltsをAnvilmarのFelix Whindleboltに渡して下さい。", "Gnomereganからtroggを追い出したのに、そのあと何もかもがひどいことになっちゃったんだ！今じゃ故郷はすっかり放射能まみれで、僕たちノームはDun Morogh中に散り散りになってしまった。\n\n放射能から急いで逃げたせいで、私物も道具も全部なくしちゃった。持っていったのはトロールだよ。僕のchestも、boxも、bucket of boltsまで盗まれたんだ！Anvilmarの南西にある奴らのキャンプに持ち帰られちゃった。\n\n僕は冒険者じゃないんだ――僕の物を見つけて、ここまで持ってきてくれないかな、お願い？", "ああもう、{name}、この町は私みたいな者には向いてないよ。事故の前のGnomereganと同じくらい、ここには嫌な生き物がうじゃうじゃいるんだ!\n\n私の持ち物は持ってきてくれた? もしまだなら、トロールどもが今ごろそれをどうしちゃったか分かったもんじゃない……", "やったぁ、見つけてくれたんだね！君は本当に救世主だよ、友よ。ほら、大したものじゃないけど、迷惑をかけたお詫びのしるしだ！ありがとう！", 0x71d49aac, 0x8c5c5442, 0x7b36eefc, 0xe6a8fff5, 0x6f038cb6, "....." },
  [3362] = { "Thistleshrub Valley", "GadgetzanのTran'rekは、Gnarled ThistleshrubとThistleshrub Rootshaperをそれぞれ8頭殺すよう求めています。", "Thistleshrub Valleyを見たことあるかい? ものすごく危ない所だよ、{name}。\n\nあそこの妙な獣どもときたら、ちっとも信用できない! gnarled thistleshrubsとthistleshrub rootshapers、たしかそう呼ばれてたと思うけど……\n\nとにかく、谷に入りたいんだけど、あんなにたくさんthistleshrubsがいちゃ、戻るなんてとんでもない。そこで君の出番さ――もし君が何匹か片付けてくれたら、戻ることを考えてみてもいいかな。どうだい、{name}? 手を貸してくれる?", "谷にあるあのサボテンをもっと近くで見てみたいんだ……だから少しは形のまま残しておいてくれよな?", "そんなに大きいのか? 計画を考え直さなきゃならないかもな……\n\nでも、君は約束をちゃんと果たしてくれた。だから、これが約束の品だ。", 0x8cd85dbd, 0x4d0981fc, 0x3c4f4162, 0x43b6929c, 0x1a09be46, "....." },
  [3364] = { "Scalding Mornbrewの配達", "Anvilmarの中にいるDurnan Furcutterに、5分で冷める前にScalding Mornbrewを配達しろ", "くそっ! このうまい熱々のmornbrewを、しばらく前にAnvilmarの中のDurnan Furcutterへ届けるはずだったんだが、先にここのGrelinに一杯届けなきゃならなくてな。これじゃ、Anvilmarに着く前に冷めちまう!\n\nお前さん、足が速そうだな。お前さんなら間に合うかもしれん。このカップはあと5分しか熱いままでいられないし、Durnanは「冷えた」mornbrewなんて注文しちゃいない。さあ急げ。Anvilmarは北東、山に掘られた集落だ。\n\nありがとな、{name}。俺のマグを持って帰るのを忘れるなよ!", "おう、わしがDurnan Furcutterだ。わしに何か持ってきたのか?", "よしよし、やっと到着したか。このScalding Mornbrewを味わう間、ちょっと休憩させてくれよ！", 0xf0284895, 0x5506e41b, 0xbce4688b, 0x65bfe9d2, 0xd3b1def7, "....." },
  [3365] = { "マグを持って帰ろう", "Nori's MugをNori Pridedriftに返して下さい。", "こいつは効いた! 寒い冬の日に、熱々の――いや、やけどするほどの――mornbrewほど、魂の芯まで温めてくれるものはないな。\n\nほらよ、{name}――頼むから、この空のマグをNoriに返してきてくれんか。", "熱々のmornbrewがちゃんと間に合ってDurnanに届いたといいんだけど! 私のmugを持って帰ってくるの、忘れなかった?", "見事だ、{name}！mugを持ち帰るという単純なことすら忘れる使い走りが、どれほど多いか驚くぞ。mugは木に生るわけじゃないからな、そう聞いているよ！\n\n手間をかけた分の心付けだ。改めて助力に感謝する。", 0x8db5a5c3, 0x1075f009, 0x2d2a6b06, 0x795e536d, 0x3d3438fe, "....." },
  [3366] = { "Glowing Shard", "Ratchetへ行き、Nightmare Shardに秘められた意味を突き止めて下さい。", "その欠片は鮮やかな緑色で、固いのに、表面のすぐ下で煙のようなものが渦巻いている。結晶の奥をつい見つめてしまうが、同時に、どこかひどく不穏なものがあると分かる。\n\nRatchetに、この奇妙な欠片についてもっと教えてくれる者がいないか確かめてみるべきかもしれない。", nil, nil, 0x855951c0, 0xa0c652c0, 0xf1eddfb4, nil, nil, "...mm" },
  [3367] = { "Suntaraの石", "DoriusがIronforgeへ戻るのを手伝って下さい。", "<Doriusはうめいた。>\n\nひどい怪我だ、{race}。頭が……ふらふらする……世界が回っている……出血が……体の中で。\n\nIronforgeに戻らねばならん。助けてくれ、{name}。", "私はもう駄目だ……", "この手紙は、Doriusが撃たれたときに落としたものだ。", 0x49144676, 0xb36e1cd6, 0xa87dc59b, 0xf779cab5, 0x8d0bdc13, "....." },
  [3368] = { "Suntaraの石", "Singed LetterをIronforgeのThoriusのところへ持って行って下さい。彼はHall of Explorersにいます。", "兄弟へ\n\nもしお前がこの手紙を読んでいるなら、私はもうこの世にいない。どうやってお前の手に渡ったのかは分からないが、届けてくれた者たちに礼を言い、報いてやってくれ。\n\n石のことだが、あれは実在する。そしてDark Ironsがそれを手にしている。奴らの指導者Lathoric the Blackが、石の力を使って私の発掘隊を奴隷にしているのだ。彼らは大釜へ連れていかれた。心をねじ曲げられ、Obsidionと呼ばれる何かを完成させるために、昼も夜も働かされている。\n\n彼らを助けてくれ、兄弟よ。死んだ男の最後の願いだ。\n\n-Dorius", "<Thoriusはすすり泣いている。>", "<Thoriusは顔の涙を拭う。>\n\n光の名にかけて、彼の願いは叶えられよう。これは私の誓いだ。", 0x49144676, 0x54c7e8e2, 0x6d1813a8, 0xd7580be9, 0x125e0856, "....." },
  [3369] = { "悪夢の中で", "Nightmare ShardをElder RiseにいるHamuul Runetotemに渡して下さい。", "このかけらには大きな秘密があります。これはEmerald Dreamの純粋な結晶なのです。しかし、かけらの中に私が見た物は、夢ではありませんでした。それは悪夢の光景ともいえる類のものだったのです。\n\n{name}、あなたを怖がらせるつもりではないのですが、出来る限り早く、聡明なドルイドの手元へかけらを届けるのが最善策だと思うのです。\n\nあなたが会うべき人は、Elder RiseにいるHamuul Runetotemです。Thunder Bluffへ向かって下さい。これ以上のことは言えません。", "何かご用ですか?", "Fallaがそなたを寄越したのか? それでは、見てみよう。Fallaが語るのをためらったというかけらを……\n\n<Hamuulはかけらの中をじっと見つめた。>\n\nおお……これは言えんな……やれやれ。\n\n{name}、これを持ってきてくれたことに感謝するぞ。このように話すのは賢明ではないが、忠告しよう。これはそなたが関わるべきでない問題だ。\n\nひとまず、Emerald Dreamは我々が思っていたようなものではなかった、とだけ言っておこう……\n\n恐らく今後、我々の道は再び重なることになろう。", 0x768d8fac, 0xe8a601a6, 0x45fe85a3, 0x42e8d794, 0xcb46c0bc, "....." },
  [3370] = { "悪夢の中で", "Nightmare ShardをDarnassusにいるMathrengyl Bearwalkerに渡して下さい。", "このかけらには大きな秘密があります。これはEmerald Dreamの純粋な結晶なのです。しかし、かけらの中に私が見た物は、夢ではありませんでした。それは悪夢の光景ともいえる類のものだったのです。\n\n{name}、あなたを怖がらせるつもりではないのですが、出来る限り早く、聡明なドルイドの手元へかけらを届けるのが最善策だと思うのです。\n\nあなたが会うべき人は、Cenarion CircleにいるMathrengyl Bearwalkerです。Darnassusへ向かって下さい。これ以上のことは言えません。", "何かご用ですか?", "Fallaが君を寄越したのか? それでは、見てみよう。Fallaが語るのをためらったというかけらを……\n\n<Mathrengylはかけらの中をじっと見つめた。>\n\nおお……これは言えんな……やれやれ。\n\n{name}、これを持ってきてくれたことに感謝するぞ。このように話すのは賢明ではないが、忠告しよう。これはCenarion Circleのドルイドだけで取り組むべき問題だ。\n\nひとまず、Emerald Dreamは我々が思っていたようなものではなかった、とだけ言っておこう……\n\n恐らく今後、我々の道は再び重なることになろう。", 0x768d8fac, 0x92596199, 0x891baadf, 0x42e8d794, 0x1d9fadb2, "....." },
  [3371] = { "ドワーフの正義", "Searing Gorgeへ戻り、Doriusの考古学調査隊を見つけて下さい。", "心があったところに、ぽっかりと空っぽの穴が開いてしまった、{name}。Doriusを失った痛手から、すぐに立ち直れるとは思えん。彼の最後の願いは、私が最後まで果たさねばならん。この冷酷な殺しの犯人どもに、裁きを受けさせねばならんのだ。\n\nSearing Gorgeへ戻り、彼の最後の頼みを果たしてくれ。彼の部下たちを解放するのだ。", nil, "私のことはいい、他の者たちを助けてくれ。", 0x040d1a14, 0x1d757d60, 0x16a99128, nil, 0x7f1395e5, "...m." },
  [3372] = { "彼らを解き放て", "Searing Gorgeの北西部でTwilight's Hammer Idolatersが守っているMysterious Artifactを見つけて下さい。", "彼らを解き放ってくれ、{race}。体が限界を迎えた後でさえ、Suntaraの力が彼らに仕事を続けさせているのだ。\n\nSuntaraの祭壇が鍵だ。北西へ行け。洞窟の上の丘で……Twilight's Hammerがある遺物を守っている。それを取り戻して、Suntaraの祭壇に置くのだ。\n\n<瀕死の考古学者は倒れた。>", "祭壇は空っぽだ。", "mysterious artifactをSuntaraの祭壇に置く。", 0x2d84374c, 0xdca71d8a, 0x3df5ce39, 0xa6dc1ec3, 0xcfff63de, "....." },
  [3373] = { "The Essence of Eranikus", "Essence of EranikusをEssence Fontに入れて下さい。Essence FontはSunken Templeのこの住処にあります。", "宝石に触れると、深い声が頭の中に響き渡る。\n\n「定命の者よ、この願いを聞け。我はGreen DragonflightのEranikus、この呪われた神殿の守り手なり。トロールどもが二度とあの忌まわしき神を呼び出さぬよう見張るという我が務めは、今のところ失敗に終わった。この宝石に我が本質の一部を込めるにつれ、Dreamへの我が掌握が混沌へとねじれていくのを感じる。頼む――この宝石を我が巣の本質の泉に置き、そこにある我らの魔法で我が心から穢れを清めさせてくれ。我が安らかに眠れるように。」", "Eranikusが教えてくれたエッセンスの泉に近づくと、再び彼の声があなたの心に触れる。\n\n「そうだ、定命の者よ。このエッセンスの泉が、この宝石に宿る我が精神の穢れなき部分を贖ってくれよう。宝石を泉の中に置き、Green Dragonflightの魔法によって我が身から堕落と穢れを清めるのだ。そうして初めて我は真の解放を得、そうして初めてDragonflightはAtal'aiに対する管理の務めを再び果たせるようになるのだ。」", "あなたは宝石をエッセンスの泉の中に納めた。\n\n「感謝する、定命の者よ、そなたは――いや……これは、これはあり得ん！やめろ！この呪われし神の穢れは、Green Dragonflightのエッセンスの泉の神聖ささえ汚すというのか！やめてくれ、我が本質が引き裂かれていくのを感じる！この痛み！永遠の悪夢が我を捉えていくのを感じる……」\n\n「定命の者よ、頼む！これを止めるためにGreen Dragonflightの一人を見つけてくれ……助けてくれ……我は闇に縛られ……永遠の苦悶の中に……頼む、苦しめないでくれ……」", 0x1b4a9b28, 0x3918be39, 0xea0661cc, 0x25aa7bf2, 0xc5685f76, "....." },
  [3374] = { "Eranikusのエッセンス", "Oathstone of Ysera's DragonflightとChained Essence of EranikusをSwamp of SorrowsのIthariusのところへ持って行って下さい。そこで、Ysera's Dragonflightに手を貸すかどうかを選ぶことになります。", "Oathstoneに触れると、Ithariusが石を通して直接あなたの心に語りかけてくる。\n\n「このOathstoneに込められた務めを受け入れることで、そなたは我が大義と、Ysera's Dragonflightの大義――Eranikusの堕落した魂を贖うこと――に力を貸すと誓うのだ。最初の犠牲は、そなたと我がこれから払うであろう多くの犠牲の一つとなろう。それは、Eranikusの精神に残る、自由な意志を持つ部分を縛りつけてきた宝石を、我に引き渡すことだ。」\n\n「これを成せ、{name}。そうすれば我らは力を合わせ、贖われるにふさわしい魂を贖うであろう。」", "さて、ここに至ったぞ、{name}。またしても岐路だ。再び選択をすべき時が来た。定命の者よ、そなたはどちらを選ぶ?", "そなたは選択をした。そして、事は始まる。これまでのそなたの選択は、我が正しいと考えるものであった。この先もそうあり続けるかどうかは、今後のそなたの行いと功績によって決まるであろう。", 0x1b4a9b28, 0x028ab8e5, 0x066c19dc, 0x05791b0e, 0x2675acb2, "....." },
  [3376] = { "Sharptuskを倒せ!", "Red Cloud MesaのBrave WindfeatherにChief Sharptusk Thornmantleの頭を渡してください。", "{name}、君のことは聞いている、新人。ひょっとしたら、他の者が失敗したことでも、君ならやってくれるんじゃなかろうか。\n\n我々トーレンはこの土地に家を切り開いてきたのだが、犠牲なしにはできない。Brambleblade RavineのChief Sharptusk Thornmantleに率いられたBristleback quilboarたちは、我々に戦をしかけ続け、生活をさいなんでいる。族長を討ち取り、首を持ってくることを命じる!\n\n東の渓谷にある仮設村で、彼を見つけられるだろう。", "私のもとに奴の死の証を持ち帰れば、Sharptuskがもう我々を悩ませることはない。私が求めているのは奴の首だ、{name}。\n\n我らトーレンは狩りのために生きている。そして、こちらを狩り返すほどの狡猾さを持つ相手との狩りほど偉大な狩りはない。この務めを果たせば、若いの、私の言う意味が分かり始めるだろう。", "今日この日、迅速な働きによって正義がもたらされた。{name}。この行いは、我々の郷を脅かすすべての者たちへの警告となるだろう。\n\n滞在の助けになる報酬は、君の努力の賜物だ。若き{class}よ。", 0x1204c4b0, 0xa500ec30, 0x72c9ab91, 0x5068b9a6, 0x42acf4c0, "....." },
  [3377] = { "Prayer to Elune", "Zamaelが語る話を聞いて下さい。", "我に力を貸してくれるか、定命の者よ？ 我が話を聞け。", "私の話を最後まで聞いてくれ。", "私はこの檻の中での運命を受け入れました。ですが、祈りは見つけなければなりません。", 0x033b2fe0, 0x90a3b258, 0x68d49b69, 0x5c717573, 0x6d9aa4c2, "....." },
  [3378] = { "Prayer to Elune", "Prayer to Eluneを見つけ、DarnassusのAstarii Starseekerのところへ持って行って下さい。", "我に力を貸してくれるか、定命の者よ？ prayer to Eluneを見つけてくれるか？\n\n話したとおり、そのprayerは金の石板に刻まれていた。偶像を崇めるこの悪党どもの誰かが、それを身につけているはずだ。\n\nもしprayerを取り戻したなら、DarnassusのAstarii Starseekerのもとへ持っていってくれ。我がこの世界とそこに住む者たちに対して数えきれぬほどの悪行を働いた後で、信仰を取り戻したことなど大した意味はない。だが、我が祈りは聞き届けられねばならぬ。赦しなど、我が最も期待していないものだ。", "何の用でTemple of the Moonへ来たのですか、{name}?", "今宵、Eluneがあなたに微笑んでいます、{name}。あなたは迷える魂を彼女のもとへ還してくれました。どうか、私たちの感謝のしるしとして、これを受け取ってください。", 0x033b2fe0, 0x4ad2902a, 0x5e5c5ebc, 0x08a22fe6, 0xa1cb3fb2, "....." },
  [3379] = { "影織る者", "Searing GorgeをうろついているShadow Silk Poacherの一団を殺して下さい。 Nilithには、Shadow Silk Poacher 5名を掃討する必要があると信じる理由があります。この仕事を終えたらSearing GorgeのNilithのところへ戻って下さい。", "Searing Gorgeの蜘蛛は、shadow silkの貴重な供給源だ。知ってのとおり、shadow silkは我々の業界の職人たちにたいへん求められている。\n\n最近、密猟者の一団がこの地に入り込み、自分たちの行いが長い目で見てどんな影響を及ぼすかなど考えもせずに、蜘蛛を手当たり次第に大量に殺している。そこで最初に頼む仕事は単純なものだ。奴らを見つけ出し……始末してくれ。\n\n捜索は北から始めるといい。\n\n助けが必要なら、Razeと話してくれ。", "どんな情報を持っている?", "見事な働きだ、{name}。\n\nこれはあなたがまだ見たことのないshadoweaveの一片に違いない。", 0xa980b06f, 0xcb129914, 0xdfea1643, 0x9a301625, 0xf0243f05, "....." },
  [3380] = { "The Sunken Temple", "TanarisにいるMarvon Rivetseekerを探して下さい。", "この世には安らげぬ魂がいる、{name}。孤独によって穢され、古の悪に縛られた魂が……\n\n大地の奥深くにある場所の話を聞いたことがある――私がこれまで見たこともない強大な力によって、そこへ追放された場所だ。\n\nその場所、Sunken Templeについてもっと知りたければ、Marvon Rivetseekerというゴブリンを訪ねるといい。彼は世界の多くの古代遺跡を研究してきた者で、最後に聞いた話では、Tanarisのトロールの遺跡を調べるためにRatchetの家を出たそうだ。", nil, "ああ、Sunken Templeか。あれはこの目で見たと言えるとも。もっと詳しく聞きたいかね？\n\nあなたは冒険を好むたちのようだ。興味を引きそうな話をいくつか知っているぞ……", 0x49245186, 0xd5fc3f18, 0x8e0c57bd, nil, 0x8af0f4e1, "...m." },
  [3381] = { "師匠との会見", "Sanath Lim-yoの主人と話したければ、Undamaged Hippogryph Feathersを$N1枚、AzsharaのSanath Lim-yoのところへ持って行って下さい。", "ああ、若い{race}がSanathに話をしに来たか。何とすばらしい日だ！ あなたがご来臨くださるとは、まことに光栄の至り。ありがとう！\n\n頼むから……私の皮肉を褒め言葉だと思い上がらないでくれ。一つはっきりさせておこう。私はお前が好きではない。だが、このちょっとした会話は私たちとは何の関係もない。私の師匠に関わることだ。\n\n私の矢に使うhippogryph feathersを二、三枚持ってこい。そうすれば、師匠に会うのを許してやろう。十分にふさわしいと分かった冒険者がいたら、自分のところへ送るようにと言われているのでな。", "私は主人の命でここに留まっている。主人の塔までの送り賃は、好きな値をつけていいと許されているんだ。今のところは、旅人一人につきfeathersを2枚だけもらうことにしている。自慢の矢を作り続けるためにね。\n\n気をつけないと、値上げするよ。半ダースのゴールドなんてどうだい?\n\nやっぱりそう思ったよ。まあ、行儀よくしていれば値段はこのままにしておくさ。", "頼んだとおり、羽根が2枚。それも、なかなか悪くない品だ。\n\n準備はいいか? 一言言えば、すぐに送り出してやる。\n\nああ、それからもう一度言っておくが、気をつけることだ……我が主人は愚か者を好まぬが、主人を喜ばせる者にはとても寛大なのだ。", 0x7ce7cb7c, 0xeebf2cce, 0xcdcdd2e9, 0x33ecde61, 0x26a739ed, "....." },
  [3382] = { "攻撃を受ける船員たち", "nagaの襲撃から、Captain Vanessa Beltisと彼女の船員たち、そしてHorizon Scoutの乗客を守る。Captain Vanessa Beltisが生き残らなければならない。", "俺たちは、錨を下ろせる安全な避難場所を探して、すぐ沖合にいたんだ。日が沈んでから一時間も経たないうちに、奴らが襲ってきた……あのいまいましいnagaどもが！\n\n奴らが何を探していたのかは分からないが、見つからなかったのは明らかだ。もう一度戻ってきやがったからな。次の襲撃が来たらすぐ知らせるように、斥候を二、三人、谷の入り口で見張らせている。\n\n今ここに来てしまったのは気の毒だがな、{name}、もう俺の手には負えないんだ。\n\n一世一代の戦いの準備はいいか？", "こいつは厳しい戦いになりそうだ……", "やったぞ! ありがとう! これは間違いなく、私が加わった中でも最も過酷な戦いの一つだった。いくら感謝してもしきれない。\n\n乗組員がもっと大勢この試練を生き延びられていたらと、悔やむばかりだ。\n\nHorizon Scoutの生き残った乗客たちと話してやってくれないか。この辺りに用があった者もいて、君さえよければ、ちょっとした頼みごとが2つほどあるかもしれない。重ねて、助けてくれて本当にありがとう。", 0x81d369b3, 0x8cfbc87a, 0x8e32956b, 0xb5e0794a, 0x343ea4a6, "....." },
  [3385] = { "闇市場", "Trade Master Kovicとその手下Clunkを殺して下さい。死体からTrader's Satchelを取り戻し、Nilithに返して下さい。", "奴らは自らをUndermarketと呼んでいる。相応の値さえつけば、売る、運ぶ、取引する、ほとんど何でもやる非情な商人どもだ。\n\n話はもっと悪い、{name}。奴らはこのSearing Gorgeに活動拠点を築いた。その作戦を率いているのはTrade Master Kovicで、この地のDark Ironのドワーフとも深いつながりがある。\n\n我々は強く叩き、奴らの上層部に思い知らせねばならん。Trade Master Kovicと、その手下Clunkを倒せ。仕事が済んだら、奴のtrader's satchelを持ち帰ってくれ。\n\nCauldronへ!", "Trade Masterはまだ生きているのか?", "あなたはUndermarketに決定的な一撃を与えた。奴らの頭目たちも、これ以上手下を峡谷へ送り込むのを考え直すだろう。\n\nああ、それとtrader's satchelの中には役に立つものは何もなかった。中にあるものは何でも好きに取っておくがいい。", 0xcf667eb3, 0xf4eef121, 0xce7df4b5, 0x6d94a2b9, 0xd4a893c2, "....." },
  [3402] = { "闇市場", "GadgetzanのVizzklickと話して下さい。", "GadgetzanのVizzklickに、Kovicを倒した知らせを個人的に届けてもらいたい。Kovicが死んだと聞いたらすごく喜んで、何か素晴らしい報酬をくれると思う。", nil, "Kovicが討たれただと？！今日は素晴らしい日だ、{name}！何年もの間、あの悪党はundermarketで怪しげな取引を続け、世界中の正直で勤勉な商人たちを出し抜いてきた。\n\nこの功績には立派な報酬がふさわしい！そして立派な報酬を受け取ってもらうぞ！", 0xcf667eb3, 0x12988fe1, 0xb3552e5b, nil, 0x8fb04460, "...m." },
  [3441] = { "神の報い", "Velarok Windbladeが語る話を聞いて下さい。", "我が話を聞け、冒険者よ。", "最後まで話させ……{race}。", "もう十分に聞いたか? 行動する覚悟はできているか?", 0xa32f5c7d, 0x3d7177a4, 0xaefd1f11, 0x8a28a26a, 0xf4e4b7a3, "....." },
  [3442] = { "完璧な炎", "Hearts of Flameを$N1個とGolem Oilを$N2瓶集め、Velarok Windbladeのところへ持ち帰って下さい。", "正しい決断をしたな、{name}。\n\n最大の打撃を与えられる場所を叩かねばならん。四つの見張り塔だ。\n\n四つの塔が炎に包まれれば、奴らが反応する前に攻勢を仕掛けられる。\n\n塔に火を放つには、しかるべき道具が要る。その道具を作るには、材料がいくつか必要だ。\n\nhearts of flameを四つとgolem oilを四つ持ってこい。そうすれば、完全なる炎の松明を作ってやろう。\n\nこの地のgolemsとelementalsを、まず狙うがいい。", "素材は集めたか?", "よくやった、{name}。準備はほぼ整った。", 0x74ef41b1, 0xff79791f, 0x0085154c, 0xb9773f73, 0x032b23bf, "....." },
  [3443] = { "柄の鍛造", "Thorium Plated Daggersを$N1本、Velarok Windbladeのところへ持って行って下さい。", "完全なる炎を収めるには、柄と覆いが要る。まずは、ふさわしい柄を見つけねばならん。\n\n大釜のDark Ironの監督や奴隷使いどもは、魔法のかかったthoriumの武器を使っている。thoriumはきわめて頑丈な合金だ。thorium plated daggersを八本持ってきてくれれば、その合金を分解して、柄に打ち直せる。", "8本だ、{name}。8本要るんだ!", "君は並外れた働き手だな、{name}。転職を考えたことはないか? 探偵なんてどうだ? ガラクタ集めは? ああ、そうだ、金属探知の仕掛けを抱えてAzerothの浜辺を這い回り、失われた宝を探している、あの間抜けなノームどもの一人なんてどうだ。うん、それこそ君にうってつけの職だ。", 0x95631eee, 0x2ccc04fd, 0x723eec46, 0x4b5e1cf6, 0x854a703c, "....." },
  [3444] = { "Stone Circle", "RatchetにあるMarvon Rivetseekerの作業場からStone Circleを回収して下さい。", "かつて私は、Sunken Templeの不吉な部屋に足を踏み入れたことがある。あの場所の悪は、入る者すべてに染み込む。今では床を覆う軟泥をかき分けながら、なんとか外へ出るのがやっとだった。覚えているのは、蛇の像で埋め尽くされた大きな円形の部屋をよろめきながら通り抜けたことだけだ……\n\n最近、同じ蛇の紋様が刻まれているらしい丸い石を見つけた。それを梱包して、Ratchetの工房へ送らせておいた。それを取ってきてくれれば、もっと詳しく話せるかもしれない。", "Ratchetはここから遠くない、{name}。長い旅にはならないはずだ。", "そうだ……これがあの石だ。\n\n今、すべてが思い出されてくる、{name}……", 0xf6d90021, 0x0818ded7, 0x01a3b0a9, 0x56b42f76, 0x83595b35, "....." },
  [3445] = { "The Sunken Temple", "TanarisにいるMarvon Rivetseekerを探して下さい。", "大地の奥深くにある場所の話を聞いたことがある――私がこれまで見たこともない強大な力によって、そこへ追放された場所だ。\n\nその場所、Sunken Templeについてもっと知りたければ、Marvon Rivetseekerというゴブリンを訪ねるといい。Troyasや私と同じく、彼も世界の多くの古代遺跡を研究してきた。最後に聞いた話では、Tanarisのトロールの遺跡を調べるためにRatchetの家を出たそうだ。\n\n彼を見つけられるといいのだが。しばらく消息が途絶えているのでね。", nil, "ああ、Sunken Templeか。あれはこの目で見たと言えるとも。もっと詳しく聞きたいかね？\n\nあなたは冒険を好むたちのようだ。興味を引きそうな話をいくつか知っているぞ……", 0x49245186, 0xd5fc3f18, 0x00e8289e, nil, 0x8af0f4e1, "...m." },
  [3446] = { "深淵へ", "Swamp of SorrowsのSunken TempleにあるAltar of Hakkarを見つけて下さい。", "神殿の中で、6つのバルコニーがある円形の部屋を見つけたんだ。どのバルコニーの縁にも蛇の像があってね。気になって、そのうちの一つを押してどうなるか試してみたら、罠だったのさ! 爆発で危うく死ぬところだった。岩棚に倒れたまま下を見たら、部屋の底にもう一つ像があるのに気づいたんだ。祭壇みたいなもので……たしかHakkarって呼ばれてたと思う。\n\nその祭壇が秘密の鍵だと思うんだ――このトークンを、Sunken Templeの祭壇へ持って行ってくれ。", "像を調べると、側面にくぼみがあることに気づく。ちょうどMarvonにもらった証と同じ大きさだ……", "あなたはstone circleを窪みへ押し込む。かちりと固定される音が聞こえた。\n\n石が収まった今、先へ進むことができる……だが、次に何をすべきだろうか？\n\nこの祭壇をもっと調べてみるべきかもしれない……", 0xbc552e93, 0xd3d3a647, 0x5b0928d1, 0x3e0007dc, 0x923bbc72, "....." },
  [3447] = { "環の秘密", "Sunken Templeへ行き、石像の環に隠された秘密を暴いて下さい。", "記憶ははっきりしないが、話せることは話そう。Sunken Templeの像の輪は危険だが、さらに大きな財宝を解き放つ秘密を握っていると私は思う。\n\n中央の祭壇から、一連の光を灯すことができた。その光が何を意味しているのか解き明かせれば、この部屋に隠された秘密が何であれ、解き放てるかもしれない。\n\nだが警告しておくぞ、{name}。神殿には大いなる悪が潜んでいる。価値あるものは何であれ、厳重に守られているだろう……", nil, "偶像の目は、神殿の薄暗がりの中でも明るく輝いている。その透き通った奥に、何か光るものが見える。目を横へ滑らせ、手を差し入れて、像の内にあるものを掴み取った。\n\nAtal'aiの宝は、今やあなたのものだ。", 0x6accd531, 0x0d09a55c, 0x42f0e580, nil, 0x0b0e6c7b, "...m." },
  [3448] = { "重荷を託す", "IronforgeのTymorと話して下さい。", "最近、Azsharaの調査を任されたところなんだ。かつてはエルフが故郷と呼んだ美しい地域だ。エルフがまだ魔法を使っていた頃の話さ。今では美しいというより危険な場所だが、だからといって、俺たちが過去の答えを求めてあらゆる石をひっくり返すのをやめるわけじゃない。\n\n俺の仲間のTymorって奴が、この一帯の調査を手伝うと申し出てくれた。そういうことに特に興味があるんでな。\n\nあいつはこの街のHall of Mysteriesの右隣に、小さな家を持ってるよ。", nil, "ああ、Karnikに言われて来たのか。そろそろ彼から連絡があると思っていたよ。Azsharaについて素晴らしいことをいろいろと発見したんだ……ナイトエルフが途方もなく長い寿命を持っていることは知っているけれど、誰でも時には、自分の人生の……不幸な出来事を忘れてしまうものだ。批判のつもりじゃない、ただの所見だよ。\n\nはるか昔、elvesが築いた都市があって、そこには魔法や他の失われた技についての知識が満ちていた。そういうことを学ぶ身として、私は調査を始めた。見つけたものは実に胸躍るものだったよ。", 0x3addab05, 0xf915132a, 0xc1d05228, nil, 0xbacc0aaf, "...m." },
  [3449] = { "秘術のルーン", "Drawing Kitを使って、Rune of Beth'Amara、Rune of Jin'yael、Rune of Markri、Rune of Sael'haiの拓本を取り、Azshara南部の半島の沖にある小島へ向かって、Pilot Xiggs Fuselighterに迎えの合図を送って下さい。", "一部のエルフにとって、魔法はかつてElune自身と同じくらい崇められていました。彼らの中でも最も強力なメイジたちは、秘術の規則や自らの発見についての洞察を記したルーンや石板を作りました。そして、誰もが思索できるよう、それらを公の場に残したのです。\n\nRuins of Eldarathにあるそのルーンの拓本がぜひとも欲しいのです。拓本を取るためのkitはお渡ししますが、ルーンを見つけるのはあなた次第です。でも気をつけてください。Eldarathに興味を持っているのは、Explorer's Leagueだけではありませんから。", "おやおやおや、よくここまで来てくれたね、{name}。Tymorのための拓本は取れたかい?\n\nここは危険な場所だけど、海岸沿いではそれほど騒ぎは起きていないんだ。水中を泳いでいるnagaのせいかもしれないけど、それは私の問題じゃない……私が見回るのは空だからね。", "無事で何よりだ、{name}。あまり大変じゃなかったならいいんだが。\n\nこれはすぐにTymorのところへ届けるよ。こういう物を見られて、あいつも大喜びするだろう。\n\nフレアガンは捨てちまっていい……どうせもう役に立たないだろうし、俺はもう新しいのを手に入れたからな。", 0x34f133ac, 0x434c007c, 0x1b184c56, 0x1803d3d6, 0xbd0b8d4a, "....." },
  [3450] = { "簡単な受け取り", "IronforgeのXiggs Fuselighterと話して下さい。", "拓本は私の塔に届けてほしいのですが、あなたにわざわざそこまで行ってもらう必要はありません。Azsharaから空輸させましょう。\n\nXiggs Fuselighterは私に借りが一つ二つあって、近いうちにその辺りに来るはずです。海岸の巡回の仕事を引き受けたのです。出発する前に彼と話してください。彼に合図を送るための信号銃をくれるでしょう。拓本が手に入ったら、彼に言われた場所へ行って、それを彼に渡してください。そうすれば彼が私の塔まで無事に届けてくれます。彼はMilitary Wardの格納庫にいるはずです。", nil, "何の用だい、{name}? 長旅に向けて船の準備をしてて、今ちょっと忙しいんだ。戦車のパイロットたちに会いにこっちへ来たところでね。操縦席の内張りにwendigoのたてがみが要るんだが、あいつらはたいてい余分に持ってるんだ。\n\n手短に済むなら少しは時間を割けるよ……若いのが一人、下のSteelgrill's Depotのパイロットたちにたてがみの余りがないか確かめに行ったところだからね。", 0xc51063db, 0x319e159e, 0x406ea5f6, nil, 0xc77d6b8a, "...m." },
  [3451] = { "迎えの合図", "IronforgeでXiggs Fuselighterと話し、Standard Issue Flare Gunを受け取って下さい。", "ああ、じゃあTymorに言われて来たのか？ ああ、あいつには借りが一つ二つあるよ。何だって？ まったく、あのちびの悪ガキめ。ああ、それなら手を貸してやれるよ。つまり、flare gunと場所が要るってわけだな……お安いご用さ。\n\nAzsharaの南の半島の沖に小さな島があって、俺たちはそこに着陸場を作ったんだ。このflare gunを持っていって、そこで使いな。合図が見えたら、あいつが欲しがってる……その何だか知らないもんを拾いに行くよ。", nil, "ほら、俺のstandard issue flare gunだ。撃った後は辛抱強く待ってくれよ。こいつには弾が数発しか入ってないし、俺が沖のどのあたりにいるか次第で、そっちへ行くのに少しかかるかもしれない。フレアを撃ったら、とにかく沖のほうを見ていてくれ。", 0x111e6b45, 0xcd6871bc, 0x0ad9695b, nil, 0xebcc5e87, "...m." },
  [3452] = { "炎の外殻", "Symbol of Ragnarosを見つけ、Velarok Windbladeのところへ持ち帰って下さい。", "松明を形作るのに、最後の部品が一つ要る。\n\n北西の山中に、Twilight's Hammerの大きな野営地がある。奴らは自分たちの神を崇める象徴や偶像を持ち歩いているという噂だ。その象徴や偶像なら、魔法の覆いを形作るのに十分な魔力を帯びているかもしれん。symbol of Ragnarosを一つ持ってこい。その品から魔力を取り出して、覆いを作ってみよう。", "適切な秘術エネルギーの源がなければ、torch of retributionは完成しない。", "この印からは邪悪な魔力が放たれている。我らの務めにうってつけだ。", 0xf6dbe91a, 0xa55f0a57, 0x82d0ba66, 0xf41fce2b, 0x5608c2de, "....." },
  [3453] = { "Torch of Retribution", "Velarok WindbladeがTorch of Retributionを完成させるのを待って下さい。", "部品を組み合わせ、必要な魔力を付与するまで、少し待て。", "チャネリングの過程を邪魔するでない。", "そなたが果たさねばならぬ最後の務めが、1つ残っている。", 0x302cf31b, 0x71e960aa, 0x261e14d8, 0x0a1289be, 0x5248e48e, "....." },
  [3454] = { "Torch of Retribution", "Torch of Retributionを受け取って下さい。", "今度は、torchをその持ち主に結びつけねばならん。torchを手に取れ、{name}。", nil, "両手で松明をつかむと、憎しみと怒りの波が全身を脈打つように駆け巡る。", 0x302cf31b, 0xaeeb041a, 0xab51fc7a, nil, 0x7f85ed76, "...m." },
  [3461] = { "Tymorのもとへ戻る", "TymorのDrawing KitをIronforgeにいる彼に返して下さい。", "Tymorからは、あんたに払うものを何も預かってないんだ。だから、Ironforgeに戻ったらあいつに掛け合うといいよ。きっとまだMystic Wardの家にいるはずだ。とにかく訪ねていって、しっかり払わせるんだな。ここはピクニックとはわけが違う……それは確かだ。\n\nそれでも、あいつを手伝ってくれてありがとうな。幸運を祈るよ。\n\nああ、それと、写生キットはもう要らないんだ。あいつに会いに行くときに、Tymorに返してやったらどうだい？", "戻ってきたか! 素晴らしい。drawing kitも持ってきてくれたか?", "素晴らしい! それを聞いてとても嬉しいよ。\n\n早く塔に戻って、あの拓本をじっくり調べたくてたまらないよ。君がうらやましいな……Azsharaのような場所へ行けるなんて。秘術を学ぶ者なら誰もが夢見ることだろうね。\n\nさて、君はExplorer's Leagueのために働いていただけだから、報酬の話は一度もしなかったけれど、君は何かを受け取るに値するよ。", 0x260f8ba5, 0x90d05445, 0x3997cdc0, 0x03a24046, 0x34b90840, "....." },
  [3462] = { "Squire Maltrake", "Squire Maltrakeと話して下さい。", "我が使者、Squire Maltrakeと話せ。Torch of Retributionの使い方について、さらに指示を与えるだろう。", nil, "一撃を加える覚悟はできているか?", 0x0069fcce, 0x987eebfd, 0xbabc11c0, nil, 0x1e917c10, "...m." },
  [3463] = { "火を放て！", "North、South、East、WestのSentry Towersのそれぞれの建物の中でTorch of Retributionを使い、火を放って下さい。", "よく聞け、{name}。四つの塔は決して破壊できないが、torch of retributionを使えば、とても長い間火を放ち続けることができる。どんな元素も力も鎮められぬ炎だ。\n\n塔が燃えている間は、衛兵も見張りの部隊も監視所にとどまることはできない。そうなれば、奴らの第一の防衛線は無力になる。\n\nそれぞれの塔に入り、その防御の内側でTorch of Retributionを使わねばならん。Dark Ironsの精鋭の見張り部隊には気をつけろ、{name}。", "道に迷ったのか、{name}?", "見事です! 見事ではありませんか、ご主人様?", 0x41623cfd, 0x9b337002, 0xe9f6762f, 0xf721a64c, 0x5652553c, "....." },
  [3481] = { "装身具……", "箱を開けて下さい。", "箱には鍵がかかっているようだ。", nil, "あなたが触れると、箱が開く。この中にどれほどのチーズが入っているのだろう? 確かめる方法は1つしかない。", 0xba04bbaa, 0x6a8234a8, 0xa520e789, nil, 0x5f10c2f0, "...m." },
  [3501] = { "すべては量がものを言う", "Imperfect Draenethyst FragmentsをKum'ishaのところへ持って行くと、渡した一つごとに報酬がもらえます。", "flawless sphere of draenethystは見つからないかもしれないが、この地を探索するうちに、draenethystのさまざまな不完全なかけらをきっと見つけるだろう。\n\nKum'ishaがその傷のあるかけらを使って故郷へ帰れるかは疑わしいが、そのかけらはdraeneiにとって他の役に立つ使い道があるかもしれない。\n\n見つけたflawed draenethyst fragmentsは何であれ持ってくるがよい。そうすれば報いよう。", "探索で何か成果はあったか?", "本当に反吐が出るな、{race}。いい大人がガラクタの山によだれを垂らしているとは? 情けない! 報酬を持って、とっとと失せろ。", 0x710e9f91, 0xf35fbef0, 0xd8e321c4, 0x480f2e19, 0xe2c4a2a8, ".....", nil, nil, nil, nil, 0x93155b22 },
  [3504] = { "裏切り", "Sealed Letter to Ag'torをAzsharaのAg'tor Bloodfistに届けて下さい。", "裏切り者の、泥棒エルフ! 俺はあの女をそう呼んでる……あの女はこの先もずっとそういう奴だ!\n\n{name}、俺は重大な間違いを犯したに違いない。俺はブラッドエルフを信じたんだ。\n\nあの女はAzsharaが巨万の富と……強力な品々を持っていると言っていた。あの女を守るため、俺は安易に幾人かの戦士を送り、報いられるはずだった。ああ、どいつが阿呆か見てみるがいい……あの女、戦士を全部殺しやがった。\n\n{name}、復讐したいんだ。だが、誰かを送ることはできない。Haldarr Encampmentの北、ValormokにいるAg'torを見つけてくれ。詳しいことは彼に聞いてくれ。", "ほう、Belgromもようやく賢くなって、自分の配下じゃない者を助けによこしたってわけか?\n\nこの野営地にはかつて12人のウォリアーがいたんだ、{name}。だが今は全員死んだ。あのメイジ、Rimtoriが皆殺しにしたんだ。あの女はBelgromをリュートみたいに弄んだ……誘惑までしてな。俺の知ったことじゃないが、ここだけの話、あいつは大した妖婦だよ。俺がまだここでBelgromを手伝っているのも、たぶんそのせいだ――俺でもきっと同じことをしただろうからな。", "あの女とその手下どもには持てる限りの者を送り込んだが、奴らは戦いに強い。誰一人戻ってこようとはしなかった。死んだ者もいるだろうが、他の者はただ逃げ出したに違いない……臆病者どもめ。\n\nだが援軍が到着した今、まだ何かできることがあるかもしれん。嘘をつきBelgromを裏切ったあの女を、まだ罰することができるかもしれん。\n\nどうだ、乗るか？", 0xebf1036b, 0xfb1801e8, 0x24633632, 0x2f76370e, 0x03d70660, "....." },
  [3505] = { "裏切り", "Magus Rimtori's campを探し出す前に、Blood Elf Reclaimer・Blood Elf Surveyorを10人殺して下さい。Magus Rimtori's campを見つけたら、女を戦いに引きずり込むことのできる、彼女にとって大切であろう何かを探して下さい。", "そんなことだろうとは思っていた。\n\nAzshara北半島の南の断崖に沿って、あの女の手下どもに対する報復を始める。血の怒りと共に奴らを殺せ……裏切る相手を間違えたのだと思い知らせてやれ。\n\n女についてはまだ心配しなくていい……あいつは護衛と一緒にAzsharaの探索をするのに時間を費やしている。手下どもを殺した後、女の野営を見つけるのが賢いやり方だろう。どこで女を攻撃できるか偵察するのが賢いだろうよ。\n\n女を呼び出すのに使える何かがあるはずだ。", "本のタイトルは黒い革の表紙に金箔で刻まれている――Kaldorei Tome of Summoning。ページを開くと、この本はとても古いものの、極めて良い状態であることが分かる。\n\n文章は何かの古代語のようだ……もしかするとKaldoreiの言葉だろうか?\n\nblood elvesの裏切りに報いを与え終えたら、ここへ戻ってくるべきだと直感が告げている。", "黒い絹製の薄いしおりで目印をつけられたページまで、あなたはざっと目を通した。\n\n文字を解読しようとした時、あなたはあるページの一番下に描かれた図を見つけた。目の前の光景を素早く見渡し、地面の水晶や円陣やその他の物が、本に描かれた図と同じように置かれているのに気が付いた。", 0xebf1036b, 0xda5e2dce, 0xb1d5f78a, 0xe0f0f6a7, 0xe176809c, "....." },
  [3506] = { "裏切り", "Magus Rimtoriに関係したarcane focusing crystalを破壊し、彼女を討ち取って下さい。その後、Head of Magus RimtoriをAzsharaのAg'tor Bloodfistの元へ持って行って下さい。", "数分考えて、頭にいくつかのアイディアが浮かんだ。あるひとつの考えにあなたは笑みを浮かべた。Belgromの裏切りとオーク殺害に関与したブラッドエルフは、水晶の破壊に動揺するのではないだろうか?\n\nあなたは文と絵の解読をさらに続け、あるひとつの水晶がこの円陣の術者と関係していることに気が付いた……他の水晶はもっと邪悪な何かと関係している。\n\nあなたは本を閉じ、どの水晶を破壊すべきか決めることにした。", "blood elfの裏切り者どもの殺戮は進んでいるか、{name}? 何か成果はあったか?\n\nお前こそがあの犬を跪かせるほど強い者であることを願っているぞ! あの女がしてきたことを思えば、苦痛に満ちた死以外にふさわしいものはない!", "マジか!! 信じられない!\n\nやってくれたな! Belgromが喜ぶよ! 多くの戦士たちの魂もようやく安らかに眠れる。どうもありがとう、{name}。", 0xebf1036b, 0x7c93eea7, 0xae3913b5, 0x95829dd6, 0xa4ec0c3f, "....." },
  [3507] = { "裏切り", "OrgrimmarのBelgrom Rockmaulに話しかけて下さい", "OrgrimmarのBelgromのところへ戻ってくれ。彼も自分の目でこいつを見たいだろう! 我々もすぐ戻る。\n\nああ、今日は本当に良い日だよ。君の助けに感謝するよ、{name}。", "覚えているぞ、{class}。俺を裏切ったあの女を始末しにAzsharaへ行ってくれと頼んだな! もうずいぶん昔のことのように思える。まさかAg'torや他の者たちも死んだなんて言うんじゃないだろうな!", "ハハ！今の姿を見ろ、哀れな女め！貴様の亡骸に唾を吐いてやる！\n\nありがとう、{name}。心の底から感謝する！今日は実に素晴らしい日だ！\n\n俺にその力があれば、王国をくれてやるところだ！だが、これで我慢してくれ。\n\n<Belgromは自分を裏切ったメイジの首を見下ろす。>\n\nハハ！愚かなblood elfめ、今の姿を見ろ……麻袋に入れられて、体もないとはな！Belgromを裏切るべきではなかったのだ！", 0xebf1036b, 0x93cd53eb, 0x76dc5375, 0x2e6dd780, 0x339d3b7b, "....." },
  [3508] = { "結界を破る", "Loramusが啓示の呪文を終えるのを待って下さい。", "お前は向こう見ずだな、{name}。だがそれは、お前の種族の見上げた性質だ。勝ち目がほとんど、あるいはまったくないというのに、やみくもに戦いに飛び込んでいく。力を貸してやろう。Razelikhの手下がたった一人でも倒れるのを見るためだけにでもな。\n\nRazelikhの配下どもにかけられた守りを破るには時間がかかり、希少な遺物を手に入れねばならん。\n\n静かにしていろ。まず、啓示の儀式を行わねばならん。私が集める知識は、大いなる力を持つ武器を鍛えるのに役立つだろう。", nil, "その獣の名を突き止めねばならぬ。", 0xd775797a, 0x0104195d, 0xd405f8b2, nil, 0xf09e3aa3, "...m." },
  [3509] = { "獣の名", "AzsharaのLord Arkkorocと話して下さい。Temple of Arkkoranを見つけるには、水辺から探し始めて下さい。", "悪魔の王とその手下どもを傷つける方法は、ただ一つしかない。奴の真の名を刻んだ力ある武器を鍛えねばならんのだ。\n\nそのような武器が鍛えられれば、悪魔とその配下すべてが無防備になる。\n\nAzsharaには下位の神が住んでいる。Lord Arkkorocだ。彼を探し出さねばならん。だが気をつけろ、見つかれば、彼の手下どもはお前を滅ぼすためなら手段を選ばぬだろう。\n\nそのような情報を得るには、間違いなく何らかの代償を払わねばならんだろう。", nil, "悪魔の君主だと?\n\n<Lord Arkkorocは笑う。>\n\nその情報については、この者が力になれるやもしれぬ。だがまずは、そなたがこの者に力を貸さねばならぬ。", 0xa611ce38, 0x6018f1ae, 0xa96f0987, nil, 0x6af53384, "...m." },
  [3510] = { "獣の名", "Hetaeraを倒し、Hetaera's Bloodied Head、Hetaera's Beaten Head、Hetaera's Bruised HeadをLord Arkkorocのところへ持ち帰って下さい。", "あの女は我が子らを殺す、定命の者よ。この海の支配者を名乗る女だ。偽りの神、それ以外の何者でもない。あの女を打ち砕き、そのheadsをすべて持ち帰るがよい。\n\nそうすれば、そなたの求める名と、それに劣らず重要なものをもう一つ授けよう。\n\nあの女は産卵場をうろついている……Hetaeraという名だ。\n\n<Lord Arkkorocは南西を指さした。>\n\n行け！", "<Lord Arkkorocはかがみ込んであなたを調べる。>\n\nあれはどこだ?", "ついに、Arkkorocの知恵にふさわしい者が現れた!", 0xa611ce38, 0xd218c689, 0x6555b2ac, 0xde44a003, 0x04ec8c62, "....." },
  [3511] = { "獣の名", "鍛えられたものをLoramus Thalipedesのところへ持ち帰って下さい。", "約束どおり、悪魔の王の名を明かそう。Razelikh the Defilerだ。だがその前に、お前の旅のためにこの上なく重要なものを用意せねばならん。\n\nお前が作ろうとしている武器には焼き入れ剤が要る。この首から血を抜き取るので、少し待て。\n\n<Lord Arkkorocは巨大な拳で首を握りつぶし、血を搾り取る。>\n\n焼き入れ剤を、その獣の名、Rakh'likhとともにLoramusのもとへ持ち帰れ。", "戻ったか! 驚いたぞ、{race}。真の名は分かったのか?", "この焼き入れの液が、武器を鍛えるのに必要な激しさを加えてくれる。その完成まで、残る工程はあと1つだけだ。", 0xa611ce38, 0x68861385, 0x4e66ca0d, 0x6c8a8f84, 0x38e867c7, "....." },
  [3512] = { "Eranikus自身の言葉で", "Winterspringの東部へ行き、Umbranse the Spiritspeakerと話して下さい。", "{name}、我々の最初の一歩は、宝石を通してEranikusと話す方法を考え出すことです。彼は今、眠りと死のはざまの危うい状態にあり、悪夢の織物の中でねじ曲げられています。あなたが渡してくれた精髄はひどく穢れていますが、彼に届く可能性はあります。\n\nはるか遠く、東Winterspringの氷の地へ向かい、我々の定命の友の一人、Umbranse the Spiritspeakerを訪ねてください。彼は死者の代弁をする人間の霊媒です。Eranikusは本当に死んでいるわけではありませんが、それでも彼は我々の助けになるかもしれません。", nil, "Ithariusがそなたを我のもとへ送ったのは賢明であった。Eranikusは、そなたらの理解する意味での死を迎えたわけではないが、間もなく自らの言葉で我らに助言を与えるであろう。だが今のところ、我はそなたを直接助けることはできぬ……少なくとも、まだな。\n\n死者と語る我が技をそなたに貸そう。だがまずは、我とは違って老いの衰えに縛られぬ者の助けが要る。我が最も強力な占いの道具が、我が意に反して奪われてしまった。それを取り戻さぬ限り、我らはEranikusを助ける術を持たぬであろう。", 0xd0c7f188, 0xea321243, 0x511aba56, nil, 0x3fc8d4f6, "...m." },
  [3513] = { "Runed Scroll", "Runed ScrollをBarrensのnorthern guard towerへ持って行って下さい。", "公式文書とみられる巻物は、銀色のリボンで固く巻かれている。この巻物に誰かが興味を示すに違いないとあなたは思ったが、興味を持ちそうな者は誰だろうか?\n\n北へ向かったところに、Ashenvaleとの境界に隣接した前哨基地がある。もしこの巻物にナイトエルフに関する情報があれば、前哨基地へ持って行くべきだろう。", "何を持ってきた?", "どれ……どこでこれを見つけた?", 0x4918e4bc, 0xa4caed64, 0x97a4a11f, 0x0364734f, 0xa9e181b5, "....." },
  [3514] = { "Hordeの存在感", "Talon Denの指導者、Rynthariel the Keymasterを殺して下さい。", "Stonetalon PeakにあるTalon Denに、鍵の支配者であるdryadのRyntharielがいる。この巻物は、策略家のそいつが出したものだ。\n\nあんたがこれを略奪した使者に奴は二度と接触しないだろうがな、ヘッ、俺たちはここを一歩も引きはしないぜ。Hordeは奴のoutrunnerどもを通しやしない。\n\n{name}、Talon Denへ行ってRyntharielを殺してくれ。それから、皆に見えるように象徴を立ててくるんだ。このHorde旗を持って行け、{name}。この旗をTalon Denに立てれば、俺たちの縄張りを通って別の使者を送るなんてふざけた真似は二度としないだろう。", "Allianceを我らの地に入れるわけにはいかん、{name}。このことを知らしめよ。", "あんたタフな奴だなあ! あのRyntharielの巣窟に乗り込んでくるなんて大きな一歩だぞ、{name}。奴らがまたまとまるには時間がかかるだろうから、Barrensに入り込むAllianceのrunnerが少なくなるのに期待できるってわけだ。この道を使って別の使者を送る前に、奴らも考え直すことだろうよ。\n\nありがとうな。", 0x247781f9, 0xe57bf0f8, 0x07dbeb87, 0xc47b2c26, 0x9451d022, "....." },
  [3517] = { "知識を盗む", "Tablet of Beth'Amara、Tablet of Jin'yael、Tablet of Markri、Tablet of Sael'haiを見つけてから、AzsharaのJedigaのところへ戻って下さい。", "正直に言うわ、{name}。Azsharaでの境遇を、私は最大限に利用してきたの。Belgromの罰にも、それなりの恩恵があったというわけ。\n\n出発する前に少し調べてみたんだけど、価値のある品がどれほどそこらに転がっているか知ったら驚くわよ。\n\nその品を集めるのを手伝ってくれたら、私の取引についてもっと話してあげるし、儲けの分け前もあげるわ。\n\n東のRuins of Eldarathのあちこちに、私が必要としている石板があるの。四つともHighborneの魔法使いにちなんで名付けられているわ。それを取ってきてくれたら、もっと話をしましょう。", "お前に集めてもらっているtabletsは、しかるべき相手に渡せば銅貨の2枚くらいにはなるはずだ。誰に届けるかは見つけてから教える。だが俺も馬鹿じゃない……届けた証拠を見てから、お前の取り分を渡す。\n\nさあ取りかかれ――こっちも暇じゃないんだ。他の奴に手伝いを頼まなきゃならなくなるかもしれん。", "完璧だ、{name}。しかも状態もいい。これなら関係者全員からいい値が取れるはずだ。\n\n必要以上にここでぐずぐずするのはやめよう。稼ぐべき金があるんだ。", 0x47276997, 0x7a5f9504, 0x828570cd, 0x1a819558, 0x7018a42b, "....." },
  [3518] = { "Magathaへの配達", "Tablet of Beth'AmaraをThunder BluffのMagathaのところへ持って行って下さい。", "最初の石板は、トーレンの女性……Magathaという者に渡すの。彼女はThunder Bluffの長老の一人で、トーレンとForsakenの同盟を推し進めている一人よ。長老たちの誰よりも、トーレンとその流儀がForsakenを人間に戻る道へ導けると考えているの。\n\n彼女にTablet of Beth'Amaraを届けて。その石板は、Forsakenを救う方法を見つけるのに彼女が必要としている手がかりかもしれない……少なくとも彼女はそう言っているわ。", "はい、{name}。何かご用ですか? 片付けなければならない用事がたくさんあるので、手短にお願いします。", "ああ、ついにTablet of Beth'Amaraか。Jedigaとの協力関係が破綻したのか、それともあの哀れなオークがAzsharaで命を落としたのかと思っていた。彼女がやり遂げてくれて何よりだ。\n\nBeth'AmaraはHighborneの中でも最も影響力のある錬金術師の一人であった。その魔術師ただ一人が、金属の変成をはじめとする数々の術を極めたと言われている。", 0xd4c2c45f, 0x2ea1ce4f, 0x2c5f5d08, 0x901d8ed6, 0xb3df3437, "....." },
  [3519] = { "困ったときの友", "ShadowglenにいるDirania Silvershineと話せ。", "ううう…。すぐ近くのクモの洞窟を探検していたときに、Githyiss the Vileという名のクモに思い切り噛みつかれてしまってね。酷い毒にやられちまったみたいだ。助けてくれ。\n\nDirania Silvershineと話をして欲しい。彼女はきっと助けてくれるはずだ。\n\n急いでくれ…めまいがひどい…", nil, "なんてことなの。今日はIverronの姿をみかけないとは思っていたのよ。あの辺りのクモには気をつけるようにって、いつも注意していたのに…", 0x14600625, 0xd73f79e1, 0x6dca0a7e, nil, 0xcf23564b, "...m." },
  [3520] = { "Screecherの魂", "Feralasにいるscreecherの魂を3つ捕らえ、Steamwheedle PortのYeh'kinyaのところへ戻って下さい。", "私はFeralasのvale screechersの霊を探し求めている。奴らははるか古の神の眷属で、その霊は神とつながっているのだ。\n\nこのイバラの杖を持ってFeralasへ行け。Feralasの南部と中部でvale screechersを見つけて倒し、倒れた体の上で私のイバラを振るのだ。そうすれば霊が姿を現すよう誘い出せる。その霊に触れ、本質を集めてこい。\n\n私のイバラと集めた本質を持って戻ってくれば、先ほど話した古の神についてもっと教えよう。", "screecher spiritsのエッセンスは集めたか、{name}?", "よくやった、{name}。そろそろもっと明かす時かもしれん……\n\nトロールの間には古い予言がある。死せる神Hakkar、Soulflayerがいつの日かこの地に戻ってくるというものだ。Hakkarの到来はトロール族に喜びと栄光をもたらすと言う者もいれば、その復活こそ万物の終わりの印だと信じる者もいる。\n\n私はこの神話を信じてはいないが、Hakkarのエッセンスが大きな力を秘めていることは知っている。そしてその力は、それを悪用しようとする者たちから遠ざけておかねばならない……", 0x2d7c7613, 0xa123a982, 0x2d39ef63, 0x6a3c5251, 0xe1d531df, "....." },
  [3521] = { "Iverron's Antidote", "Hyacinth Mushroomを7つ、Moonpetal Liliesを4つ、Webwood Ichorを１つ、ShadowglenにいるDirania Silveshineのために集める。", "私の知る解毒剤で、Iverronを助けることができるはずよ。でも、それを作るには幾つか材料が必要ね。\n\nまずHyacinth mushroomsがいるわ。これは木の根元でみつけられる。それか、ここから南にいるgrellからも集められるかもしれないわね。あれはキノコを集めるのが好きみたいだから。次にMoonpetal liliesがいるわね。これは水辺にしか咲かないの。\n\n最後の材料が多分一番厄介でしょうね。Iverronに噛み付いた毒クモから、Webwood ichorを集めるのよ。", "どうか材料を集めてください、{name}。Iverronには私たちの助けが必要なのです。", "こんなに早くあなたが材料を集められたことを、Eluneに感謝しなくてはね！\n\nちょっと待っていて、解毒剤の準備をするわ。", 0xf8fbaf1b, 0x12503cdc, 0x32bb4179, 0xd4e56d7d, 0xbaa1ea59, "....." },
  [3522] = { "Iverron's Antidote", "Iverron's Antidoteを時間内にIverronへ届けろ。Iverronは北の洞窟の傍にいる。", "解毒剤ができたわ、{name}。Iverronがコレを飲むのを見届けてね。\n\n知っておいてもらわなければならないんだけど、この解毒剤、5分しかもたないのよ。だから時間内に届ける必要があるの。\n\n急いで、{name}！", "ああ……{name}、戻ってきてくれて本当に嬉しいです。", "これは…なんだい{name}？\n\nああ、Diraniaは僕を助けてくれるって信じてたよ！\n\n<Iverronが解毒剤を飲む>\n\n僕はいっつもDiraniaを僕の厄介ごとに巻き込んじゃうんだけど、彼女はそのたびに助けてくれるんだ。\n\nだいぶ気分が良くなってきたよ。でもすっかりよくなるまでは、僕はもう少しここに座っていようと思う。さてと、そんなわけで君、できたら僕のために、あの凶悪なクモたちをやっつけて道を開けてくれると嬉しいんだけどなあ…", 0xf8fbaf1b, 0x19c81d7f, 0x9296895f, 0x4cd0a6af, 0xc1dde192, "....." },
  [3523] = { "DownsのScourge", "Belnistraszに手を貸すことに同意するなら、もう一度彼と話し、彼から渡されたOathstoneを返して下さい。", "素晴らしい！私の名はBelnistrasz、助けてくれて感謝する。もう死んだものと諦めていた……いや、もっと悪ければ、このScourgeに蝕まれた害獣どもの餌になるところだった。そうだ、確かにScourgeと言ったんだ。奴らはここのQuilboarと何か取引を結んだらしく、この悪夢はその結果なんだ。\n\n聞いてくれ……ただ逃げ出すのではなく、我々皆のために何かを変えたいんだ。そのために手を貸してくれないか？たぶん危険だが、君はそういうことをあまり気にしない質のようだからな。", "私は政治には関心がない。君がHordeに属していようとAllianceに属していようと構わない。私が関心を持っているのは、すべての種族に対する直接的で深刻な脅威を叩き潰すことだ……そして、ここにはとんでもなく大きな脅威がいる。\n\nすべての民のための真の英雄となる覚悟があるなら、誓いの証として私が渡したoathstoneを渡してくれ。私は……この辺りの出ではない。我が同族にとって、oathstoneは約束の絆として大切なものなのだ。", "素晴らしい。君は英雄の器だと思っていたよ! 正直に言うが、{name}、我々には大仕事が待っている。目の前の任務に集中していれば、きっと勝利を収められるはずだ。\n\nでは、これまでに何が起きているのか説明しよう……", 0xae7d8ef9, 0x85690b77, 0x9c1e1ebf, 0x00a114d7, 0xd298f8e8, "....." },
  [3524] = { "打ち上げられたもの", "Auberdineのすぐ南に打ち上げられた海の生き物からSea Creature Bonesを回収し、AuberdineのGwennyth Bly'Leggondeのところへ持ち帰る。", "堂々たる海の生き物たちがDarkshoreの海岸に自ら乗り上げ、死ぬまでそこに打ち上げられたままになることが知られています。最近、こうした生き物が打ち上げられる数がますます増えているのです。私はTemple of the Moonから調査のためにここへ遣わされたのですが、水辺にmurlocがいるせいで研究がはかどりません。\n\nAuberdineのすぐ南に巨大な生き物が打ち上げられているのですが、忌まわしいGreymist murlocに取り囲まれています。そこへ行って、私たちの研究のためにその生き物の骨を取ってきていただけませんか？", "この生き物たちがこれほど驚くべき数でDarkshoreの海岸に上陸し始めたのは、ごく最近のことだ。何かの凶兆ではないかと思わずにはいられない。南にいるあの生き物のbonesのサンプルを持ち帰れば、Darnassusにいる我々がこの状況を見極める助けになるだろう!", "これを集めるのに、murlocがあまり手を焼かせなかったならいいのですが! 次のDarnassus行きのhippogryphに、必ずこれを載せましょう。Temple of the Moonから、助力への謝礼として配る資金を少し預かっています。どうか、私たちの感謝とともに受け取ってください。\n\nここでのあなたの成功に励まされ、よろしければ、Temple of the Moonにさらに力を貸す機会をあなたに差し上げたいのですが……", 0x8079e34a, 0xdf94400b, 0xdd2f6ea9, 0xb30873ce, 0x899e5ad6, "....." },
  [3525] = { "神像の火を消す", "Belnistraszを、Razorfen DownsにあるQuilboarの偶像まで護衛する。\n\nBelnistraszが偶像を停止させる儀式を行っている間、彼を守って下さい。", "入口の近くに、Quilboarにとっておぞましいかまどの役目を果たす偶像がある。あの獣ども……Barrensからさらってきた者たちを文字どおり食らっているんだ。私なら偶像の働きを止め、奴らが二度と使えないよう縛ることができるが、それには君の助けが要る。私の計画はこうだ。偶像まで私を護衛してくれ。着いたら儀式を始める。そうなれば君と話すのもやっとで、自分の身を守るどころではなくなる。偶像を止める間、私を守ってくれ。私がやられたら、我々はおしまいだ。\n\n一緒に来てくれるか？！", nil, "Belnistraszが突然去った後には、燃える火鉢が残されている。炎を見つめると、大いなる翼を持つred dragonの姿が心に広がる。よりしわがれたBelnistraszの声が、直接あなたに語りかけてくる。\n\n「まことに、定命の者たちよ、そなたらは我が望んだとおりの英雄であった。そなたらのおかげで、あの獣どもが行っていた殺戮は過去のものとなった。そなたらのような定命の者への我が信頼は、再び新たにされた。英雄にふさわしい報酬として、これを受け取るがよい。」", 0x17d394ac, 0xb46725ca, 0x55b0d5af, nil, 0x0f1269c0, "...m." },
  [3526] = { "Goblin Engineering", "Goblin Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをGadgetzanのNixx Sprocketspringに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。ゴブリン工学が優秀なエンジニア全員の選択であることは明らかだな。高性能爆薬や最高の道具の賢い使い方を通じて、世界征服を学べ!\n\n{name}、このマニュアルを読め。ゴブリン工学を学びたいのなら、これを持ってGadgetzanのNixx Sprocketspringのとこへ行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、あいつの課題を終える前には必ず確認しろよ。", "新入りの匂いは、上等な発破粉と同じように嗅ぎ分けられるんだ――一マイル先からでもな。爆発の極意を学びに来たのかい?", "さて{name}、オレの指導を請いにくるとは賢明だな! どんなのろまだって工学基礎の専門家になれるぜ……ノームどもや、放射線を浴びたあいつらの故郷Gnomereganがその証拠さ。もっとも、Goblin Engineeringの分野を修得するには強い心としっかり動く手（しっかり、が肝心だ）が必要だがね。\n\nよく聞けよ{name}、そうすりゃ何かしら学べるだろうよ。", 0x4ccb3e9c, 0x84f932f9, 0x31040b00, 0x21f4153d, 0xad63c1bf, "....." },
  [3527] = { "Mosh'aruの預言", "TanarisのYeh'kinyaにFirst Mosh'aru TabletとSecond Mosh'aru Tabletを渡して下さい。", "Mosh'aruの古の予言は、神Hakkarの本質を封じ込める方法について語っている。それは2枚の石板に書かれ、Gadgetzanの西にあるトロールの都Zul'Farrakへ持ち去られた。\n\nMosh'aru tabletsを持ってきてくれ!\n\n一枚目の石板は、はるか昔に死んだトロール、Theka the Martyrが持っている。彼を迫害した者たちは呪われてスカラベに変えられ、今は彼の祠の周りを這い回っているという。\n\n二枚目の石板は、Gahz'rillaの聖なる池の近くにいるhydromancer Velrathaが持っている。\n\n石板を手に入れたら、私のところへ持ってきてくれ。", "Prophecy of Mosh'aruのtabletsは持っているか、{name}?\n\ntabletsを手に入れたら、それを研究し、Hakkarのエッセンスを封じ込める方法を学ぶのだ!", "ああ、これはいい。この古代のtabletsを一つに融合させ、そこに隠された秘密を研究できる。\n\nあなたへの借りは増えるばかりだ、{name}。そして、これからもっと増えることになる。", 0xd364c406, 0x5779c127, 0x04cf4634, 0x501c1184, 0xc5a84974, "....." },
  [3528] = { "Hakkar神", "TanarisのYeh'kinyaにFilled Egg of Hakkarを渡して下さい。", "今こそ、Hakkarのアバターの本質を捕らえる時だ。\n\nEgg of HakkarをAzerothのSunken Templeにある、Sanctum of the Fallen Godへ持って行け。卵の力を呼び起こし、死せる神を揺り動かすのだ。\n\n奴はお前に手下を差し向けてくるだろう。奴のbloodrinkersを倒してHakkari bloodを奪い、その血でHakkarの霊を繋ぎ止める永遠の炎を消せ。すべての炎が消えれば、Hakkarのアバターがこの世界に現れる。\n\n奴を倒し、その本質をegg of Hakkarに納めるのだ。", "avatar of Hakkarは倒したか、{name}? 奴のエッセンスは、私が渡したeggにもう力を与えたか?", "Hakkarのエッセンスは集められた! 今この時もEggは生命に脈打っている! Hakkarの神話は本当なのだろうか?\n\nそれが本当であってはならない。もし再び生を受ければ、Hakkarが何をするか恐ろしいからだ。私はこのeggを安全に保管し、邪悪な手に落ちないよう見届けよう。\n\n私と共の務めはこれで終わりだ、{name}。あなたは伝説に触れた。その行いはいつの日か、我々の世界の姿を変えるかもしれない。", 0x238c5bf2, 0x9b475888, 0xd9ea8d5c, 0x6654d44b, 0xef77c52c, "....." },
  [3541] = { "Jes'rimonへの配達", "Tablet of Jin'yaelをOrgrimmarのJes'rimonのところへ持って行って下さい。", "Orgrimmarに故買屋がいるの。The Dragに住んでいるわ。どこを探せばいいか知らないと捕まえにくい相手だけど、あそこで一番高い建物の一つを探せば、問題なく見つかるはずよ。\n\nでもお願いがあるの。彼がそこにいることや、彼の商売のことをKalimdor中に言いふらしたりしないでね――私たち二人ともまずいことになるから。\n\n彼ならTablet of Jin'yaelに十分すぎる値をつけてくれるわ。理由は分からないけど、その在りかを聞いたときの彼の興奮ぶりといったら、見せてあげたかったわね。", "おう、何の用だ、兄弟? 今日は片付けなきゃならねえことが山ほどあってな、お前はその予定に入ってねえ。しつこくすりゃ、そいつは変わることになるぜ。", "ああ、JedigaがAzsharaからはるばる荷を送ってきたか。よし。こいつを待ってたんだ。\n\nJediga、ありゃいい女だ……危なくもある。これ以上のもんがあるか?\n\nこれを見ろ……石板は完璧な状態だ。お前はいい使者だな、{name}。", 0x4e34a97a, 0x41e30fa4, 0x20977793, 0xf2fc3677, 0x7c6a3519, "....." },
  [3542] = { "Andron Gantへの配達", "Tablet of MarkriをUndercityのAndron Gantのところへ持って行って下さい。", "次の取引相手はAndron Gantよ。たいていUndercityに引きこもっているわ……Apothecariumのすぐそばにね。\n\n彼は、何のために石板が欲しいのかについては少し口が軽かったわ。どうやらUndercityのメイジの何人かが、Highborneが使っていた秘術の呪文を研究しようとしているらしいの。この石板が役に立つと考えているのね。Markriは生き物、特にelementalsの召喚に長けていたから。\n\nTablet of Markriを持っていって、それから報酬の取り分を受け取りに私のところへ戻ってきて。", "おや……<ヒック>……こりゃ驚いた。冒険者者者……<ヒック>!\n\nあんたのために何ができるかね……<ヒック>?", "ほら、金を持ってけ……新しい……<ヒック>……鎧でも何でも買いな……\n\nこいつは、しかるべき……<ヒック>連中のところへ持ってけば、ピカピカの金貨2枚ほどにはなる。", 0xeafb35da, 0x59e7d7dc, 0x51a61fdf, 0x12ec3263, 0xf29d0364, "....." },
  [3561] = { "Archmage Xylemへの配達", "Tablet of Sael'haiをAzsharaのArchmage Xylemのところへ持って行って下さい。", "この最後の石板は、とても危険な人物に渡すものよ、{name}。よく聞いて。この人物は、これまで会いに行ってもらった誰よりも、私はずっと信用していないの。\n\nArchmage XylemはAzsharaを見下ろす丘の上に塔を構えているわ。人間だけど、私が会ったことのある……あるいは殺したことのある、どんな人間とも違う振る舞いをするの。力がにじみ出ていて、その石板で何をするつもりなのか、とても聞く気にはなれないわ。\n\n彼は私のところへ来たけど、会う準備ができたら護衛のSanathが塔まで案内してくれると言っていたわ。Sanathを探すなら北よ。", "何か手伝えることはあるか、{name}?", "ああ、Tablet of Sael'haiか……どれほど研究したいと願っていたことか。\n\nありがとう、{name}。Jedigaによくやったと伝えてくれ。彼女が求めた支払いに見合う価値は十分にある。", 0x1e83cbca, 0x0aa23362, 0x8a0ebd1b, 0xcb59cbf2, 0xcdfb217a, "....." },
  [3562] = { "MagathaからJedigaへの支払い", "Magatha's NoteをAzsharaのJedigaに届けて下さい。", "この手紙をJedigaへ届けてくれ。彼女が戻ってきたら、ここで報酬を渡すと伝えてほしい。それから、彼女の仕事には満足していると。\n\n急いで行け、{name}。お前の主人に、ここで待っていると伝えるのだ。", "で、Magathaは何て言ってた? あの老婆め……さぞ無礼な態度だったろうな。", "ああ、よかった。彼女は思っていたよりずっと話の分かる相手だったようだな……少なくとも君に対しては。代わりの者を寄越した私の無礼を理由に、君を罰するのではと半ば思っていた。よほどあの石板が欲しいんだろう。興味深い。\n\nそれはまた別の機会に考えるとしよう。", 0x3b14ab9f, 0x02e806f2, 0xf71b8e6c, 0x96d1bd37, 0x1707e51a, "....." },
  [3563] = { "Jes'rimonからJedigaへの支払い", "Jes'rimon's NoteをAzsharaのJedigaに届けて下さい。", "この手紙をJedigaに持ってけ。俺たちの取引は得になった、あいつの仕事には満足してる、と伝えてくれ。\n\nあいつにOrgrimmarへさっさと戻ってこいと言え。そうすりゃJes'rimonがちゃんと面倒を見てやるってな。\n\nそう伝えてくれ。そうすりゃ、いつかまたお前の力を借りることもあるかもしれねえ、{name}。", "もうJes'rimonとは話したか?\n\nトロールの中の猪みたいな奴だが、奴の情報はたいてい正確で、仕事の払いもいい。\n\n奴の態度に耐えられるなら、奴の商売でいい稼ぎができるだろう。", "手紙の様子からすると、彼はいたくご満悦だったようだな……少々ご満悦すぎるくらいに。\n\nいつか時間を取って、私も彼の言い寄りをどれほどありがたく思っているか、きちんと分からせてやるとしよう。まあ、少なくともAzsharaでもっと過ごすのを楽しみにする理由が、一つはできたわけだ。\n\nこれが君の取り分だ。", 0xa9046055, 0x807e2f79, 0xb7a80dcb, 0xf55ca601, 0xce0311b9, "....." },
  [3564] = { "AndronからJedigaへの支払い", "Andron's NoteをAzsharaのJedigaに届けて下さい。", "ほら……これを……<ヒック> Jedigaに持ってってくれ。幸運を祈るぜ！", "Andronにはもう会ったか? 奴はUndercityをめったに離れないから、見つけるのはそう難しくないと思う。", "完璧だ……ちょっと待て。\n\nハハ! 石板を届けたとき、あいつに何て言ったんだ、{name}? とんでもなく払いすぎてるぞ! 文句を言ってるわけじゃないがな。取引の条件が変わったとでも言ったのか? それとも、あいつがまた酔っ払ってたのか?\n\nどうでもいいさ……ほら、追加の取り分も持っていけ。", 0xd9ca2a68, 0xa50e8b74, 0x5384d93c, 0x8cbc2e7f, 0x9ea5ab0f, "....." },
  [3565] = { "XylemからJedigaへの支払い", "Xylem's NoteをAzsharaのJedigaに届けて下さい。", "何だ？ああ、そうだ、報酬だな。もちろんだ。\n\nこれを受け取って、さっさと立ち去るがいい。Jedigaはお前の帰りを、さぞかし辛抱強く待っていることだろう。", "で、Xylemは何て言ってた? 何かされなかったか? 呪文をかけられたとか? 騙されて奴の仕事をさせられたとか?", "問題なし? 何ひとつ? それは大したものだ……少しは渋るか、少なくとも取引を裏切るくらいはすると思っていた。ふむ、結局は信用できる奴なのかもしれないな。\n\nまあ、あまりくよくよ考えることもない。これが君の取り分だ。手伝ってくれてありがとう。", 0x09c7ab2f, 0xbc90260c, 0x8ce9adbd, 0x73c5e1a6, 0x8079cdfc, "....." },
  [3566] = { "蘇れ、Obsidion！", "Lathoric the BlackとObsidionを倒し、Head of Lathoric the BlackとHeart of Obsidionを持ってIronforgeのThoriusのところへ戻って下さい。", "あれは……あれは……すべて罠だった。\n\n許して……くれ。\n\nあの野郎を殺せ……我々のために殺してくれ……Thoriusのために。", "信じられん! 証拠を見せろ!", "<Thoriusの顔が青ざめる。>\n\nこれは……こんなことがあるはずがない。我が兄弟が? あいつがすべて仕組んだというのか?\n\n<Thoriusの顔が怒りに歪む。>\n\nあいつは私を裏切った、Ironforgeを裏切ったのだ! Old Godsの影響は、いまだにこの地で強いようだ。かつて高潔で誇り高い男だった我が兄弟が、これほどたやすくRagnarosの意志に屈したのなら、安全な者など誰もいない。", 0x7fb05197, 0xfb84ebff, 0x88e5dd78, 0x4f3925a0, 0xe365ffe6, "....." },
  [3568] = { "染み出した腐敗", "Chemist Cuelyのところへ戻る前に、AzsharaのRuins of Eldarathの海岸に沿って潮溜まりでEmpty Vials 4本を満たして下さい。", "私の後ろにいるトーレンが見えるか――今にも具合が悪くなりそうな顔をしている女だ。彼女は最近Azsharaにいた。Ruins of Eldarathを抜けていく途中で、nagaに傷を負わされたと言っている。\n\n何体か撃退した後、浜辺で一休みして、潮だまりの水を飲んだそうだ。それで今は吐き気がしている……ほかにもいろいろとな。\n\n彼女が何を飲んだのか突き止めたい。この箱を持っていけ。中に私がラベルを貼ったempty vialsが入っている。それぞれ別の潮だまりで満たして戻ってきてくれ。", "この先どうなるかは分かっているだろう、{name}? 彼女が助かる見込みはない……見てみろ。今の彼女にとって一番いいのは、疫病の治療法を見つける手助けをすることだ。彼女が飲んだこの水に、その方法を突き止める手がかりがあるかもしれない。どうせ死ぬのだ――ならば死ぬ前に、同胞のために何か気高いことをして死んだほうがいい。そう思わないか?", "素晴らしい。彼女が死ぬ前に戻ってきたな。よし、よし。\n\nでは、さっそく取りかかるとしようか?\n\n彼女の症状はしばらく前から調べているが、なかなかひどいものだ。まだ立っていられるのが不思議なくらいだよ。そこら中に3、4回は吐いている……実に心地よい匂いだ。\n\n我々の……友で試すものを調合するから、少し待ってくれ。", 0x38d70828, 0x3680eba9, 0x6b26740e, 0xe6d21164, 0x046aa600, "....." },
  [3569] = { "染み出した腐敗", "Cuely's ElixirをUndercityのThersa Windsongに与えて下さい。", "これをThersaにあげてくれ。これで治る……かもしれない。飲み終わるまでは本当に分からんのだ。", "私がUndercityに来たのは、ここの錬金術師たちが自分たちの病の治療法を見つけるために長く熱心に研究していると聞いたからです。私のことも助けてくれるかもしれないと勧められたのです。\n\nここはとても歓迎されているとは思えない場所ですが、他に選択肢はありませんでした――私を襲った病は内側から私を引き裂いていて、すぐに彼らの助けが必要だったのです。", "Chemist Cuelyはとても親切にしてくれた……不気味なほどにな。だが、これが私を助けると彼が言うのなら、他に選ぶ道はない。他の解決策を探している時間はないのだ。プリーストやシャーマンにはもう相談したが、誰も私を助けることはできなかった。\n\nEarthmotherが私の魂を見守ってくださることを願おう。", 0x38d70828, 0x8ecbdf01, 0xdc5e548a, 0x37c1ae49, 0x59105d6c, "....." },
  [3570] = { "染み出す堕落", nil, nil, nil, "この霊薬がこれほど早く効くとは、夢にも思わなかった。ありがとう、{name}。残りのサンプルにもすぐ取りかかろう。遠からず、Lady SylvanasとForsakenの役に立てられるはずだ。", 0x38d70828, nil, nil, nil, 0x38bb3b3e, ".mmm." },
  [3601] = { "まさしくKim'jael！", "Thalassian Base CampでKim'jaelのCompass、Scope、Stuffed Chicken、Wizzlegooberを探し、Azsharaにいる彼のところへ返して下さい。", "Kim'jaelだとさ！！Kim'jaelってのがBlood elvesにとってどういう意味か知ってるか、{name}？ちびネズミ……とかそんな意味さ。あのいじめっ子どもめ！\n\nあいつらは、何か失われたお宝を探してこのあたりを偵察する手伝いに俺を雇ったんだ。もちろん「お宝」って言葉と払う額を聞いた瞬間に飛びついたさ。だが案の定、あいつらは俺を裏切って殺そうとしやがった……この俺をだぞ！\n\nBlood elfは信用できないってことだな。\n\n問題は、あいつらがまだ俺の装備を持ってて、取り返せないってことだ。手を貸してくれないか？", "あの臭えBlood elvesどもめ。いいか、俺がお前ぐらい強かったら、自分であそこへ降りていって奴らに思い知らせてやるところだ! だが、お前に金を払って片付けてもらうことで我慢するしかねえ。", "ハハ! あいつらをうまくやっつけてくれたんだね?!\n\nこいつは最高だ! これで、あのBlood elvesどもも仲間を裏切るとどうなるか思い知るだろう……特にゴブリンの商人みたいに忠実な相手をね! ふん、Blood elvesめ……!\n\nさて、せめてもの礼に、あんたの時間の分は払わせてもらうよ……約束したとおりにね。\n\nほらよ……これは役に立つはずさ。", 0xa956ad63, 0xfa7d5231, 0xab350b2c, 0xeca2c37d, 0xc1cbc6a5, "....." },
  [3602] = { "Azsharite", "Azshara南部でCrystallized Azshariteを二十個回収する。巧みに隠された鉱床の場所を「嗅ぎ」出すのに、Felhoundの助けを借りてもよい。\n\n任務を終えたらLoramusのところへ戻って下さい。", "Azshara南部の古のcliff giantsは、この地の岩や建物を糧として食らう。その排泄物は、非常に加工しやすく極めて強靭な結晶で、Azshariteとして知られている。\n\nその結晶の塊は南の弧状の地に散らばっているが、giantsがきわめて凶暴なため、回収されることはめったにない。\n\n南へ赴き、武器の本体を作るのに十分なAzshariteを回収してくるのだ。我がfelhoundsが結晶の回収を手伝うであろう。", "悪は眠らぬ、愚か者め。休むのは死んでからでよい。さあ、そのcrystalsを持ってこい。", "Azsharaでのそなたの務めは終わった、定命の者よ。我は今から、そなたの冒険の次なる段階に必要な部品を鍛えねばならぬ。", 0xe0c1e16e, 0xc8bece98, 0xa5e86e50, 0x9f1d4c72, 0xc180ec49, "....." },
  [3621] = { "Felbaneの形成", "Shipment to GalvanをStranglethorn ValeのGalvan the Ancientのところへ持って行って下さい。", "武器を鍛える準備は整った。焼き入れしたazshariteを、fel energyを扱う力を持つ者のもとへ持っていかねばならん。\n\nStranglethorn Valeにそのような鍛冶屋がいる。Mithril Orderの長、Galvan the Ancientが、お前の望みどおりに武器を作ってくれるだろう。彼の野営地はZul'GurubとMosh'Ogg ogreの塚の間にある。\n\nお前の決意と信仰が、この試練を乗り越えさせてくれることを願う。たとえ失敗しようとも、お前の神はお前に微笑んでいると知るがいい、定命の者よ。", "Loramus、だと? その名を聞くのは何年ぶりだろう。", "なんとまあ、この材料を手に入れるのにどんな目に遭ったのか、想像するしかないな。Azsharaへ足を踏み入れて生きて帰る者はほとんどいない。ましてや、半神や巨人と対峙した者ならなおさらだ!", 0xccbcf585, 0x99abba77, 0x50c2a1b5, 0x28677752, 0x61496e75, "....." },
  [3625] = { "魔力を帯びたAzshariteの邪悪な武具", "Galvanが武器を鍛え終えるのを待って下さい。", "{name}、それぞれの武器を作るにはいくらか時間がかかる。\n\n加えて、Felcurseの力は三分に一度しか使えん。Razelikh the Defilerとその手下どもを弱める効果が続く時間は、まちまちかもしれん。だからこそ、Felcurseは時が来たときにだけ解き放たねばならんのだ！\n\nでは、お前の武器を作るので少し待て、{name}。", "鍛造の過程を中断すれば、不完全な武器になりかねない。辛抱強く待て、{name}。", "<Galvanは額の汗を拭う。>\n\nこれほど優れた悪魔退治の者は、かつていなかったぞ、{name}。", 0x730cdf69, 0x60b82d6d, 0xa22882fb, 0x6169881c, 0x241a8eea, "....." },
  [3626] = { "Blasted Landsへ戻る", "Fallen Hero of the Hordeのところへ戻って下さい。", "贖罪の時は近いぞ、{name}。新たに手にした武器を携えてBlasted Landsへ戻り、Fallen Hero of the Hordeと話して最後の目的を受け取るのだ。", nil, "歴戦の強者の顔つきだな、{name}。Razelikhとその手下どもに立ち向かう覚悟はできているか?", 0xabec8174, 0xa1f27799, 0xac47adc8, nil, 0x2aac230d, "...m." },
  [3627] = { "砕けたアミュレットをひとつに", "Grol the Destroyer、Lady Sevine、Archmage Allistarjを倒す。彼らの死体からAmulet of Grol、Amulet of Sevine、Amulet of Allistarjを手に入れて下さい。\n\nEnchanted Azsharite Fel Weaponryを「使って」三人組を弱らせるのを忘れないこと。そうしなければ彼らは倒せない。だが、賢く使うこと……", "Defilerのもとへたどり着くには、まず力の三者を倒し、護符の欠片を取り戻さねばならん。三つの欠片をすべて取り戻したら、我のもとへ戻れ。さらなる指示を与えよう。\n\n行け、{name}！Blasted Landsへ！Sevine、Allistarj、Grolを倒すのだ！", "3つは1つとなり、1つは道を照らす。", "Razelikh the Defilerのアミュレットは再び完全な姿に戻ったが、奴は自らの指揮系統が乱れたことを感じ取っている。お前が自分を倒しに来ることを、奴は知っているのだ……", 0x44f1cf37, 0x2d4201e5, 0xeaa447f3, 0xede28e58, 0x281d72b0, "....." },
  [3628] = { "お前はRakh'likh、悪魔だ", "Razelikh the Defilerを滅ぼし、Severed Horn of the DefilerをFallen Hero of the Hordeのところへ持ち帰って下さい。Ward of the Defilerも持ち帰る必要があります。Fallen Heroがそれを破壊し、決して悪人の手に渡らないようにするためです。", "Razelikhの隠れ家は、Blasted Landsで最も高い山の頂にある。隠れ家へ行く唯一の方法は、山の近くにあるテレポートのルーンを使うことだ。護符を持っている限り、隠れ家まで自由に転移できる。隠れ家に着いたら、あの獣を呼び出さねばならん。護符が鍵なのだ、{name}。それをAltar of the Defilerに使え。\n\nDefilerを倒したなら、奴の角を持ち帰れ。それを見るすべての者にとって希望の象徴となるだろう――この戦火に荒れた世界にも英雄は確かに存在するという証にな。", "もはや恐れるものは何もない。", "今日という日は、永遠に記憶されるであろう。Blasted Landsの悪魔の支配者が、ついに倒れたのだ!", 0xb2d1d4a9, 0x9f71e0ee, 0xd0cab34d, 0xad069565, 0x28cc70b1, "....." },
  [3629] = { "Goblin Engineering", "Goblin Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをGadgetzanのNixx Sprocketspringに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。私は公平なトレーナーだから、わざわざゴブリン工学について述べてやったまでだ。あいつらは爆発物を作るのが好きなんだ。しかも、何を爆発させるかってことも滅多に気に掛けやしない……自分自身を爆発させることすらな。\n\n{name}、このマニュアルを読め。自分自身の爆発方法が知りたいのなら、これを持ってGadgetzanのNixx Sprocketspringのとこへ行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、あいつの仕事を終える前には必ず確認しろよ。", "新入りの匂いは、上等な発破粉と同じように嗅ぎ分けられるんだ――一マイル先からでもな。爆発の極意を学びに来たのかい?", "さて{name}、オレの指導を請いにくるとは賢明だな! どんなのろまだって工学基礎の専門家になれるぜ……ノームどもや、放射線を浴びたあいつらの故郷Gnomereganがその証拠さ。もっとも、Goblin Engineeringの分野を修得するには強い心としっかり動く手（しっかり、が肝心だ）が必要だがね。\n\nよく聞けよ{name}、そうすりゃ何かしら学べるだろうよ。", 0x4ccb3e9c, 0x84f932f9, 0x52e16ce5, 0x21f4153d, 0xad63c1bf, "....." },
  [3630] = { "Gnome Engineering", "Gnome Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをIronforgeのTinkmaster Oversparkに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。ノーム工学は遙かに優秀さを示しているのだ! 素晴らしい道具や装置の構築によって、人生をより良くできるんだ!\n\n{name}、このマニュアルを読め。ノーム工学をもっと詳しく学びたいのなら、このマニュアルをIronforgeのTinkmaster Oversparkのところへ持って行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、この仕事を終える前には必ず確認しろよ!", "はいはい、今日はどんなご用件でしょう? どう見ても暇はありますよ。愛する我らの街が放射能に汚染された死の雲に包まれている間、ここに立っているだけなんですから。", "ああ、若きエンジニアが真の工学分野の追求に興味を持ってくれた! さて三文芝居ですまんな、友よ。我々の置かれている状況は急を要するままだが、真の工学の明快な呼びかけに新たなエンジニアが応答してくれるのを見るのは、いつも素敵な日であることに変わりはないよ!", 0x963c40b5, 0xab72bd39, 0xf53fb9a4, 0xc8d72920, 0x23d1ca8c, "....." },
  [3631] = { "Summon Felsteed", "BarrensのStrahad Farsanと話して下さい。", "ふん。お前は準備ができていないと私は思うが、それを決めるのは私ではない。Strahadの考えは違う。そして決めるのは彼だ……今回はな。\n\n彼はお前と話したがっている、それも急いでだ。彼は今もBarrensのRatchetの上にいる。弟子たちと一緒に、あの小さな塔にな。\n\nぐずぐずするなよ。", nil, "ほう、また私の前に顔を出す気になったか。ご親切なことだ。\n\n弟子たちは、お前が本当に姿を見せるのかと訝っていた。私は疑う余地はないと言ってやった。力が絡むとなれば、お前は炎に引き寄せられる蛾のようにやって来るのだからな。", 0x5220fbc8, 0xf356d493, 0xc98053e2, nil, 0x23773eba, "...m." },
  [3632] = { "Gnome Engineering", "Gnome Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをIronforgeのTinkmaster Oversparkに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。ノーム工学は遙かに優秀さを示しているのだ! 素晴らしい道具や装置の構築によって、人生をより良くできるんだ!\n\n{name}、このマニュアルを読め。ノーム工学をもっと詳しく学びたいのなら、このマニュアルをIronforgeのTinkmaster Oversparkのところへ持って行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、この仕事を終える前には必ず確認しろよ!", "はいはい、今日はどんなご用件でしょう? どう見ても暇はありますよ。愛する我らの街が放射能に汚染された死の雲に包まれている間、ここに立っているだけなんですから。", "ああ、若きエンジニアが真の工学分野の追求に興味を持ってくれた! さて三文芝居ですまんな、友よ。我々の置かれている状況は急を要するままだが、真の工学の明快な呼びかけに新たなエンジニアが応答してくれるのを見るのは、いつも素敵な日であることに変わりはないよ!", 0x963c40b5, 0xab72bd39, 0x73a63c06, 0xc8d72920, 0x23d1ca8c, "....." },
  [3633] = { "Goblin Engineering", "Goblin Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをGadgetzanにいるNixx Sprocketspringに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。ゴブリン工学が優秀なエンジニア全員の選択であることは明らかだな。高性能爆薬や最高の道具の賢い使い方を通じて、世界征服を学べ!\n\n{name}、このマニュアルを読め。ゴブリン工学を学びたいのなら、これを持ってGadgetzanのNixx Sprocketspringのとこへ行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、あいつの課題を終える前には必ず確認しろよ。", "新入りの匂いは、上等な発破粉と同じように嗅ぎ分けられるんだ――一マイル先からでもな。爆発の極意を学びに来たのかい?", "さて{name}、オレの指導を請いにくるとは賢明だな! どんなのろまだって工学基礎の専門家になれるぜ……ノームどもや、放射線を浴びたあいつらの故郷Gnomereganがその証拠さ。もっとも、Goblin Engineeringの分野を修得するには強い心としっかり動く手（しっかり、が肝心だ）が必要だがね。\n\nよく聞けよ{name}、そうすりゃ何かしら学べるだろうよ。", 0x4ccb3e9c, 0x84f932f9, 0x31040b00, 0x21f4153d, 0xad63c1bf, "....." },
  [3634] = { "Gnome Engineering", "Gnome Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをIronforgeのTinkmaster Oversparkに渡して下さい。", "Engineeringは、熟練者の段階で2つの分野に分かれる。ノーム工学とゴブリン工学だ。俺は無駄だと思うが、ノームの専門分野のことも知っておくべきだろう。奴らは世界を変えると謳う品や道具を作るが、まともに動くことはめったにない。\n\n{name}、この教本を読め。金属製の文鎮の作り方を学びたいなら、その教本をIronforgeのTinkmaster Oversparkのところへ持って行け。忘れるな――加入は永久で、もう一方の分野には入れなくなる。奴の仕事を終える前に、本当にそれでいいのか確かめておけよ!", "はいはい、今日はどんなご用件でしょう? どう見ても暇はありますよ。愛する我らの街が放射能に汚染された死の雲に包まれている間、ここに立っているだけなんですから。", "ああ、若きエンジニアが真の工学分野の追求に興味を持ってくれた! さて三文芝居ですまんな、友よ。我々の置かれている状況は急を要するままだが、真の工学の明快な呼びかけに新たなエンジニアが応答してくれるのを見るのは、いつも素敵な日であることに変わりはないよ!", 0x963c40b5, 0xab72bd39, 0xc301270e, 0xc8d72920, 0x23d1ca8c, "....." },
  [3635] = { "Gnome Engineering", "Gnome Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをBooty BayのOglethorpe Obnoticusに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。もったいないことだな、ノーム工学の特化に関心があるなんて。あいつらは世界を変えようとして物や道具を作ってるんだ。めったに作動しないがね。\n\n{name}、このマニュアルを読め。金物のペーパーウェイトの作り方が知りたいのなら、このマニュアルをBooty BayのOglethorpe Obnoticusのところへ持って行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、この仕事を終える前には必ず確認しろよ!", "やあ、どうも! 追尾ロボットがあなたの住まいの壁を突き破ったかもしれないという件でいらしたなら、あらかじめ私の弁護士をご紹介しておきます。そうでなければ、今日はどんなご用でしょう?", "ノーム工学を学びに来たんだろ? よし、お前さんはぴったりのノームのとこへ来たんだ。Gnomereganの主流派閥は、知性ある脅威とみなした者を排斥するために政治を利用するだろうが、知識とは支配できない物であるということは奴らも知ってるんだ。\n\n奴らも私も、私がGnomereganを離れた時に分かったのだよ。今日生きているノームエンジニアで最も偉大な者を失ったとね。もしお前さんが優秀な弟子なら、知っていることを教えてあげよう。", 0x963c40b5, 0x6595257c, 0x478a11f0, 0x110595dc, 0xebc8c2cf, "....." },
  [3636] = { "光をもたらす", "Archbishop Bendictusは、Razorfen DownsのAmnennar the Coldbringerを倒してほしいと言っています。", "ScourgeはAllianceにとって絶えることのない脅威です。それはあなたもよくご存じでしょう。最近、我々はとても奇妙なものを発見しました、{name}。\n\nBarrensに、Razorfen Downsと呼ばれるおぞましいイバラの茂みがあります。かつてはただのquilboarの住処でしたが、今ではScourgeと盟約が結ばれ、はるかに恐ろしい生き物が生み出されていることが明らかになりました……今、彼らを支配しているのはlich、Amnennar the Coldbringerです。\n\n光と共にあってください、{name}。この邪悪な結びつきに終止符を打つのです。", "Amnennarを根絶せねばならぬ。行け、速やかに。", "ありがとうございます、{name}。これでScourgeも、再び軍勢を増強しようとする前に、二の足を踏むことでしょう。\n\nあなたに光の祝福がありますように。", 0x15219363, 0x58355ea6, 0xf1d2ffc7, 0x30367c57, 0xaa15e714, "....." },
  [3637] = { "Gnome Engineering", "Gnome Engineeringについて詳しく学びたいのであれば、Manual of Engineering DisciplinesをBooty BayのOglethorpe Obnoticusに渡して下さい。", "専門レベルの工学は、ノームとゴブリン、二つの分野に分かれる。もったいないことだな、ノーム工学の特化に関心があるなんて。あいつらは世界を変えようとして物や道具を作ってるんだ。めったに作動しないがね。\n\n{name}、このマニュアルを読め。金物のペーパーウェイトの作り方が知りたいのなら、このマニュアルをBooty BayのOglethorpe Obnoticusのところへ持って行け。忘れるなよ……会員資格は永久のもので、もう一方の分野に入門することはできなくなる。だから、この仕事を終える前には必ず確認しろよ!", "やあ、どうも! 追尾ロボットがあなたの住まいの壁を突き破ったかもしれないという件でいらしたなら、あらかじめ私の弁護士をご紹介しておきます。そうでなければ、今日はどんなご用でしょう?", "ノーム工学を学びに来たんだろ? よし、お前さんはぴったりのノームのとこへ来たんだ。Gnomereganの主流派閥は、知性ある脅威とみなした者を排斥するために政治を利用するだろうが、知識とは支配できない物であるということは奴らも知ってるんだ。\n\n奴らも私も、私がGnomereganを離れた時に分かったのだよ。今日生きているノームエンジニアで最も偉大な者を失ったとね。もしお前さんが優秀な弟子なら、知っていることを教えてあげよう。", 0x963c40b5, 0x6595257c, 0x478a11f0, 0x110595dc, 0xebc8c2cf, "....." },
  [3638] = { "The Pledge of Secrecy", "Goblin Engineerとなることに同意する場合は、Pledge of Secrecyを右クリックし、GadgetzanのNixx Sprocketspringと再度話して下さい。", "ゴブリン工学ってのは、高い利益と、もっと高い爆発力を生む実用性がすべてだ! 俺たちの設計図があれば、強力な爆弾や強大な武器が作れる。お前が読んだ教本にも書いてあったろう。\n\n教本には、設計図に関する俺たちの昔からの秘密の誓いのことも書いてあった。ゴブリン技師になったら、それまでだ。ノーム工学には一切手を出せなくなる。\n\nそれでもゴブリン技師になりたいなら、生涯秘密を守ると誓うこの書類に署名して、もう一度俺に話しかけてくれ。よく考えるんだぞ、{name}。", "書類に署名して私に渡す準備ができているなら、それで決まりだ。これは片道の旅だと言われているはずだ。準備ができているなら、さあ乗り込め!", "ようこそ、Goblin Engineer {name}! 君はまもなく、Azerothのどこよりも強力な工学の設計図を利用できるようになる。\n\nこの知識の追究に身を捧げたからには、君のゴブリン流の工学の成果を検討する時だ。そこから、君のゴブリン工学の才能を最大限に伸ばす計画を立てる手伝いをしよう!", 0x377e89c9, 0x1c9a7579, 0xe3b7826f, 0x488e5de6, 0xac54b098, "....." },
  [3639] = { "成果を示せ", "Big Iron Bomb 20個・Solid Dynamite 20本・Explosive Sheep 5つをGadgetzanのNixx Sprocketspringに渡して下さい。", "君の指導役として、君の作品のサンプルが欲しい。君が腕の立つエンジニアであることは疑いようがない、{name}。だが私が望むのは、それらを分析して、今後の君の仕事でゴブリン流の技術をより活かす道を探ることだ。必要なのは次のとおり：Big Iron Bombを20個、Solid Dynamiteを20本、Explosive Sheepを5個――それから安全装置はかけたままにしておくように！\n\nこれらの品を提出すれば、君専用のGoblin Engineer Membership Cardを発行しよう。すべてのゴブリン工学トレーナーの指導を受けるには、それが必要だ！", "君が作った工学の品を私が審査のために受け取ったら、本物のGoblin Engineer Membership Cardを渡そう! カードが有効な限り、世界中どこにいるゴブリン・エンジニアのトレーナーにも無制限に会えるようになるぞ。", "これが君の最初のGoblin Engineer Membership Cardだ！\n\nこのカードは14日分の会費が前払いされていて、どのカードも有効になってから2週間で期限が切れる。期限が切れたら、どこかのゴブリンエンジニアのトレーナーに次の会費を払って、新しいカードをもらってくれ。カードがないと会員資格は一時的に失効して、新しい設計図を手に入れられなくなる。\n\nこれは、君がすでに覚えていることには決して影響しない。一度ゴブリンエンジニアになったら、ずっとゴブリンエンジニアさ。", 0x28ad35d0, 0x60c595fd, 0x22d1c014, 0x1dccf7ff, 0xaf83734e, "....." },
  [3640] = { "The Pledge of Secrecy", "Gnome Engineerとなることに同意する場合は、Pledge of Secrecyを右クリックし、IronforgeのTinkmaster Oversparkと再度話して下さい。", "ノーム工学とは、私たちの必要に応じて形作られた工学理論なんだ! 私たちの設計図があれば、身の回りの世界を制御する装置が作れる。君が読んだ教本にも書いてあったね。\n\n教本には、設計図に関する私たちの昔からの秘密の誓いのことも書いてあった。ノーム技師になったら、それまでだ。ゴブリン工学には一切手を出せなくなる。\n\nそれでもノーム技師になりたいなら、生涯秘密を守ると誓うこの書類に署名して、もう一度私に話しかけてくれ。よく考えるんだよ、{name}。", "書類に署名して私に渡す準備ができているなら、それで決まりだ。\n\n私がこれから教える秘密は非常に重大なものだから、Pledge of Secrecyへの署名は絶対に欠かせない。私も署名したし、兄弟姉妹であるノームのエンジニアたちも皆署名した。君はなかなか栄えある仲間に加わることになるぞ、Engineer {name}!", "ようこそ、{name}! 君はまもなく、Azeroth中で最も進んだengineeringの設計図を手にすることになる。\n\nこの知識の探求に身を捧げたからには、次は君のノーム方面のengineeringの仕事を見せてもらおう。そこから、君のノームのengineeringの才能を最大限に伸ばす計画を立てる手助けをしよう!", 0x377e89c9, 0x84e69e0f, 0x214b7ad1, 0x19cea1d0, 0xfdd2709b, "....." },
  [3641] = { "成果を示せ", "Mithril Tube 6本・Accurate Scope 一つ・Advanced Target Dummies 2つをIronforgeのTinkmaster Oversparkに渡して下さい。", "君の指導者として、君の仕事の見本がいくつか欲しい。君が腕利きの技術者であることに疑いはないよ、{name}。でも私としては、君の仕事を分析して、今後の君の取り組みでノーム流の技術を重視していけるような方法を見つけたいんだ。必要な見本はこれだ。mithril tubeを6本、accurate scopeを一つ、そして高性能な標的用ダミーを2体。\n\nこれらを私に提出してくれれば、君専用のGnome Engineer Membership Cardを発行しよう。すべてのノーム工学トレーナーの指導を受けるには、これが必要なんだ！", "製作したエンジニアリング品を審査のために受け取ったら、本物のGnome Engineer Membership Cardを渡そう! カードが有効である限り、世界中どこのノームのエンジニアトレーナーでも無制限に利用できるぞ。", "これが君の最初のGnome Engineer Membership Cardだ!\n\nこのカードは14日分の会費が前払いされている。カードはすべて、2週間分の活動で期限が切れる。切れたら、次の会費をノームのengineerのトレーナーの誰かに払って、新しいカードをもらうんだ。カードがなければ会員資格は一時的に失効し、新しい設計図を手に入れられなくなる。\n\nこれは君がすでに覚えたものには決して影響しない。一度ノームのengineerになれば、ずっとノームのengineerだ。", 0x28ad35d0, 0x8f3af78f, 0x0315cb1b, 0x6d0fae99, 0xd8998a19, "....." },
  [3642] = { "The Pledge of Secrecy", "Gnome Engineerとなることに同意する場合は、Pledge of Secrecyを右クリックし、Booty bayのOglethrope Obnoticusと再度話して下さい。", "ノーム工学は我々のニーズに役立つよう形作られた工学理論なのだ! ノーム工学体系によって、世の中を操る装置を作ることができる。君が読むこのマニュアルはそれについて触れている。\n\nこのマニュアルは、ノーム工学体系において何世代も昔から続く秘密の誓いにも触れている。一度ノームエンジニアとなったら、それで終わり。ゴブリン工学に触れることはまったく出来なくなる。\n\nそれでもまだノームエンジニアになりたいのなら、生涯秘密の宣誓文書にサインしてからまた話しかけてくれ。慎重に考えるんだぞ、{name}。", "書類に署名して私に渡す準備ができているなら、それで決まりだ。\n\n政治的にはGnomeregan――特にあの愚か者Tinkmaster Overspark――とは激しく意見が対立しているかもしれんが、Pledge of Secrecyは何よりも優先されるのだ! ただ一つの道に身を捧げ、生涯その道に忠実であることを誓わねばならん。", "ようこそ、{name}! 君はもうすぐ、Azerothのどこよりも発展した工学体系に触れることができるんだ。\n\nその知識の追求をするという立場をはっきり示したからには、ノーム指向工学の成果を試す時だ。君がノーム工学の才能を最大限に伸ばす計画を築き上げるのを、そこから手伝ってあげよう!", 0x377e89c9, 0x2d86b3ca, 0x214b7ad1, 0x6e5d0046, 0xfdd2709b, "....." },
  [3643] = { "成果を示せ", "Mithril Tube 6本・Accurate Scope 一つ・Advanced Target Dummies 2つをBooty BayのOglethorpe Obnoticusに渡して下さい。", "君の指導者として、君の仕事の見本がいくつか欲しい。君が腕利きの技術者であることに疑いはないよ、{name}。でも私としては、君の仕事を分析して、今後の君の取り組みでノーム流の技術を重視していけるような方法を見つけたいんだ。必要な見本はこれだ。mithril tubeを6本、accurate scopeを一つ、そして高性能な標的用ダミーを2体。\n\nこれらを私に提出してくれれば、君専用のGnome Engineer Membership Cardを発行しよう。すべてのノーム工学トレーナーの指導を受けるには、これが必要なんだ！", "製作したエンジニアリング品を審査のために受け取ったら、本物のGnome Engineer Membership Cardを渡そう! カードが有効である限り、世界中どこのノームのエンジニアトレーナーでも無制限に利用できるぞ。", "これが君の最初のGnome Engineer Membership Cardだ!\n\nこのカードは14日分の会費が前払いされている。カードはすべて、2週間分の活動で期限が切れる。切れたら、次の会費をノームのengineerのトレーナーの誰かに払って、新しいカードをもらうんだ。カードがなければ会員資格は一時的に失効し、新しい設計図を手に入れられなくなる。\n\nこれは君がすでに覚えたものには決して影響しない。一度ノームのengineerになれば、ずっとノームのengineerだ。", 0x28ad35d0, 0xa2c12436, 0x0315cb1b, 0x6d0fae99, 0xd8998a19, "....." },
  [3661] = { "Eluneに愛されし者？", "Rut'theran VillageのErelas Amberskyのために、HinterlandsでWildkin Feathersを$N1枚集めて下さい。", "Wildkinはとても予測のつかない生き物です、{name}。驚くほど穏やかにもなれるのですが、大切だと思うものが脅かされると、ひどく獰猛になります。\n\nこの獣たちはEluneによって創られたと噂されていて、私はそれが本当なのかを確かめることに興味があるのです。\n\n最近、Hinterlandsにwildkinの群れが棲んでいると聞きました――Vicious、Primitive、そしてSavage Owlbeastsです。あちらの野生の生き物の間で見つかります。wildkin feathersを集めてきてくれませんか？", "できるだけ避けるようにしてください、{name}。Wildkinはあなたの興味を、危害を加える意図だと誤解するかもしれません……", "これを持ってきてくれてありがとう、{name}。\n\nWildkinについて何か分かりましたか?\n\nこの羽根が、もっと多くのことを教えてくれるかもしれません。獰猛な怪物なのか、それとも単に道を誤ったペットなのか? いつか真実を知りたいものです……\n\n私は研究を続けます。しばらく時間が経ったら、また話しに来てください。", 0xc37a4269, 0x5c08c3bb, 0x07d63186, 0x6980b3e3, 0x9787a159, "....." },
  [3681] = { "Tome of Divinity", "StormwindのDuthorian Rallと話して下さい。", "旅の邪魔をして悪いが、{race}、最近Stormwindから、パラディンは訓練のためにそこへ出頭するようにとの知らせが届いたことを伝えておこうと思ってな。\n\n私の見立てが正しければ、君は特別な時を迎えつつあるようだ。そろそろTomesの勉強を始める頃だろう。\n\nStormwindのDuthorian Rallを訪ねなさい。彼はたいていCathedral of Lightでパラディンを訓練している。", nil, "Cathedral of Lightへようこそ、{class}。", 0x85861feb, 0xfa9ae08e, 0x355bcc91, nil, 0x252bde23, "...m." },
  [3701] = { "Thaurissanのくすぶる遺跡", "Burning SteppesのRuins of Thaurissanへ赴き、Thaurissan Relicsから情報を集めて下さい。情報を集めたら、Royal Historian Archesonusのところへ戻って下さい。", "Burning Steppesにある、くすぶるThaurissanの遺跡へ向かい、できる限り多くの情報を集めてきてくれ。\n\n遺跡には謎めいた遺物が散らばっているという。まずはそこから探し始めるといいだろう、{name}。Thaurissanの守護者たちには気をつけろ。遺跡を守り、そこにまだ埋もれているかもしれない秘密を守り続けている暗殺者どもだ。", "新しい情報を持ってきたか?", "なんと! この情報で、Thaurissanについてずいぶん多くのことが分かる。\n\nまだまだ学ぶべきことがたくさんあるぞ!", 0x1388ff2f, 0x7fad64f0, 0x44373936, 0x9da52d5c, 0xba8be352, "....." },
  [3702] = { "Thaurissanのくすぶる遺跡", "Royal Historian ArchesonusがThaurissanの歴史を語るのを聞いて下さい。", "Dark Ironのドワーフの簡単な歴史を聞きたいかね？", "Thaurissanの物語を最後まで話させてくれ。", "では、進めようか?", 0x1388ff2f, 0x6e7ab0a1, 0x0e208f1c, 0xe4703b62, 0x759e0656, "....." },
  [3721] = { "自分専用 OOX", nil, nil, nil, "OOX 自動誘導ロボットを三機も回収して下さいましたね! 期待以上のことをして下さいましたから、そのお礼に特別なものを差し上げましょう。あなたが起動させ、可愛がって下さったのとそっくり同じロボットのミニチュアバージョン、OOX です!\n\n通常、このような潜在的殺傷能力を有する装置は誰かに差し上げることはないのですが、あなたには本当にお世話になりましたから。ただし――戦闘メカニズムと自動追尾論理回路は使えなくしてあります。\n\nそれ以外は完全な OOX ですよ!", 0xe02f962a, nil, nil, nil, 0xb41bd7fe, ".mmm." },
  [3741] = { "Hilary's Necklace", "Hilary's Necklaceを見つけ、LakeshireのHilaryに返す。", "友達のHilaryがネックレスをなくしちゃって、見つからないの。ずっとここで一日中釣りをしてたし、この辺はもう探したの。考えられるのは、湖に落ちちゃったってことだけ。お父さんとお母さんは湖で泳いじゃだめって言うの……ママは水の中に意地悪なものがいるって言うけど、あなたは意地悪なものなんて怖くなさそう。\n\nお願い、あの子のために探してくれない？", "こんにちは。わたしのnecklaceがなくてさみしいの。パパが買ってくれたんだよ。パパが、湖にはモンスターがいるって言ってた。モンスターやっつけた?", "私のネックレスを見つけてくれてありがとう、{class}さん……とっても親切なんだね! 私のネコちゃんもありがとうって言ってるよ。ね、Effsee?", 0x42188c01, 0x56803c15, 0xf3c09303, 0xe8736a32, 0x7a3fe990, ".....", nil, nil, nil, nil, 0xed8e927e },
  [3761] = { "Un'Goro Soil", "Thunder BluffのElder RiseにいるGhedeに、Un'Goro Soilの標本を20個渡して下さい。", "Un'Goro Craterの土は強い魔力に満ちていると言われている。Cenarion Circleは研究のためにその土を大量に必要としている。そこで、Un'Goroの大自然に分け入り、我々が研究を続けるために必要なだけの土を確保して来てほしい。\n\n時々、肥えた土は山のように突き出ていることがある。獣たちの中にも、使えそうな土を持っているものがいるかもしれん。土は全て、外にいるGhedeに渡してくれ。土の山と、怒鳴って指図するトーレンだ。見れば分かる。良かれと思ってやっているから、本当に怒らせないようにな!", "楽にしろ、二等兵。Un'Goroのsoilを降ろしに来たのなら――それなら上出来だ! そうでないなら、消えろ。", "ああ、そうだとも、{name}二等兵、この土を山の上に降ろすのを手伝おうなんて少しも思わなくていいさ！Great Spiritsがそうしたいと望んでいたなら、奇跡で上まで運んでいただろうからな、そうだろう？！\n\nArch Druid Runetotemがまた君と話したいそうだ。だが彼の次の任務には、中級程度のHerbalismの知識があると役に立つだろう。もっとも、知らなくても、彼は君に何か役目を見つけてくれるはずだ。", 0x158a6d09, 0x2d72886c, 0x7f829e93, 0x861e8e17, 0x8b0d244a, "....." },
  [3762] = { "Arch Druid Runetotemの手伝い", "Thunder BluffのArch Druid Hamuul Runetotemと話してください。", "すみません、{class}。ちょっとお時間をいただけませんか。\n\nThunder BluffのCenarion Circleは、重大な研究計画への助けが必要で、あなたのような手練れの冒険者に非常に関心を持っています。私は詳しく知りませんが、他ならぬHamuul Runetotemがこの研究を指揮していることはお教えできます。\n\nどうか、もし興味がおありならばElder Riseにいる彼と直接話してください。", nil, "ごきげんよう、{class}。我々の研究の手助けに興味を持ってくれて嬉しく思う。やることが多すぎるんだ。この仕事が危険でないと言ったら、君の気分を害するかもしれないな。願わくば、嫌気がさして帰ったりしないで欲しいが……しかし、君の顔を見れば分かるよ。前にも同じような危険な仕事を捌いてきたってね。", 0xba8dc721, 0xaac27949, 0x6fcc5bd2, nil, 0x93151f63, "...m." },
  [3763] = { "Arch Druid Staghelmの手伝い", "DarnassusのArch Druid Fandral Staghelmと話して下さい。", "失礼します、{class}。もしよろしければ、少しだけお時間をいただきたいのです。\n\nDarnassusのCenarion Circleが、重要な研究計画に力を貸してくれる、あなたのような熟練の冒険者を探しています。詳しいことは存じませんが、ほかならぬArch Druid Fandral Staghelmがこの研究の先頭に立っていることはお伝えできます。\n\nどうか――もし興味がおありでしたら、Darnassus本土のCenarion Enclaveで、直接彼と話してください。", nil, "さて、{class}……私自らがこの研究を率いていると知らされたのだから、当然、できる限り急いで来たのだろうな。\n\nここに来たからには、最初に説明するときにしっかり聞いておくことだ。同じことを繰り返すつもりはないのでな。", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3764] = { "Un'Goro Soil", "Un'Goro Soilのサンプルを$N1個、DarnassusのCenarion EnclaveにいるJenalのところへ持って行って下さい。", "Un'Goro Craterの土壌には、強力な魔法の性質が宿っていると言われています。私は事実と虚偽を見分けたいのです。Un'Goroの荒野へ赴き、我々の研究を続けるのに十分な、質の良いsoilのサンプルを手に入れてきてください。\n\n採集の仕事など自分にはふさわしくないと思うかもしれませんが、そういう態度では、私にもCenarion Circleにも好かれませんよ。サンプルはJenalのところへ持っていってください。きっとこの木の裏の外で時間を無駄にしているはずです。土の山を探せばすぐ分かります。段取りは彼が担当します――私ではありません。", "ああ、土ですね。大ドルイドは冒険者ごとに20回分を望んでおられますから、必ず20回分をお届けしましょう。我々に陰謀を企てる者どもは、道端に倒れるがいい!", "貴重な荷物はここに降ろしてくれたまえ、高貴なる{class}よ。さぞ重荷だったろう……先見の明を持つ者として私が背負う重荷と、そう変わらぬものだ。これは大ドルイドご自身の指示による、君の働きへの謝礼だ。\n\nArch Druid Staghelmが再び君と話したがっているぞ、{name}。だが次の仕事では、Herbalismを中級程度まで身につけていれば助けになるだろう。もっとも、知らなくてもCircleの力にはなれるとも！", 0x158a6d09, 0x8ab96594, 0x8b6a582c, 0x33b60dd8, 0x132cb099, "....." },
  [3765] = { "汚染は海の向こうに", "AuberdineのGershala Nightwhisperのもとへ出向いて下さい。", "Stormwind――なんと活気に満ちた街でしょう。\n\n私は助けを求めて遠くから旅してきました。勇敢な冒険者たちがこの街の通りを歩き回っていると、よく耳にしますから。\n\n私の兄、GershalaがDarkshoreで助けを必要としています。彼は海辺の町Auberdineに住んでいます。\n\nその旅は長く、壮大なものです。だからこそ、あなたのような熟練の{class}に助けをお願いしているのです。", nil, "ああ、それで私の兄弟Argosが君を寄越したのだな? 旅で疲れているのは分かっている。だが、話すことがたくさんあるのだよ。", 0xba7186ed, 0xd3d2f1f5, 0x698b9ad9, nil, 0xb83a2954, "...m." },
  [3781] = { "Morrowgrainの研究", "Arch Druid's Seed VoucherをDarnassusのCenarion EnclaveにいるMathrengyl Bearwalkerのところへ持って行って下さい。", "我々がEvergreen Pouchと呼んでいるものを使って、Un'Goro Craterの土でTharlendrisの種を育ててきました。この種は、さまざまな強い薬草を無作為に咲かせます。その一つがmorrowgrainという、我々もほとんど知らない謎の薬草です。私はこの謎を解き明かすつもりです。\n\nこれを階下のMathrengylのところへ持っていってください。始められるよう、彼が種をくれるでしょう。種が尽きたら、彼から買い足す必要があります。", "友よ、あなたに平安と静けさがありますように。大ドルイドご本人の用件でいらしたのですね?", "ええ、この引換券で種20袋と交換できます。足りなくなったら、さらにお渡しできます。ただ残念ながら、Tharlendrisの種を大量に作るにはかなりの費用がかかります。そのためCenarion Circleは、協力してくださる方々に費用の一部を負担していただくようお願いしているのです。\n\nmorrowgrainを持ち帰った方々は、大ドルイドが授ける報酬が費用を十分に補って余りあるものだと気づくのです。", 0x5cd3af85, 0xe666d2f2, 0x786c2f34, 0x2c0b9166, 0xd45cbd8d, "....." },
  [3782] = { "Morrowgrainの研究", "Thunder BluffのBashana RunetotemにSeed Voucherを渡して下さい。", "我々は、Evergreen Pouchと呼んでいるもので、Un'Goro Craterの土にあるTharlendris seedを栽培してきた。その種は何かの薬草に成長する。そのうちのひとつがmorrowgrainといって、我々にもほとんど知識のない神秘的な草だ。Cenarion Circleのために、是非ともこの神秘を解き明かしたい。\n\nこの証書をあそこにいる私の娘Bashanaに渡して、種を受け取りなさい。それで我々の手助けができる。種が無くなったら、彼女から買うといい。", "友よ、あなたに平安を。大ドルイドご本人の用件でいらしたのですね?", "はい、この証書は種20個分ですね。もし種を使い切っても、あなたに売る分は余分に持っていますよ。\n\n申し訳ないのだけれど{name}、Tharlendris seedを多く生産するにはとても費用がかかるのです。そのため、私たちを手助けしてくれる方々に費用を負担してもらうよう、Cenarion Circleに頼まれているのです。\n\nmorrowgrainを持ってきて下さった方には、費用を補ってあまりある報酬をご用意しています。", 0x5cd3af85, 0xe58b0883, 0x547a911b, 0x410657db, 0x58f0c3f6, "....." },
  [3783] = { "イエティ、いるの?", "EverlookのUmi Rumplesnickerに、Thick Yeti Fur 10枚を集めてあげて下さい。", "友達はいつもすごいアイデアを思いつくんだ。僕はとても敵わないと思ってた……今日まではね! すごいものの設計図を描き上げたところなんだ! 誰にも言わないって約束してくれたら、秘密を教えてあげる……\n\n機械仕掛けのイエティを作るんだ! 見たら友達はきっとびっくり仰天するし、それが落ち着いたら、絶対に感心してくれるはずさ!\n\nまずはice thistle yetiから取れるthick yeti furが要るんだ。手伝ってくれる? 奴らは南東にいるよ。", "ここで取りかからなきゃいけないことが山ほどあるんだ。できるだけ早くそのfursを持ってきてくれ!", "この毛皮完璧ね、{name}。私たちの偉大な一歩はここから始まるのよ!", 0xf5c82ef5, 0x1931bf53, 0xe5571af0, 0x0a62a942, 0xcf7621cb, "....." },
  [3784] = { "Arch Druid Runetotemの手伝い", "Thunder BluffのArch Druid Hamuul Runetotemと話してください。", "すみません、{class}。ちょっとお時間をいただけませんか。\n\nThunder BluffのCenarion Circleは、重大な研究計画への助けが必要で、あなたのような手練れの冒険者に非常に関心を持っています。私は詳しく知りませんが、他ならぬHamuul Runetotemがこの研究を指揮していることはお教えできます。\n\nどうか、もし興味がおありならばElder Riseにいる彼と直接話してください。", nil, "ごきげんよう、{class}。我々の研究の手助けに興味を持ってくれて嬉しく思う。やることが多すぎるんだ。この仕事が危険でないと言ったら、君の気分を害するかもしれないな。願わくば、嫌気がさして帰ったりしないで欲しいが……しかし、君の顔を見れば分かるよ。前にも同じような危険な仕事を捌いてきたってね。", 0xba8dc721, 0xaac27949, 0x6fcc5bd2, nil, 0x93151f63, "...m." },
  [3785] = { "Morrowgrainの研究", "Evergreen PouchにPacket of Tharlendis SeedsとUn'Goro Soilのサンプル二つを入れて使い、Morrowgrainの栽培を試みて下さい。\n\nMorrowgrainを$N1個、DarnassusのMathrengyl Bearwalkerのところへ持って行って下さい。", "これがあなたのEvergreen Pouchです。Tharlendisの種を使うのに必要になります。それから、種の肥料として使うUn'Goro soilのサンプルも手元に用意しておく必要があります。すべて揃ったらポーチを使うだけです。あとはポーチがやってくれます。\n\nmorrowgrainが十分に集まったら、この聖域にいる私のところへ持ってきてください。どうか大ドルイドの邪魔はしないでくださいね。とても忙しいお方ですから、誰かがmorrowgrainをまた一束持ち帰るたびに煩わされる必要はないのです！", "ええ、{name}。大ドルイドの大切な研究のために、morrowgrainを育ててくれましたか? 彼がCenarion Circleのために行っている仕事はとても重要です。あなたの助力は必ず報われますよ!", "よくやってくれました、{name}。大ドルイドご自身が必要とされる時に、必ずこれをお渡しします。それまでの間、Cenarion Circleからの感謝のしるしとして、これをお受け取りください。\n\nmorrowgrainは絶えず必要としています。引き続き協力していただけるなら、さらにmorrowgrainを育てたら私のところへ戻ってきてください。", 0x5cd3af85, 0x364ac53e, 0x81f87e3a, 0x859e04b5, 0xbb7b95ba, "....." },
  [3786] = { "Morrowgrainの研究", "Evergreen PouchをPacket of Tharlendis SeedsとUn'Goro Soilの標本2つに使い、Morrowgrainを栽培して下さい。\n\nMorrowgrainを10個集め、Thunder BluffのBashana Runetotemに渡して下さい。", "Evergreen Pouchをご用意しました。これはTharlendis seedを使う時に必要なものです。それと、種の肥料として使うUn'Goro soilの標本も必要です。必要なものすべてが揃ったら、ポーチを使うといいでしょう。あとはポーチが面倒をみてくれます。\n\nmorrowgrainが集まったら、私のところへ持ってきて下さい。Arch Druidの邪魔をしないようにして下さいね。父は数多くの関心事と研究を抱えて、とても忙しいのです。", "ええ、{name}。大ドルイドの大切な研究のために、morrowgrainを育ててくれましたか? あなたが力を貸してくれるおかげで、Un'Goro Craterの不思議な性質は日ごとに明らかになってきています。", "素晴らしいです、{name}。これは、Arch Druidが種を必要とする時に必ず渡します。そうそう、Cenarion Circleからの感謝の印に、これを受け取って下さい。\n\n今のところ、私たちは常にmorrowgrainを必要としています。もし援助を続けて下さるのでしたら、さらに種を栽培できたらまた来て下さいね。", 0x5cd3af85, 0x779a0170, 0x0af38d1b, 0x7c5db02e, 0x3fc7561d, "....." },
  [3787] = { "Jonespyreの依頼", "Feathermoon StrongholdのQuintis Jonespyreと話して下さい。", "失礼、友よ……\n\n私の同僚が、あなたがCenarion Circleと共に進めている研究について、あなたと話をしたがっています。Quintis Jonespyreという名のドルイドで、FeralasのFeathermoon Strongholdに住んでいます。彼はmorrowgrainについてあなたと相談したいそうです……そして、この話は大ドルイドの耳に入らないようにしてほしいと強く望んでいます。\n\n興味があれば、彼と話してください。話せば、きっとすべてが明らかになるでしょう。", nil, "よくぞ来てくれた、疲れた旅人よ! 自己紹介をさせてもらおう。私はQuintis Jonespyre、ドルイドであり、MalfurionとCenarion Circleに仕える謙虚な僕だ。私の同志たち(General Shandris FeathermoonとProtectorate――名前を聞いたことがあるかもしれないな)と私は、君がDarnassusでFandral Staghelmのために行っている仕事について、話がしたかったのだ。\n\n話を先に進める前に、この話し合いは私たちの間だけに留めておいてほしい。それで問題なければ、始めるとしよう。", 0xb0b67119, 0xf2782e63, 0xaf54904d, nil, 0x8fcfd489, "...m." },
  [3788] = { "Jonespyreの依頼", "Feathermoon StrongholdのQuintis Jonespyreと話して下さい。", "失礼、友よ……\n\n私の同僚が、あなたがCenarion Circleと共に進めている研究について、あなたと話をしたがっています。Quintis Jonespyreという名のドルイドで、ここFeathermoon Strongholdに住んでいます。彼はmorrowgrainについてあなたと相談したいそうです……そして、この話は大ドルイドの耳に入らないようにしてほしいと強く望んでいます。\n\n興味があれば、彼と話してください。話せば、きっとすべてが明らかになるでしょう。", nil, "よくぞ来てくれた、疲れた旅人よ! 自己紹介をさせてもらおう。私はQuintis Jonespyre、ドルイドであり、MalfurionとCenarion Circleに仕える謙虚な僕だ。私の同志たち(General Shandris FeathermoonとProtectorate――名前を聞いたことがあるかもしれないな)と私は、君がDarnassusでFandral Staghelmのために行っている仕事について、話がしたかったのだ。\n\n話を先に進める前に、この話し合いは私たちの間だけに留めておいてほしい。それで問題なければ、始めるとしよう。", 0xb0b67119, 0xf2782e63, 0x51236f26, nil, 0x8fcfd489, "...m." },
  [3789] = { "Arch Druid Staghelmの手伝い", "DarnassusのArch Druid Fandral Staghelmと話して下さい。", "失礼します、{class}。もしよろしければ、少しだけお時間をいただきたいのです。\n\nDarnassusのCenarion Circleが、重要な研究計画に力を貸してくれる、あなたのような熟練の冒険者を探しています。詳しいことは存じませんが、ほかならぬArch Druid Fandral Staghelmがこの研究の先頭に立っていることはお伝えできます。\n\nどうか――もし興味がおありでしたら、Darnassus本土のCenarion Enclaveで、直接彼と話してください。", nil, "さて、{class}……私自らがこの研究を率いていると知らされたのだから、当然、できる限り急いで来たのだろうな。\n\nここに来たからには、最初に説明するときにしっかり聞いておくことだ。同じことを繰り返すつもりはないのでな。", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3790] = { "Arch Druid Staghelmの手伝い", "DarnassusのArch Druid Fandral Staghelmと話して下さい。", "失礼します、{class}。もしよろしければ、少しだけお時間をいただきたいのです。\n\nDarnassusのCenarion Circleが、重要な研究計画に力を貸してくれる、あなたのような熟練の冒険者を探しています。詳しいことは存じませんが、ほかならぬArch Druid Fandral Staghelmがこの研究の先頭に立っていることはお伝えできます。\n\nどうか――もし興味がおありでしたら、Darnassus本土のCenarion Enclaveで、直接彼と話してください。", nil, "さて、{class}……私自らがこの研究を率いていると知らされたのだから、当然、できる限り急いで来たのだろうな。\n\nここに来たからには、最初に説明するときにしっかり聞いておくことだ。同じことを繰り返すつもりはないのでな。", 0x683edaeb, 0xf466e7fe, 0x53a106de, nil, 0x0de267fb, "...m." },
  [3791] = { "Morrowgrainの謎", "Morrowgrainを$N1個、Feathermoon StrongholdのQuintis Jonespyreのところへ持って行って下さい。", "率直に言わせてもらいますよ、{name}。私が興味を持っている――いや、懸念しているのは、なぜDarnassusの大ドルイドが、Cenarion Circleの名とCircleの資源を使って大量のmorrowgrainを手に入れようとしているのか、ということです。私は研究者で、呪いが専門です。morrowgrainはしかるべき条件の下で、原始的な呪いに使われる他の薬草と同じような性質を放つと聞いています。\n\nもっと知りたいので、あなたの助けをお願いしたい。morrowgrainを十個持ってきてくれれば、きちんとお礼をしますよ。", "私が探しているのは10個のmorrowgrainだ。少なくとも研究を始めるにはそれで足りるはずだ。間違った道を進んで、きっとたくさん使い潰してしまうだろうが、それが研究というものだ。", "うう、このmorrowgrainはどうも……変な気分になる。Eluneの名にかけて、Staghelmはこんなもので何を企んでいるんだ?\n\nとにかく、改めて手伝ってくれてありがとう。ささやかだが受け取ってくれ……まあ、手間賃だ。morrowgrainの研究にはしばらくかかるし、きっともっと必要になる。ついでに、morrowgrainに錬金術で役立つ使い道がないかも調べてみようと思う。それでも、そばにいるだけで落ち着かないんだ。", 0xd8cf82fd, 0xeb7239db, 0x4a5fec1a, 0x216361ab, 0x9f0f22f5, "....." },
  [3801] = { "Dark Iron族の遺産", "都市中枢への鍵を入手することに興味があるのならば、Franclorn Forgewrightと話して下さい。", "ごきげんよう、{name}。我はFranclorn Forgewright。そう、stonewrought様式の建築を生み出した、あのFranclorn Forgewrightだ。戦に引き裂かれたこの世界を冒険する中で、そなたも我が創造物のいずれかを通り抜けたか、その上に立ったことがあるに違いない。\n\n我がなぜここにいるのか、そしてそなたに何を望むのか、おそらく不思議に思っていることだろう――どちらももっともな疑問だ。\n\nもちろん、そなたの助けが要るのだ。その助けと引き換えに、我が呪われし都の深部への鍵を授けよう。", nil, "君をここに連れてきたのが強欲であろうが、私利私欲の無い献身による行いであろうが、君が引き受けようとしていることは我々すべてにとっての利益なのだ。", 0x3b3da85f, 0x0a06140f, 0x0658260b, nil, 0x70085210, "...m." },
  [3802] = { "Dark Iron族の遺産", "Fineous Darkvireを討ち取り、大いなるハンマーIronfelを取り戻して下さい。IronfelをShrine of Thaurissanへ持って行き、Franclorn Forgewrightの石像に安置して下さい。", "Fineous Darkvireは、Ring of Lawの先、Hall of Craftingにいる。あの卑しい犬めを殺し、Ironfelを取り戻すのだ。\n\nIronfelをShrine of Thaurissanへ持って行き、槌をあるべき場所に置け。すなわち、我を讃えて建てられた像の両手の中にだ。\n\nそれが済めば、我がマスターキーを納めた隠し場所が開く。さらに重要なのは、Ironfelが永遠に我が手の中にとどまることだ。奴らがその槌を取り除こうとすれば、像も槌も砕け散り、永遠に失われるであろう。", "像があなたの頭上に不気味にそびえ立っている。", "ハンマーはあるべき場所、巨大なDark Iron族の石像の手中へしっかりと滑り込んだ。石像の台座にある小さな収納庫が開いた。その中に見つけたのは……", 0x3b3da85f, 0x7dade027, 0x84d5a972, 0x75236cb2, 0x92bd876f, "....." },
  [3821] = { "Dreadmaul Rockへ", "Burning Steppesにむかい、Sha'ni Proudtuskがどうしているか調べてきてください。", "３週間前Sha'niはBurning SteppesのFiregut ogreどもの奇妙な儀式のうわさを確認するために調査へ出た。\n\nGoretoothは小隊の誰とも連絡がつかないそうだ。そして私に目下の任務に集中するのが一番だといった。馬鹿なことを言うな！私の妻だぞ！\n\n{name}、私はここを離れることができない。しかしSha'niの身に何が起きたか知りたい。Burning Steppesへ行き、彼女を捜してほしい。", nil, "かわいそうなThal'trak。\n\nこの遠征が終わったら、私の両親と一緒にHinterlandsに引っ越すつもりだったの。でもそれもだめになっちゃったね。", 0x4b469dbd, 0x5f7281f1, 0x81b81b47, nil, 0x5b741fec, "...m." },
  [3822] = { "Krom'Grul", "Sha'ni's Nose-RingをKrom'Grulから取り戻し、KargathのThal'trakに渡してください。Dreadmaul Rockの洞窟や坑道を隅々まで捜しなさい。", "私の小隊はとらわれたわ、{name}。みんな殺された・・・私を除いて。\n\nやつらのリーダーKrom'Grulは、私をある儀式のために生かしておいたの。\n\n獣どもにこの祭壇につながれ、残忍な扱いをうけたわ。苦痛のときが過ぎて私の生命は失われた。あの野獣は私の顔から結婚記念のノーズリングを引きちぎると、自分の指にはめた。こんなひどいことは初めてだわ！\n\nKrom'Grulを見つけ出し殺して！私のリングをThal'trakのもとへ戻して。\n\nそして{name}、彼に伝えて。いつかまた・・・きっとあえるって。", "Sha'niを見つけてくれたか? 彼女は無事なのか?", "<Thal'trakは座り込んでしまった。>\n\nHinterlandsに引っ越すつもりだったんだ。あいつから聞いたかい？これがあいつの最後の仕事だったんだ。\n\n<Thal'trakはすすり泣いた。>\n\nもうそれはいらん、{name}。どこかに捨ててきてくれ。かまわん！そのリングはもはや何の意味もない。あいつがいなきゃ・・・", 0x72ff97e9, 0xb1056733, 0x6ba1cbac, 0xd0890e0f, 0x91277ed6, "....." },
  [3823] = { "Firegutの殲滅", "Firegut Ogre-Magesを$N1体、Firegut Ogresを$N2体、Firegut Ogre Brutesを$N3体倒し、終わったらOraliusのところへ戻って下さい。", "敵に攻撃される前に、こちらから攻撃せねばならん！\n\n手短に話すぞ、兵士。\n\nBurning SteppesのFiregut ogresは、Blackrockのオークどもの同盟者だ。あの卑劣なオークどもと密に手を組み、鉱物の豊富なDreadmaul Rockを守り、補給線を常に開いている。\n\n爪痕を残してこい、{name}。奴らの戦力を叩き潰し、仕事が済んだら戻ってこい。\n\n<Oraliusは宙をつかみ、首を絞めるような仕草をする。>\n\nぶっ殺してやるぞ、WINKY！", "お前の軍服には血がまったく足りんぞ、兵士よ!", "見事だ、兵士よ! オークもogreも、この一撃で数分は、いや数時間はよろめくことだろう!", 0x554f266e, 0x2ec663c4, 0xb66dbe20, 0xc3904a24, 0x4c7f645a, "....." },
  [3824] = { "Gor'tesh the Brute Lord", "Dreadmaul Rockの西のどこかにいるGor'teshを見つける。Gor'teshを倒し、Gor'tesh's Lopped Off HeadをBurning SteppesのOraliusのところへ持ち帰って下さい。", "奴らはよろめいている、本当だ！次の一撃は決定的なものでなければならん。\n\n獣の親玉、Gor'teshを始末せねばならん。さらに重要なのは、奴の首を私のもとへ持ち帰ることだ。そうすれば、Firegut ogresへの攻撃の第三段階を準備できる。\n\n気をつけろ、兵士。Gor'teshはDreadmaul Rockからではなく、Dreadmaul Rockの西にあるBlackrockのオークの建物から支配している。\n\nでは、お前への命令は単純だ。Gor'teshを見つけ、その太った首を切り落とせ。仕事が済んだら戻ってこい。\n\n黙れ、WINKY！", "ああ、なんと輝かしい日だ! headを持って戻ったのか?", "見てみろ、兵士よ。胸糞悪い! 生き残ったFiregutのogreどもが、山の頂で槍の先に刺さったこのでぶ面を見たら、大混乱に陥るぞ!\n\n<Oraliusは狂ったように高笑いする。>", 0x54d3ea44, 0xcc0b01ae, 0xa6812770, 0xb3a59526, 0x96911f40, "....." },
  [3825] = { "棒に刺したオーガの首 = パーティー", "Gor'tesh's Lopped Off Headを持って行き、Dreadmaul Rockの頂上に置いて下さい。槍を突き立てるための柔らかい土の盛り上がりを探して下さい。", "最後にもう一つだけやってもらうことがある、兵士。\n\n勝手ながら、Gor'teshの首を槍に刺しておいた。あとはこの首をDreadmaul Rockの頂上へ持っていって、地面に突き立てるだけだ。そうしたら、臆病なogresどもが必死に逃げ出す様を眺めてやれ！存分に楽しんだら戻ってこい。これまでの働きすべてに報いてやろう。\n\n<Oraliusは現実を見失いつつあるようだ。>", "で? その出来事の絵は描いてきたのか?", "見事な働きだ、兵士よ! 実に素晴らしい! これで私は勇気の勲章をもらえるぞ、あ、いや、つまり、お前はたっぷりと報われるだろう!", 0x8a014f90, 0xdb9ec250, 0x54fb7628, 0xf5a6ea7c, 0x57272f80, "....." },
  [3841] = { "家を探す孤児", "Thousand NeedlesのQuentinと話して下さい。", "あら、こんにちは、{name}。また会えて本当に嬉しいわ。Darnassusへの旅はどうだった？\n\nそうそう、あなたが留守の間に、私たちはかなり進展したのよ。卵でいっぱいの巣を一つ救うこともできたの。残念ながら、母親は私たちが駆けつける前に死んでしまったけど。\n\nねえ、一つペットにしてみない？もうすぐ孵りそうだから、いい親が必要になるの。どうかしら？\n\n本当に興味があるなら、卵を一つShimmering Flatsのレース場にいるQuentinのところへ持っていって。詳しいことは彼が教えてくれるわ。", "おや、こんにちは、{class}。\n\n私がこんな場所にいるからといって勘違いしないでくれ。レースを見に来たわけではないんだ……見ていて楽しいのは確かだがね。\n\n実はここThousand Needlesで、この土地がどれほど再生できるかを知るために、できる限りの調査をしているんだ。新しい肥沃な土でこの一帯を蘇らせ、満たすことが、いわば私の使命になっていてね。もしかすると近くに水源が見つかるかもしれない。\n\nFeralasとThousand Needlesの境目がどれほど奇妙か、気づかなかったとは言わせないよ。あれが起きたとき、何か奇妙な魔法が働いていたんだ。", "ああ、sprite darterの卵か。それも、私の見立てが間違っていなければ、孵化も間近だ。見つけただけでも驚きなのに、ましてやこれほど良い状態とはな。最近ではFeralasで見かけることもめったにない。何かと理由をつけて捕まえたり殺したりしようとする密猟者たちが、この辺りにいたと聞いている。本当に残念なことだ……成長すれば、実に美しい生き物なのに。\n\nどうやってこんなものを見つけたんだ?", 0x5fb944d9, 0xac2225f9, 0xf0029122, 0x723b29ea, 0x70686f0c, ".....", nil, nil, 0x36604c86, nil, nil },
  [3842] = { "短い孵化", "Elixir of Fortitudesを$N1個、Thousand NeedlesのQuentinのところへ持って行って下さい。", "Moonweaversだって？実に興味深い。あの二人に面倒を見てもらうことがどういう意味か、sprite dartersが本当に分かってくれたらいいのだがね。二人ともなかなかの腕前だ。\n\nそれで、彼らが贈り物として卵をくれたわけか。ならば、君が望む限り、君がその卵に責任を持つべきだろう。もうすぐ孵るようだが、健康で、傷ついていないことを確かめておかないとな。\n\n卵を守るちょっとした呪文のために、elixirs of fortitudeが二つだけ必要なんだ。残りの材料はここに揃っている。", "ここに長くいればいるほど、このレースに参加したくなってくるよ、{name}。まったく訳が分からない……\n\nelixirsはもう見つかったかい? 卵が健康に育つかどうかが分かったら、孵化の準備ができるまで君に預かっておいてもらうために返すよ。\n\n知らせてくれ。", "素晴らしい。これで十分だ。材料を混ぜ合わせるから、少し待ってくれ。この卵がどうなるか見てみよう。", 0xe65f357f, 0x8f43c40b, 0x781716b8, 0x18629421, 0xebcc26c9, "....." },
  [3843] = { "家族の新しい一員", "Fragile Sprite Darter EggをHinterlandsへ持って行き、Agnar Beastamerと話して下さい。ただし急ぐこと。卵の中のひなが死ぬまでに、彼を見つけるための時間は$D1しかない。", "見事な標本だ、{name}。この生き物が無事に育てば、実に健康なペットになるだろう！\n\n最後までやり遂げるつもりなら、もう一つ勧めたいことがある――HinterlandsのAerie Peakへ行ってくれ。そこにいるAgnar Beastamerというドワーフと話すといい。熟練の動物使いで、孵化の最後の段階を指南してくれるはずだ。\n\nだが急いでくれ、{name}。この卵は壊れやすく、きちんと世話をしなければ長くはもたない。", "よう、{name}。何か力になれることはあるかい?", "ほう、ほう、ほう……こいつはずいぶん久しく見ていなかったな。私の見立てが間違っていなければ、faerie dragonだ……sprite darterの種類のようだな。素晴らしい、実に素晴らしい。\n\nさて、このちびが孵って強く健康に育つには、何か食べ物を用意してやらにゃならん。間に合ううちに私のところへ持ってきてくれてよかったよ。", 0xaf971660, 0xdea8bb91, 0x9ccd4b04, 0xcae6d14e, 0xada97a0a, "....." },
  [3844] = { "みんなには秘密", "池の周りを調べ、この壊れたいかだが誰のものかの手がかりを探して下さい。", "岸辺に壊れた筏が横たわっている。ここはほんの小さな池にすぎないので、どうやってここへ流れ着いたのかははっきりしないが、木々を見ると、水位は一定ではないのかもしれない。\n\nこのあたりを少し探索すれば、さらに手がかりが見つかるかもしれない……", nil, "水の染みた荷物が、池の底に沈んでいる。", 0x3bc250db, 0x4c34ad92, 0xa109fe23, nil, 0x48822233, "...m." },
  [3845] = { "みんなには秘密", "荷物の中の品を調べ、持ち主のところへ届けて下さい。", "それをつかんで、荷物を岸へ引き上げた。中の品を調べれば、持ち主についてもっと分かるかもしれない。\n\nMarshal's Refugeに、はぐれた旅人が何人かいる。そこでもっと詳しいことが分かるかもしれない。", "やあ。前に会ったことがあるよね……違ったかな?", "ああ……そう、確かに見覚えがある……まあ、なんとなくだけど……", 0x3bc250db, 0x3b5ff13f, 0x813cc439, 0x66133329, 0x61e3e44d, "....." },
  [3861] = { "コケーコッコッ!", "Special Chicken Feed を探し、仲良くなった鶏のところへ戻る。鶏を見つけたら、Special Chicken Feed を与える前に /cheer (コマンドを使用)する。", "「コッ……コッ……コッ……コケーッ！\n\nコッ……コッ……コッ。」\n\nニワトリはあなたを見上げると、爪で地面をひっかき始めた。何かの言葉をつづっているようだが、何なのかはよくわからない。もしかして……S-A-L-D-E-A-N？尋ねる前に、ニワトリはそっぽを向いて自分の用事に戻ってしまった。", "鶏は暗く冷たい目であなたを見つめている。腹を空かせて、あなたを待っている。\n\n「コケーーッ!\n\nコッ……コッ……コッ。」", "「BACAW!!!」\n\nニワトリはあなたがまいた餌をがつがつと食べ始めた。\n\nしばらくすると、ニワトリは驚いたように辺りを見回した。落ち着かない様子で前後にうろうろしている。このニワトリ、身ごもっているのだろうか? 下を確かめてみた方がよさそうだ。", 0x15276154, 0x72531b26, 0xa6190e7e, 0x6aec8435, 0x76e1a259, "....." },
  [3881] = { "遠征隊の救援", "Crate of FoodstuffsとResearch EquipmentをUn'Goro CraterのWilliden Marshalのところへ持って行って下さい。", "どうやってここまで来たのか知らないが、会えて本当に嬉しいよ！私はWilliden Marshal、どの勢力にも属さない探検隊を率いている。我々の最新にして最大の事業は、数えきれないほどの災難に見舞われているようでね。中でも一番深刻なのは、Un'Goro Craterの凶暴さを甘く見ていたことだ！\n\nクレーターの南西部と北東部にあったベースキャンプから逃げ出したとき、大事な物資を置いてきてしまった。君はなかなか腕が立ちそうだ――取り戻すのを手伝ってくれないか？", "ここから生きて出られる見込みを少しでも持つには、大きなcrate of foodstuffsが必要だ。それに、research equipmentを少しでも取り戻せれば、この悲惨な状況の中での救いになるだろう。", "foodstuffとresearch equipmentの両方を取り戻してくれたんだな！遠征隊を救ってくれただけじゃない、私たちの命まで救ってくれた。私もチームの皆も、感謝してもしきれない。君のおかげで、しばらくはここでやっていけるかもしれない。\n\n大したものはないが、これほど貴重な助けをしてくれた君を手ぶらで帰すわけにはいかない。ありがとう、{name}。Marshal Expeditionsには君の友がいるぞ！", 0x2ffaf72d, 0xd8277369, 0xc27d3349, 0xd0aa3c51, 0x40e21d40, "....." },
  [3882] = { "骨を転がせ", "Dinosaur Bonesを$N1個、Un'Goro CraterのSpark Nilminerのところへ持って行って下さい。", "Marshal Expeditionsの発掘主任なんだから、掘るのが好きなんだろうと思うだろう。この世にはもっとひどい仕事もあるのかもしれないが……まるで思い浮かばないね。\n\n俺たちはTerror Runで――ところで最高の名前だろ――死んだstegodonsやdiemetradonsを掘り出すはずだったんだ。ところが、あそこには生きてるやつもわんさかいる！WilとHolはまだこの死の罠を研究する気満々だから、dinosaur bonesが必要なんだ。ただ、ここだけの話、生きてるやつから取ってきても同じくらいうまくいくぜ。", "私のことをどう思おうと勝手だが、研究用に届くbonesが古代のstegodonsやdiemetradonsのものか、それとも私たちが野営地を設営しようとしていたときに丸ごと食い殺しかけた奴らのものかなんて、向こうは気にしないだろう。私はここから生きて出られれば、それで満足だ……", "よし、これで何とかなるはずだ。では、ちょっと失礼して……\n\n我々のためにこのBONESを全部地面から掘り出してくれて、しかも現地の獣たちを一切傷つけなかったことに感謝する。\n\n本当にそうだったのかどうかは、知りたくない。そういうことにしておこう、いいね？ほら、これで口をつぐんでおいてくれ。ここから生きて出られるなら何でもする、それが私の考えだ！", 0x163fb225, 0x257e9148, 0x5ed6ddc4, 0x1ac4da25, 0x8df00135, "....." },
  [3883] = { "異質な生態系", "Scraping Vialを使って、Un'Goro CraterにあるGorishiの巣の孵化場の一つからHive Wall Sampleを採取する。幼虫がぶら下がっている部屋を探して下さい。\n\nHive Wall SampleをUn'Goro CraterのHol'anyee Marshalのところへ持って行って下さい。", "挫折したからといって、研究を止めなければならないわけではない！ここに流れ着く前、我々はクレーターの南部でGorishiの昆虫を調べていた。奴らの存在はUn'Goroの生態系にとって異質なもので、我々はその理由を突き止めたいんだ。\n\n奴らの巣のネットワークのどこかに幼虫の孵化場があるはずだ。そういう場所は、ぶら下がった幼虫の卵で見分けられる。この小瓶を使って、どれかの孵化場の近くでhive wallのサンプルを取ってきてくれ。研究のために私のところへ持ち帰ってほしい。だが気をつけてくれ！", "私が調べるためのGorishi hiveのsampleは持ってきてくれたかい、{name}?", "ああ、これで十分だ。本当に助かったよ……もっと渡せればいいんだが、この野蛮な土地の真ん中で事実上取り残されている身では、渡せるものにも限りがあってね。だが安心してくれ。君の協力がなければ、ここでの研究は成し得なかった！", 0xcf01b983, 0x1d4c9802, 0xe8755f09, 0x7d3d682e, 0xa95770c0, "....." },
  [3884] = { "Willidenの日誌", "日誌を、Un'Goro CraterのどこかにいるWilliden Marshalのところへ返して下さい。", "ぼろぼろになった日誌を見つけた。一部はまだ読むことができ、Williden Marshalという人物がその中身の持ち主だと記されている。日誌が正確なら、WillidenはCraterの北部のどこかにいるかもしれない。日誌によれば、彼と仲間たちはベースキャンプを制圧されたあと、Craterの凶暴な獣から逃れるため高台を目指したという。", "やあ! 伸び放題の獰猛な獣以外の生き物にここで会えて、仲間たちも私もうれしいよ! Un'Goro Craterへは何の用で来たんだい?", "おや、これは……私の日誌じゃないか！Un'Goroに持ち込んだほとんどすべての物と同じく、失くしたものと思っていたよ。返してくれて本当にありがとう！", 0x61668177, 0xb6359148, 0xd6d9ed61, 0xcd2b79cd, 0xbc784e74, "....." },
  [3901] = { "Rattling the Rattlecages", "Rattlecage Skeletonを12体倒してください。やり遂げたらDeathknellにいるShadow Priest Sarvisのもとへ戻ってください。", "Forsakenとしての潜在力を平常心においては示せたな、{name}。-さて少し難易度を上げるとしようか。\n\nLich Kingの更なる非情な手先、Rattlecage skeletonはこれまで出会ったどのゾンビよりもタフだぞ。今再び、奴らを倒してForsakenであることを証明するのだ。ぐずぐずしている暇はない。-やりとげたなら私の元へ戻ってくるのだ。", "この任務でぐずぐずする者は、村で倒れた我らの兄弟姉妹のように、あてもなくさまようことになるだろう。お前は彼らよりうまくやれるといいがな、そうだろう?", "お前との用は済んだ、{name}――お前は与えられた自由にふさわしい者だと示してみせた。お前がなったものゆえに、多くの者が立ちはだかるだろう。だが覚えておけ、奴らが我々に何をしようとしても、我々は自由であり、二度と鎖につながれはしない。\n\nこれを取って、行くがいい。お前にはなすべきことが多くある、{class}。", 0x044eea75, 0xcf755d52, 0x04a1073b, 0x9538ef09, 0x9bd22007, "....." },
  [3902] = { "Deathknellの物資漁り", "Deathknellとその周辺からScavenged Goodsを6つ探し出し、Deathguard Saltainのところへそれらを運んでください。", "そこのあんた！いい話があるんだが聴きたくないかい。\n\n我々は生まれたての新兵をDeathknellに向かわせて、何か使えるものがないか探させているんだ。有望なのは積み上げられた箱の中だろう。もっと多くの新兵が現れるのを期待しているが、裸じゃかわいそうなんで何か使えるものがないか探しておいたほうがいいだろう！\n\nうまくやれよ、惨めな骨くん。努力しないものに何かを与えるつもりはないからな。", "何か役に立つ品を拾い集めてこられたか? 捨てられた物を再利用するのは恥ではない。誰も我々に施しなどくれはしない。我々Forsakenは自力で生き抜くのだ!", "よくやった{name}、できる奴だと思っていたよ。ここに-今まで集めた中から選りすぐったものがある。一つ持っていくといい。", 0xaae13cb4, 0x229db0af, 0x9da89248, 0x3376988f, 0xbaaab0ef, "....." },
  [3903] = { "Milly Osworth", "Milly Osworthと話す。", "{name}、君は頼りになる{class}だと証明してくれた。頼りになるうえに、手を汚すのも恐れない、だろう？\n\n私の友人のMilly Osworthが困っているんだ。修道院の反対側、厩舎の近くに荷馬車と一緒にいる。君のような人手があれば、きっと助かるはずだ。", nil, "おや、Deputy Willemに私と話すように言われたのですか？彼は勇敢な人で、いつも進んで手を貸してくれます。でも職務のせいでNorthshire Abbeyを離れられませんし、今日私が抱えている問題は、彼の手に余るのではないかと思うのです。\n\nあなたなら助けていただけるでしょうか？", 0xe1f36bcd, 0xf258ab38, 0x7ad88966, nil, 0xcb7f07d4, "...m." },
  [3904] = { "Milly's Harvest", "Northshire AbbeyにいるMilly Osworthに、Milly's Harvestを8カゴ持ってくる。", "Defiasという盗賊集団が、収穫中にNorthshire Vineyardsに侵入してきたのよ！すぐにNorthshireの衛兵に知らせたわ。衛兵達は何とかするって言ってくれたけど、大事な葡萄のことを思うと、気が気でないのよ！盗賊達が葡萄を盗ってないならいいんだけど、衛兵達が奴らを掃討しに行ったら、その騒ぎで葡萄が踏み潰されちゃうってこともあるし…\n\nお願い、何とかして！私、カゴの中に葡萄をたくさん集めてたんだけど、逃げる途中で南東の葡萄畑に置いてきちゃったの。\n\nそのカゴを持ってきてほしいの！私の葡萄ちゃんを救ってあげて！", "私のharvestは持ってきてくれたかしら、{name}?", "まあ、ありがとうございます、{name}！私の収穫を救ってくださいました！それに、あのDefiasの何人かに、この辺りで騒ぎを起こしてはいけないと思い知らせてくれたのならいいのですが。\n\n近頃は衛兵が足りないかもしれませんが、あなたのような英雄に守っていただけて、私たちは幸運です！", 0xb7c26a3d, 0x92647f37, 0x0fa99512, 0x44af6d31, 0xbc754155, "....." },
  [3905] = { "Grape Manifest", "Northshire AbbeyにいるBrother Nealsに、Grape Manifestを持っていく。", "これで私の葡萄は安全ね。このGrape ManifestをBrother Nealsに届けてくれないかしら。彼はNorthshire地方の食糧を管理しているの。この新鮮な葡萄を見たら、きっと大喜びするはずよ。\n\nBrother Nealsは修道院の鐘塔にいるわ。そこでワインを味わうのが好きな人だからすぐに見つかるわよ。", "ずいぶんご機嫌じゃないか! さあ! 座って一杯やってくれ!", "さて、どれどれ……\n\nおお！Millyのブドウが守られたのですね！山賊どもに彼女のブドウ畑を荒らされたと聞いたときは絶望しかけましたが、光への信仰は揺らぎませんでした！\n\nそしてあなたの勇気のおかげで、またワインを造るためのブドウが手に入りました！光があなたを祝福し、守ってくださいますように、{name}！", 0x46e6ddee, 0x54a8efd7, 0x7e4adc7b, 0x920c46b4, 0x8ad49c5d, "....." },
  [3906] = { "炎の不協和音", "Blackrock Mountainの石切場へ行き、Overmaster Pyronを討ち取って下さい。この任務を終えたら、Thunderheartのところへ戻って下さい。", "長老たちが精霊の間に乱れを感じ取った。Dark Ironのドワーフが邪悪な精霊をこの世界に呼び出し、それが我らの地を果てしない日照りで苦しめようとしている。この炎の不調和を調べねばならん。\n\nBlackrock Mountainへ行き、Chasm of Flameを抜けて採石場へ入れ。そこでこの炎の王、Overmaster Pyronを見つけるだろう。\n\nその乱れを終わらせ、私のもとへ戻ってこい。", "精霊たちはいまだ乱れたままだ、{name}。", "そんなはずが……そんなはずがない。Pyronの殺害はベールを取り払っただけだった。Blackrockの深淵内部には、はるかに陰湿な汚染源が潜んでいるのだ。", 0x12c28708, 0x0cb7f2a4, 0x72589669, 0x602e93ef, 0x99670efd, "....." },
  [3907] = { "火の不協和音", "Blackrock Depthsへ行き、Lord Incendiusを見つけ出して下さい。彼を討ち取り、あなたが見つけた情報源をThunderheartのところへ持ち帰って下さい。", "お前を包む空気に、穢れの味がする、{name}。Blackrockの深部に隠れ、この穢れを操っている者が他にいる。\n\n風と大地がその名を叫んでいる。Lord Incendius……だが何者かが……何かが、この存在を支配している。奴はただの使者にすぎん。\n\n奴を見つけ、その主がどこに潜んでいるのか突き止めろ。その情報を集めたら、私のもとへ戻ってこい。", "炎はまもなくこの地を飲み込むだろう。急げ、{name}!", "<ThunderheartがTablet of Kurniyaを握りしめる。>\n\nRagnarosが……ここに……\n\n長老たちがBlackrock Mountainから発する腐敗を恐れたのは正しかった。Old Godsの将軍だと! この我らの世界に! ここKargathでの我々の立場を見直さねばならん。踏みとどまって戦うか、新たな大破壊を恐れて逃げるか、決めねばならん。\n\nBlackrock Mountainをこれ以上探索するのは用心せよ、{name}。この世に存在するいかなるものよりも遥かに大きな悪が、あの燃える深部に潜んでいる。", 0x179734dd, 0x14a0125f, 0xd13aa2b5, 0x89659896, 0xf5b4afe0, "....." },
  [3908] = { "みんなには秘密", "Linken's SwordをWinterspringのDonova Snowdenのところへ持って行って下さい。", "実はね、どうしてここに来ることになったのか、まったく分からないんだ。誰も本当のことは知らない――みんなには秘密なのさ！どうしても何も思い出せなくて……\n\nでも、君が持ってきてくれたこの品……何かを思い出しかけてるよ。\n\n僕の剣。どうにかしてこれを強くするはずなんだけど、なぜなのかはよく分からない。これ以上話せなくてごめん、でも本当に思い出せないんだ！\n\nそれはともかく、どこへ持っていけばいいかは分かってる――WinterspringのDonova Snowdenだ。温泉のそばにいるはずだよ。彼女ならそこの泉で剣を鍛え直せるんだ。", "おやおや……Linkenのやつ、ようやく私に剣を送ってよこしたのかい。", "ああ、もちろんこの剣は鍛え直せるとも。作業している間に、Linkenがこれを私に届けるのに何でこんなに時間がかかったのか説明してくれ。あいつは普段、物事を忘れるような奴じゃないんだが……", 0x3bc250db, 0x967007ba, 0x7ca1e461, 0x92bb2dab, 0x48bc10c9, "....." },
  [3909] = { "Videre Elixir", "Feralas北部のGregan Brewspewerを探し出す。Videre Elixirを手に入れる方法を彼から聞き、WinterspringのDonova Snowdenのところへ戻って下さい。", "さて、これは何かしら？Linkenが……忘れた？\n\nああ、なるほど……記憶を失ったのね……\n\nじゃあ、これが彼の剣よ。でもまだ完成していないの。仕上げられる者を知っているけど……その者と話すのは難しいかもしれないわ。\n\nいい、あなたを助けられる人を知っているの。今は説明しきれないけど、あなたはどうにかしてVidere Elixirを手に入れなければならないの。それを手伝えるのは、私の知る限りGregan Brewspewerだけよ。見つけるのは大変だけど、最後に聞いた話では、Feralasの荒野で野営しているそうよ。", "もう戻ったのか?", "本当にelixirか確かめるために1本必要だ……うん……これは本物だ。", 0x2cdfc19c, 0x6fde17bf, 0xfc8b3a73, 0x721001d5, 0xa88964c5, "....." },
  [3911] = { "最後の元素", "Blackrock Depthsへ行き、Essence of the Elementsを$N1個回収して下さい。まず思いつくのは、ゴーレムとゴーレムの製作者を調べることだ。Vivian Lagraveがエレメンタルについても何かつぶやいていたのを思い出す。", "深部へ踏み込む者には仕事があるぞ、{name}。\n\nDark Ironsは、極めて強力なゴーレムの製造を極めた。\n\n我々の密偵からの最初の報告によれば、ドワーフどもは独自の動力源を使い、その創造物に比類なき殺傷力を与えているらしい。\n\nこのessence of the elementsを手に入れられたら、我々のabominationsで何ができるか想像してみろ! 必要なら都をひっくり返してでも、essenceを見つけるまで戻ってくるな! 報酬は危険に見合うものになるぞ。", nil, nil, 0x19b2e88f, 0xb96dbad5, 0xf6bdad3c, nil, nil, "...mm" },
  [3912] = { "墓前で会おう", "Gadgetzanの外にある墓地へ行き、Videre Elixirを使って下さい。Donovaの残りの指示に従い、Gaeriyanを見つけて下さい。", "この薬を飲めば、普段なら姿さえ見えない者と話せるようになる……\n\nVidere elixirを、Linkenの剣と一緒に、TanarisのGadgetzanのすぐ外にある墓地へ持っていけ。着いたら、その薬を飲むのだ。結果にかなり驚くかもしれんが、慌てることはない。\n\nその「もう一つの」姿で、山に着くまで真北へ進め。話すべき相手は、岩の裂け目の一つにいる。名はGaeriyanだ。\n\n忘れるな、彼はその姿のお前としか話さない……", nil, "我と語らいに来る者は、長らくおらなんだ……", 0xd4eb2ee9, 0xfe910951, 0x76c74a88, nil, 0xc5e80199, "...m." },
  [3913] = { "深刻な事態", "蘇生したら、Gaeriyanに探すよう言われた墓石を探して下さい。", "墓地へ戻れば、{name}、そこに墓石が見つかるはずだ……ただの墓石ではない。他のものとは違って目立つ一基だ。その中に秘密が眠っている。\n\nその石を押せば、秘密を知ることになるだろう……", "これがGaeriyanの言っていた墓石に違いない……", "石をしっかりと押すと、石が滑るように動き、その下に小さなくぼみが現れた。\n\nLinken's Swordをそのくぼみに置くと、ぴったりと収まることに気づいた……", 0x644bf249, 0xdd68d1c4, 0xc9be6d34, 0x0620b77a, 0x6e8e34a6, "....." },
  [3914] = { "Linkenの剣", "Linken's Superior SwordをUn'Goro CraterのLinkenに届けて下さい。", "強烈な閃光のあと、再び剣を拾い上げることができた。剣は姿を変えている！", "おお! 君のことは覚えてるよ! 君は……いや、言わないでくれ!", "私のsword……完成したぞ！\n\nあとは、なぜこれが必要だったのか思い出せさえすれば……\n\nほら、せめて手間賃くらいは払わせてくれ。", 0x78d825d5, 0x1e373f37, 0xcacff99b, 0xc732a45b, 0xc86f7993, "....." },
  [3921] = { "Wenikee Boltbucket", "Broken SamophlangeをWenikee Boltbucketに渡して下さい。", "このSamophlange壊れてるかもしれない。こりゃいかんよ、だってUndermineにいる仲間にSamophlangeのこと話しちゃったんだ。そしたらあいつら、すごく興味持っちゃって。これを修理する方法を探さなきゃ!\n\nこの壊れたSamophlangeをWenikee Boltbucketに渡してくれ。BarrensとAshenvaleの間にあるhordeの前哨基地、Mor'shan Rampartのすぐ南だよ。Wenikeeはとても頭が良くて知識欲旺盛なんだ。samophlangeを見せたら、修理のチャンスに飛びつくこと請け合いだよ。", "仕事でとても忙しいんだ、{class}。何か私に用があるのでなければ、先へ進んだほうがいい……", "あら、何これ? samophlange、って言った? samophlangeって何??\n\nああ……でも、あなたが使えば動くようね。それと、内側で複雑なギアの音がしてる。ああもう! 修理して調べてみたいと思わない??", 0x60e1e274, 0x7bdd885e, 0x53dfcdc8, 0xa50b6b78, 0xec4e6f32, "....." },
  [3922] = { "Nugget Slugs", "Nugget Slug15個をBarrensのWenikee Boltbucketに渡して下さい。", "samophlangeを直したいんだけど、直すのにいくつか物が必要なの。17.5口径のnugget slugsを使い切っちゃったんだけど、それがたくさん必要になってくるのよね。\n\n手に入れるのに一番近いのは、東に行ったところにあるSludge Fenね。Venture Companyは道具入れ(tool buckets)にいつも在庫を置いてるわ。Sludge Fenへ行って、道具入れを見てきて。nugget slugsをたくさん集めたら、戻ってきてね。", "nugget slugsは持ってきたかい、{name}? このSamophlangeにずっと目をつけていて、いじるのが待ちきれないんだ。", "すごい、持ってきてくれたんだ! それじゃ仕事を始められるわね……", 0x048fd5a7, 0x60a82d68, 0x9253461d, 0xaa34b2e5, 0x1136f9bf, "....." },
  [3923] = { "Rilli Greasygob", "Broken and Battered SamophlangeをOrgrimmarのRilli Greasygobに渡して下さい。", "あれ、これ動かないわ。構造の整合性を調べるのにいくつか余分な計器を取り付けたんだけど、整合性は絶不調だって示してる。直してみるのにもっとダイヤルかレバーをちょっと付け加えてもよかったけど……もっとおかしくしちゃいそう。\n\nこれはRilli Greasygobのとこへもっていった方がいいわ。彼は昔Venture Companyで働いていたの。samophlangeの直し方を知ってる人がいるとしたら、それはRilliね。\n\nOrgrimmarのValley of Honorにある、Nogg's Machine Shopに彼を見つけられるわ。", "頭に気をつけろ! 私の仕事の邪魔になってほしくないからな!", "なんだこれ? なんと、これsamophlangeじゃないか! どこから手に入れた? BarrensのVenture Companyを探り回ってるのか?\n\nあんた、とんでもなく勇敢か、でなきゃとてつもないバカだな。", 0x4f8af447, 0x451916dc, 0xf87c0604, 0xe6681672, 0xdb24502b, "....." },
  [3924] = { "Samophlange Manual", "Samophlange ManualをOrgrimmarのRilli Greasygobに渡して下さい。", "samophlangeは直せると思うが、まずは取扱説明書が必要だ。Venture Companyにいた頃、俺にはライバルがいてな、Boss Copperplugって奴だ。そいつはsamophlangeの秘密を独り占めして、信用する連中にだけ、その装置の知識をちょっとずつ分け与えてた。俺はその信用された一握りには入ってなかった……\n\nBoss Copperplugは、Barrens北東部のBoulder Lode Mineにいたもんだ。そいつから説明書を手に入れてくれ。それと、もし奴が誰かにそのページを渡してたら、それも集めてもらわなきゃならない。", "manualは持っているか?", "マニュアル手に入れたのか! 読んでSamophlangeの直し方を調べるのが待ちきれないよ! RatchetでSputtervalveと話したんだけど……あいつ、あんたが助けてくれたことに感謝しててさ、お礼したがってたぜ。\n\nオレもあんたには感謝してるよ。今度これを修理したら、知らせるよ……", 0x414249b4, 0x7dc1529a, 0xbe65b209, 0xfd8a38a1, 0xd5013a6b, "....." },
  [3941] = { "ノームの助力", "Marshal's Refugeの洞窟にいるJ.D. Collieを見つけて下さい。", "考え中……考え中……何か大事な用があってここに来たはずなんだけど……\n\nいい考えがあるよ、{name}。あそこの洞窟に、J.D.っていうノームがいてね。僕がここに着いたばかりのころ、とても親切にしてくれたんだ。もしかしたら、頭が混乱してたときに、彼女に何か話したかもしれない。\n\n何か知らないか聞いてきてくれない？あ、でも気をつけて――彼女はいつもクレーターで見かけるあの妙な光る結晶をいじくり回してるんだ。あそこで何をしてるのか、僕にはよく分からないよ！", nil, "少しだけそこを動かないでくれ……新しい水晶の組み合わせを試しているところなんだ……", 0x40816cd9, 0xfd9339a6, 0x646068c0, nil, 0xc7a0f8a8, "...m." },
  [3942] = { "Linkenの記憶", "Felwood南部でEridan Bluewindを見つけて下さい。", "え……Linken？うん、あの人は面白い人だよ。ここに来たばかりのころは、いろんな変なことをぶつぶつ言ってたんだ。たぶん頭をかなり強くぶつけたんじゃないかな。\n\nでも、あの人が言ったことで一つ気になってることがあって――何かのトーテムを作ってるって言ってたんだ。Eridan Bluewindっていう人と話さなきゃって……Felwoodっていう場所だったと思うけど？\n\n今のあの人じゃ、たいしたことは話せないと思うな。もっと知りたいなら、自分でEridanを探してみたら？", nil, "こんにちは、{class}。何か手伝えることはあるかな？", 0xb545690b, 0x4a17c137, 0x47f4f6e6, nil, 0x0fd9739c, "...m." },
  [3961] = { "Linkenの冒険", "Silver Totem of AquementasをMarshal's RefugeのLinkenのところへ持って行って下さい。", "Linkenがここへ来たのは、ずっと私たちをBlazerunnerから救うためだったなんて……本当に普通の人に見えるけど、たいていのノームと違って、私の実験や道具にまるで興味がないことには気づいてたの。きっと心の底から本物のウォリアーなのね。\n\nそのトーテムを彼のところへ持っていって。ここへ来た理由を思い出す助けになるか確かめてみて。", "やあ、また会ったね、{name}!", "J.D.は少しは役に立ったかい？", 0xe96fc353, 0x37cbdaf9, 0x77ae9d2a, 0xb9979763, 0x9e32cb12, "....." },
  [3962] = { "一人で行くのは危険だ", "Marshal's Refugeの南にあるFire Plume Ridgeへ行く。\n\nBlazerunnerを見つけ、トーテムを使って彼を守るオーラを取り除いて下さい。彼を倒したら、洞窟からGolden Flameを手に入れて下さい。", "{name}、ようやく思い出したよ……僕は確かに、Blazerunnerと戦うためにここへ来たんだ。旅の途中で、これが最後の一歩になるはずだった。\n\nでも、僕はもう英雄じゃない……君が英雄だ。君がやってきたこと全部――これを終わらせるのは僕じゃなく、君なんだ。\n\nBlazerunnerはGolden Flameという遺物を守っている。それは僕が知る何よりも大きな力をもたらすもので、邪悪な心を持つ者の手に渡れば危険なんだ。\n\n誰か仲間を連れていきたくなるはずだ――一人で行くのは危険だ。この言葉を持っていってくれ。", "BlazerunnerはGolden Flameを使って作り出したオーラに守られ、ほとんど無敵です。Silver Totem of Aquementasでそれを取り除く力を持つのは、あなただけです。", "ありがとう、{name}。\n\nGolden Flameはこれから私の故郷へ戻され、そこで守られることになる。二度と悪のために使われることはない。\n\n君がいなければ、今でも自分が何者なのか分からないままだった！これほど尽くしてくれたのだから、何か特別なものを受け取ってほしい……\n\n好きなものを1つ選んでくれ！", 0x9d699a86, 0xa69128f0, 0xd9c5c47b, 0xf5ce54e8, 0x6e1f34a9, "....." },
  [3981] = { "Commander Gor'shak", "Blackrock DepthsでCommander Gor'shakを見つける。\n\n粗雑に描かれたあのオークの絵には、肖像の上に格子が描き込まれていたことを思い出す。何かの牢獄を探すべきかもしれない。", "かわいそうなGargal……気づきもしなかった。ドカン! 矢が頭のてっぺんのど真ん中に突き刺さったんだ。前から天才ってわけじゃなかったが、今じゃ……\n\n<Galamavは顔をしかめる。>\n\n矢を引き抜いたら、矢柄に丸めた手紙が結びつけてあるのに気づいた。その手紙には、檻の中にいるオークの下手くそな絵が描いてあって、Commander Gor'shakの署名が添えてあった。\n\n奴がまだDepthsで生きているなら、お前が見つけ出さなきゃならん。\n\n罠だって? ああ、当たり前だろうが、この間抜けな蹄野郎! だからお前が行くんだよ!", nil, "あまり時間がない。よく聞いてくれ、{race}。お前に言うことは極秘だ、お前だけに話す。", 0x8c469204, 0xa1275b64, 0xdcabb55c, nil, 0x9dc26c99, "...m." },
  [3982] = { "何が起きている?", "Gor'shakを攻撃から守って下さい。", "俺はThrallの命を受けてここへ送られた。この間抜けどもに俺が捕まえられると本気で思うか? 情報を集めるために、わざと捕まったのさ。\n\n<Gor'shakがささやく。>\n\nIronforgeの王女が、Emperor Thaurissanにさらわれた。Princess Bronzebeardはまさにこの都にいるんだ! その知らせを聞いたとき、Magniの親父さんの心臓は止まりかけただろうな。\n\n<Gor'shakが笑う。>\n\nシーッ! 聞こえるか? 衛兵が来るぞ! 身を守れ!", "身を守れ、愚か者め!", "間一髪だったな。奴ら、お前に気が付いていたのだ……間違いなく、もっとやって来るだろう。", 0x6bdf65cd, 0xf461bb19, 0xa2f68f6a, 0xcc8ab8cb, 0x99acc367, "....." },
})
